/* 令和6年委員会データ（自動生成・分割ファイル） */
window.SHINAGAWA_DB.years.r06.committeeSessions.push(...[{"id":"r06-20240307-3","meetingId":"r06-c-budget","date":"2024年3月7日","dateIso":"2024-03-07","committee":"予算特別委員会","time":"午前１０時００分～午後 ６時１１分","status":"正式会議録","sourceType":"formal","overview":"予算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を187件整理しています。","topics":[{"id":"topic-01","title":"予算特別委員会","agenda":"予算特別委員会","exchanges":[{"speaker":"えのした委員","kind":"質問","question":"私からは、２０９ページ、しながわシティランについてお伺いします。しながわシティランもちょうど１年後と近づいてまいりましたが、まずは予算についてお伺いします。","respondent":"三井スポーツ推進課長","answer":"しながわシティランの予算の主なものとしましては、実行委員会の負担金となっておりまして、そのうち主要なものとしては、大会運営費が約２,５００万円、警備費などの安全対策費用が約４,０００万円となっております。","id":"exchange-001"},{"speaker":"えのした委員","kind":"確認","question":"そこでお伺いします。そこで、日々地域の安心・安全のために活動されている消防団の方に、警備等をご協力していただくことはいかがか尋ねました。","respondent":"三井スポーツ推進課長","answer":"配置するスタッフの人数など、詳細はこれからになりますが、消防署にも今後協議を進めていく段階になっております。その際に、消防団の協力の依頼ができないかなど、そのようなことについてもご相談しながら検討してまいりたいと思います。","id":"exchange-002"},{"speaker":"えのした委員","kind":"質問・要望","question":"ぜひ消防署、消防団の協力依頼を要望いたします。大会ホームページの公開も含めて、いつ頃を予定されているのかお知らせください。","respondent":"三井スポーツ推進課長","answer":"大会ホームページについては現在作成しているところですが、申込み開始時期は令和６年の９月を予定しております。","id":"exchange-003"},{"speaker":"えのした委員","kind":"確認","question":"確認が取れました。大会要項についてお伺いいたします。","respondent":"三井スポーツ推進課長","answer":"参加資格は、他の大会を参考にしています。今回コース上の設定状況も踏まえまして、障害者支援課とも相談しながら検討を行いまして、１２月の実行委員会で決定いたしました。","id":"exchange-004"},{"speaker":"えのした委員","kind":"確認","question":"約８km付近ですか、大井ふ頭中央海浜公園の陸上競技場、大井ホッケー競技場にコースが見直されております。こちらは、競技場の中、または競技場の外、外周を走ることになるのか尋ねました。","respondent":"三井スポーツ推進課長","answer":"今回、オリンピックレガシーである大井ホッケー競技場の中を走ることで、ランナーがふだん走ることができないコース設計とさせていただきました。","id":"exchange-005"},{"speaker":"えのした委員","kind":"質問・要望","question":"競技場の中と確認が取れました。例えば電光掲示板などを利用した雰囲気を盛り上げる仕掛け、当日は競技場内やスタンドにも、応援する方が入れるような取組も要望します。","respondent":"三井スポーツ推進課長","answer":"ロゴマークの公募の総数になりますが、約１４０件となっております。会長である区長を含む５名を選定委員としまして、推薦作品の中から選定委員会で協議しまして、決定いたしました。","id":"exchange-006"},{"speaker":"えのした委員","kind":"質問・要望","question":"もしくは、どちらか一方の会場で開催されるのでしょうか。品川区民デフリンピック１００％周知啓発の取組など、区のご見解をお知らせください。","respondent":"三井スポーツ推進課長","answer":"大井競馬場については、これから利用方法などを検討していく予定になっております。しながわシティランの会場内でも啓発ブースの出展ができないかなと、そのような様々な方法を考えてまいりたいと思います。","id":"exchange-007"},{"speaker":"えのした委員","kind":"質問・要望","question":"皆様の動線、また、安全性も踏まえての取組を要望いたします。続いて、１年前記念イベントについてお伺いします。","respondent":"三井スポーツ推進課長","answer":"今週末に実施いたします、機運醸成として考えている１年前記念イベントの応募状況ですが、ファミリーの部が約１７０名弱の応募となっております。来年度の大会のＰＲや気運醸成につきましては、どのような方法があるのか、今後実行委員会を含めて検討してまいりたいと思います。","id":"exchange-008"},{"speaker":"えのした委員","kind":"質問・要望","question":"ファミリーの部約１７０名、応募多数とのことですので、ぜひ今後も幅広い年代、また、幅広い地域での開催を要望します。区内に銭湯は２０軒以上ありますので、まちぐるみでの盛り上げが重要だと考えますが、区のご見解をお知らせください。","respondent":"三井スポーツ推進課長","answer":"しながわシティランを活用して、関係団体と連携したデジタルスタンプラリーができないか等のご相談もいただいているところです。これを機会に、様々な団体の方にしながわシティランを活用していただき、品川区全体で取り組んでまいりたいと思います。","id":"exchange-009"},{"speaker":"えのした委員","kind":"質問・要望","question":"区民、ランナー、ボランティア、応援等、様々な形で多くの方に参加していただき、オール品川でみんなが輝く大会の開催を要望いたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-010"},{"speaker":"ゆきた委員","kind":"確認","question":"私からは、２０１ページの歩行喫煙防止推進経費、１７７ページの区施設営繕事務費についてお伺いしてまいります。１日当たり平均で、少ないところでも２００本、多いところでは１,５００本の吸い殻が回収されていることが確認できています。","respondent":"河合生活安全担当課長","answer":"どのように対応してきたかですが、そして、シルバー人材センターによる声かけ活動などを通じてやってきております。丁寧に対応することで、そこの環境を浄化する、よくするというところで力を入れてきております。","id":"exchange-011"},{"speaker":"ゆきた委員","kind":"確認","question":"確認させていただきました。路面標示では、たばこ禁止の図柄と一緒に、喫煙禁止の横に括弧書きで「過料１,０００円」と表示されているものも確認しました。","respondent":"河合生活安全担当課長","answer":"路上喫煙禁止・地域美化推進地区におけます表示物の貼付状況ですけれども、数、場所について、詳細については把握しておりません。その場でも対応しておりますので、まちの景観等も踏まえて、効果が上がるように貼付しています。","id":"exchange-012"},{"speaker":"ゆきた委員","kind":"質問・要望","question":"私も、五反田、大井町、武蔵小山、青物横丁、大崎等で、全部で８か所確認させていただきました。これも要望があったところということで、やっていただいているということを確認させていただきました。","respondent":"河合生活安全担当課長","answer":"所管の機関等、ご意見に対応するところは調整が必要ですので、そういったご意見は踏まえていきたいと考えております。聴覚的に入るように、マイク広報等も積極的に行っておりますので、そういったところを含めてやっていきたいと考えます。","id":"exchange-013"},{"speaker":"ゆきた委員","kind":"質問","question":"捨てる場所がない、これはもう完全にモラルによるところですけれども、そこをどのように後押ししていくかが非常に重要な課題だと思います。そこで、たばこを吸う場所の整備、喫煙所の整備、拡充をどのように進めていくのか、区の見解をお聞きしたいと思います。","respondent":"河合生活安全担当課長","answer":"委員ご指摘のとおり、ポイ捨ての抑止につきましては、やはり喫煙所の整備というものが重要だと考えております。来年度に路上喫煙の実態調査等を行いますので、民間喫煙所への助成、そういったところを進めていきたいと考えております。","id":"exchange-014"},{"speaker":"ゆきた委員","kind":"質問・要望","question":"同時に、令和４年の調査結果からは、区内の指定喫煙所がある駅でも、数多くの吸い殻が回収されていることが確認できています。要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-015"},{"speaker":"山本委員","kind":"質問","question":"１７７ページの情報システム運営費、２０３ページの都市型観光プラン推進事業、２１３ページのふるさと納税事業について伺います。ＳＤＧｓ推進経費に関連して伺います。","respondent":"吉岡政策推進担当課長","answer":"産学官が連携いたしまして、多様な区民ニーズに対応し、区民のウェルビーイングの向上を図るという事業です。企業等からも協賛金、寄附金という形で出資を募ることとし、区だけの予算に限らないサステナブルな運営を目指すというような事業です。","id":"exchange-016"},{"speaker":"山本委員","kind":"質問・要望","question":"投資や融資のファンドのように、持続可能な本格的なファンドを目指してはいかがでしょうか。区のお考えを伺います。","respondent":"吉岡政策推進担当課長","answer":"ご案内の東京都の自治体が実施している複数のファンド事業も、把握しています。来年度実施をしていく中で、しっかりと効果検証を行いつつ、検討を深めてまいりたいと思います。","id":"exchange-017"},{"speaker":"山本委員","kind":"質問・要望","question":"令和６年度の本ファンドの実施に併せ、その中で投資や融資の本格ファンドへの可能性を検討していただくことを要望いたします。１,６６１の手続きに対して、令和５年度に５００件程度を実施できる見込みとお聞きしておりますが、令和６年度末までの達成目標は何件か尋ねました。","respondent":"河西情報戦略担当課長","answer":"行政手続きのオンライン化に関する目標についてお答えいたします。令和６年度の目標は９００手続きになります。","id":"exchange-018"},{"speaker":"山本委員","kind":"質問","question":"それぞれの手続きをオンラインサービスへ移行するには、具体的に誰がどのように対応するのでしょうか。お教えください。","respondent":"河西情報戦略担当課長","answer":"このシステムはオンライン決済にも対応し、簡単に手続きの受付フォームを作成できるシステムになります。研修やマニュアルを通して手続きの作成方法を習得いただき、情報推進課が支援しながら、手続きのオンライン化を進めております。","id":"exchange-019"},{"speaker":"山本委員","kind":"質問","question":"１,６６１件の案件管理、台帳管理はできているのでしょうか。令和７年度までに手続きオンライン化の目標は達成できそうか尋ねました。","respondent":"河西情報戦略担当課長","answer":"委員のおっしゃるとおり、令和７年度末までに全ての手続きをオンライン化することを考えると、前倒しの検討が必要になると考えます。定期的に所管と状況を確認し、オンライン化できるよう進めてまいります。","id":"exchange-020"},{"speaker":"山本委員","kind":"質問・要望","question":"次に、都市型観光プラン推進事業について伺います。都市型ツアーの取組についてはいかがか尋ねました。","respondent":"篠田文化観光課長","answer":"都市型観光ツアーのお尋ねです。今年度の実施例で申し上げますと、そういったものを実施いたしまして、参加した皆様方からは大変好評をいただいているところです。","id":"exchange-021"},{"speaker":"山本委員","kind":"提案","question":"実際の企画はしながわ観光協会が進めることとなると思いますが、ぜひとも後押しをしていただけないでしょうか。区のお考えを伺いますとの意見を述べました。","respondent":"篠田文化観光課長","answer":"ただ、委員からもご指摘がございましたとおり、実施、運営するに当たってはしながわ観光協会が様々関わってくるのだろうと思います。そういった点も踏まえまして、今後の展開の可能性について研究してまいりたいと思います。","id":"exchange-022"},{"speaker":"山本委員","kind":"質問","question":"より多くのことを考えて実現するために、アイデアを地元企業の方々や区民の皆様に募集するということがよいのではないでしょうか。区のご意見を伺います。","respondent":"提坂税務課長","answer":"逆に諸団体に対して、新たな返礼品選定を含む様々なご協力の依頼も行っているところです。令和６年度からは、様々な体験型・参加型の返礼品をさらに拡充してまいりますけれども、研究を行ってまいります。","id":"exchange-023"},{"speaker":"山本委員","kind":"質問・要望","question":"地元企業の方々にもお声がけしていただいたり、区民の方にもお声がけしていただいて、広がりをつくってほしいと求めました。応募するインセンティブを高めるため、企業や採用された方には特典を用意することを要望して終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-024"},{"speaker":"安藤委員","kind":"質問","question":"１８３ページ、１８５ページ、２０３ページなどを伺います。伺いますけれども、現在のところこの訪問を想定している平和関連施設とは、どの辺りを考えていらっしゃるのか伺いたいと思います。","respondent":"勝亦総務課長","answer":"非核平和都市品川宣言４０周年記念事業につきまして、訪問先、事業等につきましては、今現在検討しています。","id":"exchange-025"},{"speaker":"安藤委員","kind":"質問・要望","question":"この今のふだんの自分たちの生活の、歩いているそのまち並みの中に地続きだということを実感する上では、それらも大切なことなのではないでしょうか。伺いますけれども、区内の戦争史跡にスポットを当てるための何らかの取組を求めたいのですが、いかがか尋ねました。","respondent":"勝亦総務課長","answer":"非核平和都市品川宣言４０周年の記念に当たりまして、ご提案いただきました。どのような形で区民の方に、こういった非核平和都市４０周年を伝えていけばいいのか、様々考えていきたいと思います。","id":"exchange-026"},{"speaker":"安藤委員","kind":"質問","question":"そのような認識は区におありでしょうか。伺いたいと思います。","respondent":"勝亦総務課長","answer":"区民の方に平和、文化、そういったものをお伝えしていくことが務めだと考えています。それが、今委員がおっしゃった世論の形成につながったかどうかということは、判断できない部分です。","id":"exchange-027"},{"speaker":"安藤委員","kind":"質問・要望","question":"ぜひ判断するところ、そのような認識を持ってほしいのです。４０周年を迎えるこの年、区内外に核兵器禁止条約への支持を表明していただきたいと思うのですけれども、ぜひご答弁いただけたら幸いです。","respondent":"勝亦総務課長","answer":"そういった恒久平和に対する思い、こちらのほうは強く、区民の方に広く伝えていくものであると考えています。ただ、今おっしゃった条約等に関しましては、外交に関する部分ですので、国等の判断、責任なのかなと考えています。","id":"exchange-028"},{"speaker":"安藤委員","kind":"質問・要望","question":"度々私たちも加盟を求めてきたのですが、設立趣旨として、「世界恒久平和の実現に寄与することが自治体に課せられた重大な使命である」。ぜひこの日本非核宣言自治体協議会へ参加するよう求めたいのですけれども、いかがか尋ねました。","respondent":"勝亦総務課長","answer":"こちらが、今国内では１,７００以上の自治体が加盟している、広い取組になってあります。その中で、核兵器廃絶や世界恒久平和の実現を訴え続けるという趣旨に賛同いたしまして、品川区としてはそういった活動をしています。","id":"exchange-029"},{"speaker":"安藤委員","kind":"質問・要望","question":"人権が及ばない公共空間が区内に存在するということについてどう考えるのでしょうか、伺いたい。現実に苦しめられている、人権侵害が横行しているということについてどう考えていらっしゃるのか、ぜひお考えを聞かせてほしいと求めました。","respondent":"勝亦総務課長","answer":"ただ、今ご紹介いただいたような案件が人権侵害に当たるかどうか、こちらのほうの判断については法務省の人権擁護局等になろうかと思います。できない部分がありますので、そこについては今、治外法権等にはお答えしかねる部分があります。","id":"exchange-030"},{"speaker":"安藤委員","kind":"質問・要望","question":"なぜ宣言をしている区がそのようなことを言えないのか、本当に尊重しているのでしょうかと疑いたくなってしまいます。もう１回、これは人権侵害でしょうとズバっと言っていただきたいのですが、。","respondent":"勝亦総務課長","answer":"具体的に品川翔英というようにお名前が出てまいりました。まず一義的に、学校内の問題は学校内、東京都の管轄下になるかと考えております。","id":"exchange-031"},{"speaker":"安藤委員","kind":"質問","question":"ですから、大人の責任としても、ちょっとどうなのかと。私は、私たち全体がこれは自分の問題と受け止めるべきだと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-032"},{"speaker":"筒井委員","kind":"質問・要望","question":"施設予約システムの改善を求めていきたいなと思っておりまして、３年前この予算特別委員会で改善を求めたところ、ぜひよろしくお願いします。ＸとＩｎｓｔａｇｒａｍの扱い、品川区ホームページのトップページに、どのようにして掲載するのかについてお伺いいたします。","respondent":"横田情報推進課長、辻広報広聴課長","answer":"全ての画面において横スクロールが発生しない設計とする予定になっております。高齢者、障害者を含むより多くの利用者が使えるためのアクセシビリティ基準、ＡＡに対応するような対応になっております。もともとＴｗｉｔｔｅｒ社のときは、Ｘに変わってから、その連携がどうもうまくいっていない。","id":"exchange-033"},{"speaker":"筒井委員","kind":"質問・要望","question":"ブランディングという言葉に統一、一本化していくのか、その辺りをお伺いいたします。広報広聴課に、そのシティプロモーション担当という担当名も、当然変更されるのかどうかをお聞きします。","respondent":"辻広報広聴課長","answer":"しながわ」ということを合い言葉に、８年近く続けてまいりました。今回組織改正がありますけれども、その中で、今度は都市ブランディング担当という名前に変更になります。","id":"exchange-034"},{"speaker":"筒井委員","kind":"意見","question":"環境も進んでいる、福祉・子育てに力を入れている、その事業がすばらしいということもあるかと思います。どのように可視化ということをやっていくのか、お知らせくださいとの意見を述べました。","respondent":"辻広報広聴課長","answer":"ブランディングの進め方ということかと思います。それを可視化するということが１つと、また事業者と一緒に考えながら、何か収れんしていくのではないかなと考えています。","id":"exchange-035"},{"speaker":"筒井委員","kind":"提案","question":"ちょっと確認したいのですけれども、これからどうしていくのか、かなり明確化していっていただきたいと考えております。ですから、運用も丁寧にしていっていただきたいのですけれども、その点いかがお考えか尋ねました。","respondent":"加島人権啓発課長","answer":"こちらにつきましては、区のほうで目指す社会を実現するために、区民、事業者等のお力を借りなければというところで定めたものです。決して強制にならぬよう、区のほうで啓発に力を入れてまいります。","id":"exchange-036"},{"speaker":"せらく委員","kind":"質問","question":"こちらは５月ですか、あと利用の多いものを集めて、直感的で分かりやすいトップページになるということをご説明いただきました。今ページ遷移が結構多く、操作性の向上がされるといいのではないかと思いますが、こちら伺いたいと思います。","respondent":"崎村人事課長、横田情報推進課長","answer":"実績としては４４９件だったのですが、今年度は１２月までで、同じく４４９件というような状況です。効果といたしましては、職員の健康管理、健康増進を図るといったところで、大変効果があるものというように認識しております。 ２画面目で施設名称を検索、３画面目で場所を選択して、画面展開の手間がございました。１画面目で日時、時間を全て選択できるようになり、より使いやすいシステムとなる予定です。","id":"exchange-037"},{"speaker":"せらく委員","kind":"質問","question":"次に、この予約システムの利用登録について伺います。システム上で登録できるようにするか、電子申請を利用することによって利用者の利便性が上がると思いますが、今後の方向性を説明を求めました。","respondent":"横田情報推進課長","answer":"これまでは施設に出向いていただきまして、団体登録をする必要がございました。新施設予約システムにつきましては、システム公開に合わせまして、品川区電子申請サービスで団体登録ができるように検討しております。","id":"exchange-038"},{"speaker":"せらく委員","kind":"質問・要望","question":"例えば聞いた話ですと、保育園の発表会のお疲れさま会だとか、卒園の集まりなどを個人で地域センターを予約して取っているということがありました。そういった利用の場合は団体という形ではないと思いますので、個人でも利用しやすいような登録もぜひ進めていただきたいのですが、いかがか尋ねました。","respondent":"宮澤地域活動課長","answer":"集会所、地域住民の集会ということですので、いわゆるお一人での、個人での利用というものはできません。ただ、複数の方でご利用いただく場合には、団体登録ということでお願いしています。","id":"exchange-039"},{"speaker":"せらく委員","kind":"質問","question":"次に、区民相談室について伺いたいと思います。専門相談のほうの利用状況もお願いいたします。","respondent":"辻広報広聴課長","answer":"区民相談室についてのご質問にお答えいたします。法律相談が１,０３７件、それから税金相談が１８８件、そういった状況になっております。","id":"exchange-040"},{"speaker":"せらく委員","kind":"質問","question":"近くに数人住んでいらっしゃって、１人だから先のことを誰にも相談できない、距離がおっくうで役所まで行けないということをお聞きしました。そのような中で、すごく寄り添った区民サービスになると思うのですが、この地域センターへの出張という形で相談することについてはいかがか尋ねました。","respondent":"辻広報広聴課長","answer":"相談される方は、やはり６０代以上のご高齢の方、７０代がメインというようになっております。そういったことも考えながら、区民のそういった声もいただいて、また今後考えていきたいと思います。","id":"exchange-041"},{"speaker":"せらく委員","kind":"確認","question":"事業評価のほうを確認いたしますと、オンラインの研究を進める方向であるということが記載されていました。ご検討の状況や、相談の受付からの流れについて、決まっていることがあれば説明を求めました。","respondent":"辻広報広聴課長","answer":"様々検討、研究、他区の状況なども調べさせていただいているところです。若干他区のほうも、それほど利用状況はあまりよくないということで、今のところはまだ、いろいろなところの状況を注視しながら考えているところです。","id":"exchange-042"},{"speaker":"せお委員","kind":"質問","question":"私からは１９３ページ、働き方改革推進事業、２０１ページ、生活安全推進事業についてお伺いします。そういったことも大切だなと、３年目ぐらいですか、やっと分かりました。","respondent":"勝亦総務課長、田口人材育成担当課長、佐藤経理課長","answer":"ハラスメント対応窓口ということで、外部弁護士にも相談ができるような体制を現在取っているところです。内外コンプライアンスを含めて… 来年度から、新たにハードクレームに対応するために、弁護士による研修を実施いたします。弁護士の法的な知識による講義に加えまして… 予算書でいきますと１７９ページ、現在も取り組んでいる内容ではありますが、警備に関する委託の部分があります。","id":"exchange-043"},{"speaker":"せお委員","kind":"提案","question":"マニュアルなども、時代に合ったものに改善していただいたりとか、そういったことも含めてこれから取り組んでいただきたいと要望したいと思います。予算計上してあるということであれば教えていただきたいということと、もし計上していないなら、それはなぜか説明を求めました。","respondent":"宮澤地域活動課長","answer":"来年度予算ですと、２０３ページの上段にあります、社会を明るくする運動経費の中に、再犯防止に関する経費というものが含まれております。犯罪、非行、または再犯に陥らないようにというところで、各種団体の皆様と一緒に取り組む、この運動の中に経費を入れております。","id":"exchange-044"},{"speaker":"せお委員","kind":"質問・要望","question":"同じ会派のえのした委員とも、刑務所などを訪れると、やはり課題がどうしても国のほうが表れてくるなということは感じています。要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-045"},{"speaker":"横山委員","kind":"質問・要望","question":"今年２月、私はあーとま塾２０２３のステップ２において、評価的思考がもたらす変革と地域社会への影響についてお話をお伺いしました。区民とともに社会的価値をつくり、新たな公共マーケットを創出いただきたいと要望いたしますが、区のお考えを説明を求めました。","respondent":"田口人材育成担当課長、吉岡政策推進担当課長","answer":"明治大学の源教授をはじめまして、３名の大学教授の先生にご協力いただきまして、実施を予定しております。まず今回の、来年度に実施するものにつきましては… 区のほうで今年度実施いたしました行政評価のうち、区民や有識者等から成る外部評価委員会を設置いたしまして、提言をいただいたところです。","id":"exchange-046"},{"speaker":"横山委員","kind":"質問・要望","question":"２点目に文化コミュニティ施設経費についてお伺いいたします。昨年１２月に、映画『記憶２ 少年たちの追憶と贖罪』の中村すえこ監督にお話を伺いました。","respondent":"篠田文化観光課長、宮澤地域活動課長","answer":"各団体が行っている事業に関してもご支援をさせていただいておりまして、様々な形で機会を提供し、区民へのアプローチを図っているところです。様々な幅広い支援に取り組んでいるということもありますので… これまでも保護司会を中心に、各種団体と連携しながら、社会を明るくする運動ということで、例年７月に街頭広報活動などを進めてきたところです。","id":"exchange-047"},{"speaker":"新妻委員","kind":"質問","question":"２１７ページ、２１９ページ、支援についてお伺いします。昨年の１０月の決算特別委員会で、新年度予算の中にどのように反映されたのか、お伺いいたします。","respondent":"小林施設整備課長","answer":"全体で３１施設ありますが、そういったところが未設置の施設に対しまして、２年間かけて整備のほうを進めていくところです。工事につきましては、各施設所管のほうの、例えば運営費の中に、それぞれ予算が振り分けられているといったところです。","id":"exchange-048"},{"speaker":"新妻委員","kind":"質問・要望","question":"この授乳室の安全対策、しっかり予算に反映されていることが確認されました。多くの施設があると思うのですが、どの施設につけられるのか、２か年計画ということですけれども、施設名をお知らせほしいと求めました。","respondent":"小林施設整備課長","answer":"緊急呼出しボタンがつけられていない施設が、現在２６施設ありますので、これを２か年かけて整備をしていくところです。２６施設全てというお話かと思いますので、図書館では複数施設で予定されるなど、多くの施設で整備のほうをしていく予定です。","id":"exchange-049"},{"speaker":"新妻委員","kind":"質問・要望","question":"３２か所ですか、３２か所が整備されるということで、安心に思います。既に児童センターは整備がされているということで、ここは確認させてほしいと求めました。","respondent":"小林施設整備課長","answer":"これを兼用している施設ですが、そこの中に、やはり呼出しボタンのほうは整備させていただいているところです。今後児童センター等で、授乳室等を設置する施設につきましても、逐次設置のほうは進めてまいりたいと考えているところです。","id":"exchange-050"},{"speaker":"新妻委員","kind":"質問・要望","question":"続きまして、八潮地区まちづくり事業についてお伺いいたします。本年度は５７５万円余ということで、昨年度より大幅増の予算がつけられておりますので、この事業内容をお聞きしたいと思います。","respondent":"中西八潮まちづくり担当課長","answer":"八潮地区まちづくり事業の予算の内容といったところのお尋ねです。公表されましたまちづくりガイドラインの考え方等を踏まえまして、コンセプトを検討する委託ということで、５５０万円を計上しています。","id":"exchange-051"},{"speaker":"新妻委員","kind":"質問・要望","question":"このまちづくりの業者委託、こちらのほうにかなり予算がついたというように確認させていただきました。そしてもう１点、まちづくりの検討の中でのガイドラインとの関連を少しお伺いしたいと思うのですが、どのようにそれが関連づけられて。","respondent":"中西八潮まちづくり担当課長","answer":"様々地域の方とお話をする中でも、いただくご意見、かなり重なる部分が多くあります。業者とも連携、情報共有しながら、進めてまいりたいと考えています。","id":"exchange-052"},{"speaker":"新妻委員","kind":"質問・要望","question":"続きまして、おくやみコーナーにつきまして確認します。昨年の第３回定例会の中で、おくやみコーナーの質問をさせていただいた中で、現在検討されている状況をお知らせほしいと求めました。","respondent":"吉野戸籍住民課長","answer":"大分小さなハンドブックでしたので、これからは少し大きくしまして、見やすい内容にしようと思っています。それから、当然大きくなりますので、いろいろな情報も加味していきたいと考えております。","id":"exchange-053"},{"speaker":"新妻委員","kind":"質問・要望","question":"そのようなページもあるといいかなと考えていますので、このようなこともぜひ改編してほしいと求めましたが、見解を伺います。１点お伝えし忘れましたが、ぜひそのような工夫もお願いしたいと思いますが、いかがか尋ねました。","respondent":"吉野戸籍住民課長","answer":"今の委員のご指摘のとおり、分かりやすいものをつくっていきたいと考えております。ホームページのほうも修正したいと考えております。","id":"exchange-054"},{"speaker":"新妻委員","kind":"質問・要望","question":"昨年の、これも決算特別委員会ですけれども、この投票支援ということで、支援カードの作成について要望させていただきました。その中に自分が何の支援が必要なのかということを書けるような用紙を封筒の中に入れてほしいということを要望させていただいたのですが、今。","respondent":"鈴木選挙管理委員会事務局長","answer":"ご指摘の投票支援カードについて、現在、今年７月の都知事選挙に向けて、検討しています。区の施設でもお渡しできるような方法、トータルで支援が必要な方に支援が届けられるような形で、今検討しています。","id":"exchange-055"},{"speaker":"新妻委員","kind":"質問・要望","question":"封筒で送っていただきたいなという思いがありますけれども、確実にその支援が必要な人が、そのような体制をしっかり整えてほしいと求めました。どうぞ。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-056"},{"speaker":"おぎの委員","kind":"質問","question":"本日は２０７ページ、歴史館運営費、イベントやＰＲ活動全般について、２０９ページ、地域スポーツ等推進経費についてお伺いします。品川歴史館が工事を終えて、４月にリニューアルオープンしますが、広報の方法やリニューアルオープンのイベント内容はどのようなものか尋ねました。","respondent":"篠田文化観光課長","answer":"品川歴史館、大規模な改修工事を今進めてございまして、基本的に今年度、この３月いっぱいで全て終了するというような予定です。リニューアルオープンとしての式典を実施するということで、そのほか、そういったことにも取り組んでいくといったことを考えているところです。","id":"exchange-057"},{"speaker":"おぎの委員","kind":"確認","question":"運営を進めながらというお言葉を確認いたしました。歴史・文化を主軸にした人の流れを、この品川区中につくっていけるといいなと思っていますが、いかがか尋ねました。","respondent":"篠田文化観光課長","answer":"品川の伝統文化とのコラボレーションといったお尋ねかと思います。今後様々な企画を実施していく中で、そういった視点も含めたものが取り入れられるかどうか、検討してまいりたいと考えています。","id":"exchange-058"},{"speaker":"おぎの委員","kind":"質問・要望","question":"この後、品川区民や区内の事業者が参加できる公募のコンペなどを増やすことで、見解をお聞きしたいと思います。仕事もお金も品川区内で循環させることが、持続可能な地域の発展につながると考えますが、いかがでしょうか、見解をお伺いします。","respondent":"辻広報広聴課長","answer":"各所管がいろいろな形で、プロポーザルという形で、いろいろな事業を公募するということもあります。そういった中で、そういった方をうまく起用できるように、私どものほうは情報提供等はしていきたいなと考えています。","id":"exchange-059"},{"speaker":"おぎの委員","kind":"質問","question":"地域の方が誰でも気軽に参加でき、区民の方の健康維持のために、地域スポーツの枠組みでラジオ体操の団体の方を支援していくことはいかがでしょうか。見解をお聞きします。","respondent":"三井スポーツ推進課長","answer":"スポーツ推進課では、しながわ体操をやっておりまして、一応そちらについては普及の出前を、１回当たり参加者約２０人というような形で、そのような体操の普及啓発等をしています。","id":"exchange-060"},{"speaker":"おぎの委員","kind":"質問・要望","question":"こちらは要望です。今後、品川の文化も健康も、行政として進めていってほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-061"},{"speaker":"こしば委員","kind":"質問","question":"２０３ページのハタチの龍馬ＰＲ事業、また２０５ページ、１８５ページの外国人学校児童生徒等保護者補助金についてお伺いします。そのような中で、まず冒頭お聞きしますが、品川の名産、品川といえば何があるのか尋ねました。","respondent":"篠田文化観光課長","answer":"なかなか取れなかったりということがあったりするものですから、現実に今あるものとしての名産というものが、なかなか見つけづらいのかなといったところが率直なところです。","id":"exchange-062"},{"speaker":"こしば委員","kind":"質問","question":"その１つがマンホールのデザインであったり、それを証明する投票済証、そういったことにもシナモロールは活用されてきたかと思います。特にマンホールデザインもそうでしょう、また投票済証もそうだと思いますが、どのような効果があったのか説明を求めました。","respondent":"篠田文化観光課長","answer":"シナモロールの効果についてです。平成２９年からお願いをしているということで、必ずマニアの方というか、我々としてもとてもありがたい存在であると感じているところです。","id":"exchange-063"},{"speaker":"こしば委員","kind":"質問","question":"大変ありがたいという言葉、伺いましたけれども、たくさん人が来るということは、それは大変すばらしいことだと思うのですが、この観光大使の活用によって、今度は区民が得られる利益、幸せ、ウェルビーイングという言葉でもありますけれども、それはどのように捉えているのか説明を求めました。","respondent":"篠田文化観光課長","answer":"ある意味、シビックプライドではないですけれども、品川区の誇りに近い部分を感じていらっしゃる方がたくさんいらっしゃるのではないかなと思います。","id":"exchange-064"},{"speaker":"こしば委員","kind":"質問","question":"これがまた若い方々の関心を呼び起こす１つの要因になると思いますので、それが区民の利益につながっていくのではないのかなとは思っております。何か、観光客の方に興味を持ってもらえるような展開をお願いしたいなと思うのですけれども、その辺りのお考えがありましたら説明を求めました。","respondent":"篠田文化観光課長","answer":"できるだけそういった形で取組を進めていきたいと思いつつも、観光協会、なかなか並べて展示するスペースがないというところがあります。その辺は今後工夫をしながら、訴求力の強い形での販売方法を考えてまいりたいと考えています。","id":"exchange-065"},{"speaker":"こしば委員","kind":"質問・要望","question":"ですが、既存の契約の範囲の中でも活用することができるということで、最大限の効果が発揮できるように活用していただきたいと考えます。観光大使ですので、そういった大きなイベントでの活用も含めて検討をお願いしたいと思いますが、お考えを説明を求めました。","respondent":"篠田文化観光課長","answer":"そのほか、様々なイベント等に実際に来ていただくとなりますと、それぞれまた別の経費がかかってきます。実際に、各所管において実施するイベント等でも活用できるように、引き続きそういった形での対応をしてまいりたいと考えているところです。","id":"exchange-066"},{"speaker":"こしば委員","kind":"質問","question":"続きまして、この２１世紀に誕生しましたシナモロールとは違いまして、坂本龍馬をモデルにしたハタチの龍馬についてお聞きします。既にＹｏｕＴｕｂｅ等でもやっていると思いますけれども、さらなる宣伝の展開をお願いしたいと思いますが、お考えがありましたら説明を求めました。","respondent":"篠田文化観光課長","answer":"ハタチの龍馬につきましては、先ほどのシナモロールとは違いまして、品川区のオリジナルということで、様々自由に活用できるところがあります。今の砲台の話でも、そういった点と連動させながら、観光への効果の高い展開をしてまいりたいと考えています。","id":"exchange-067"},{"speaker":"中塚委員","kind":"提案","question":"今定例会に提案されておりますいじめ防止条例の一部改正について、総務委員会に続いて質疑をしたいと思います。子どもがどのような思いをするのか、なぜ子どものつらい気持ちが分からないのか、伺いたいと思いますとの意見を述べました。","respondent":"勝亦総務課長","answer":"１月から区長部局のほうで、いじめの相談のほうを受けてあります。区または関係機関等に相談するように努めるものとするというように、早期解決につなげていきたいという、このような趣旨のものです。","id":"exchange-068"},{"speaker":"中塚委員","kind":"質問","question":"私が伺ったのは、本人に義務づけをすると、子どもがどのような思いをするのか、子どもがつらいという気持ちが分かりますかと伺いました。","respondent":"勝亦総務課長","answer":"そういった中では、今委員がおっしゃったように、それを訴えることがつらいと感じる方、もしくは、いただいたお声の中では、学校にお伝えしにくいものが、区長部局、今回相談窓口があって訴えるところがあってよかった、そのようなお声もいただいているところです。","id":"exchange-069"},{"speaker":"中塚委員","kind":"質問","question":"相談は子どもの義務です。この条例の規定がどれだけ子どもを傷つけるか、なぜこうした子どものつらい気持ちが分からないのか、改めて伺います。","respondent":"勝亦総務課長","answer":"みじめで格好悪いとは考えてございませんが、それがいじめというものが認知できずに、悪化したり長期化したりする原因になろうかと考えています。今回区長部局のほうで窓口を設置いたしまして、はがき等でご相談ができるように、広く相談のできる機会を設けているものです。","id":"exchange-070"},{"speaker":"中塚委員","kind":"提案","question":"総務委員会は賛成多数で通過いたしましたが、子どもを追い詰めるようなことが、森澤区長のやりたいことなのでしょうか。違うのであれば、今からでも条例を一旦取り下げてほしいと思いますが、いかがか尋ねました。","respondent":"勝亦総務課長","answer":"そして重大化、長期化させないために相談できる環境を整えるという意味で、区長部局のほうに窓口を設置するです。努めるものとするという表現につきましては、努めていただくということで、努めるものとするというようにお考えいただければと思います。","id":"exchange-071"},{"speaker":"中塚委員","kind":"質問","question":"子どもから積極的に相談してほしいと思うのであれば、いじめられている本人に相談を義務づけることでは決してありません。改めて、条例は一旦取り下げるべきだと思いますが、いかがか尋ねました。","respondent":"勝亦総務課長","answer":"いじめ防止対策の法律につきましても、いじめを解決することについては社会全体で解決するものの考え方になっております。迷わず身近な人に相談をしてくださいという条例、そういった社会全体でいじめに取り組んでいくのだという、この趣旨を周知徹底していく考え方です。","id":"exchange-072"},{"speaker":"中塚委員","kind":"意見","question":"相談できないほどつらい立場に置かれている、その事実に私たちはどう向き合うのかが問われているのだと思います。子どもを責め立てるような条例は間違っていると、改めて述べたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-073"},{"speaker":"ひがし委員","kind":"質問","question":"私からは、１８９ページ、ジェンダー平等推進事業について、また２１５ページ、戸籍法改正対応経費についてご質問いたします。その点について区はどのようにお考えなのか、また、このにじいろ相談というものはどのような内容を検討しているのかお知らせください。","respondent":"加島人権啓発課長","answer":"そのため、当事者や当事者を支援する団体、こちらに類する団体にこの相談を担っていただきたい、それによる実施が望ましいと考えております。令和６年７月から月２回の頻度で、専門の相談員が電話、または面接による専門相談を実施することを考えております。","id":"exchange-074"},{"speaker":"ひがし委員","kind":"質問・要望","question":"その後の支援、政策等に活かされていたという点、すごくいいなと考えています。なるべく頼んでいるということで、講座についてのアドバイスもいただけるような取組につなげていただきたいと思うのですが、いかがか尋ねました。","respondent":"加島人権啓発課長","answer":"既ににじいろ相談を実施している他区の状況を聞きますと、やはり相談だけで完結するものではないというように聞いております。は講座であったりですとか、こういったものを通じて、性的マイノリティの方の困難の解消に努めてまいりたいと考えております。","id":"exchange-075"},{"speaker":"ひがし委員","kind":"質問・要望","question":"今回電話相談、既ににじいろ専門相談を実施している事業が出している、２０２２年４月の活動の結果というものをご紹介させてほしいと求めました。一緒に進めていければいいなという趣旨での質問になりますけれども、ＬＩＮＥ、いかがか尋ねました。","respondent":"加島人権啓発課長","answer":"来年度予算において、にじいろ相談以外にＳＮＳ相談の開始を新規で予定しております。今の通常のカウンセリング相談と同じく、セクシャリティを含め、幅広い人生のお悩みに対応していくための相談となっております。","id":"exchange-076"},{"speaker":"ひがし委員","kind":"質問","question":"前回の決算特別委員会のときの質問を思い返してみると、ただ、専門家ではないから相談しないというような状況が起こらないかなと危惧しております。１点、その点について何かご答弁があればお願いします。","respondent":"加島人権啓発課長","answer":"まず来年度開始いたしますにじいろ相談、必要性を見極めてまいりたいと考えておりますが、今後の調査研究とさせていただきたいと思います。","id":"exchange-077"},{"speaker":"ひがし委員","kind":"意見","question":"せっかく品川区でこのような条例ができるのであるから、病院などでもしっかりと周知をしてほしいというようなお話をいただいております。病院や事業者に対してどのように周知をしているのか、していく予定なのか、改めて説明を求めました。","respondent":"加島人権啓発課長","answer":"入院という通常とは異なる状況において、そのような心細い思いをさせてしまったことについては、とても心苦しく思います。関係の団体などがありますので、そういったものを通じて説明を図ってまいりたい、徹底してまいりたいと思います。","id":"exchange-078"},{"speaker":"ひがし委員","kind":"質問","question":"次に、戸籍法改正対応経費についてお伺いします。１,５００万円余が予算化されていますけれども、どのように使われるのか、まずは説明を求めました。","respondent":"吉野戸籍住民課長","answer":"来年度の予算ですけれども、今委員がお話しされていた、本籍の方へ振り仮名を確認するための通知を発送するものになります。","id":"exchange-079"},{"speaker":"ひがし委員","kind":"質問","question":"例えば個人で送ってほしいというような意見を聞いたときに、あらゆる理由でそこの住所ではなくて個人宛てに送ってほしいなどというとき、想定などがあれば教えてほしいと求めました。","respondent":"吉野戸籍住民課長","answer":"データとして支援措置が必要な方たちのデータを持っておりますので、そこの、いわゆる世帯から除くということは可能です。事前にやはり周知、こういった通知を送りますということで、個別の対応を検討できるかなと今考えております。","id":"exchange-080"},{"speaker":"ひがし委員","kind":"質問","question":"個別の対応も検討いただけるということで、ぜひこの周知というところを早い時期にしていただくべきかなと思います。これからはニュース等でも、品川区としても早い段階から周知というところを進めてほしいと求めましたが、いかがか尋ねました。","respondent":"吉野戸籍住民課長","answer":"やはり見ていただかなければ何もなりませんので、早めの周知をしたいと考えています。これに関しまして、細心の注意を払って対応しなければいけないと考えていますので、丁寧な対応を心がけたいと思います。","id":"exchange-081"},{"speaker":"ひがし委員","kind":"意見","question":"ほかの方の配慮もしてくださると思ってはいるのですけれども、ＤＶだけではなくて、お名前を変えたという方、先ほど言っていたトランスジェンダーの方々も変えた人がいて、家族に届いてしまうとというところで考えると、幅広い方々にきちんと分かるような対応を取ってほしいと求めました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-082"},{"speaker":"つる委員","kind":"質問・要望","question":"国は無料化にかじを切ったという中で、品川区の見守りホットラインについても無料化すべきだということを、各機会を通じて求めさせていただきました。これは０３からなので、庁舎管理費に関連して伺いたいと思いますが、この辺の検討状況を説明を求めました。","respondent":"加島人権啓発課長","answer":"見守りホットライン、こちらのダイヤルについてですけれども、委員からもご案内ございましたとおり、４本あります。こちらにつきましては、令和６年１０月の区立児童相談所の開設に合わせまして、フリーダイヤル化していく予定です。","id":"exchange-083"},{"speaker":"つる委員","kind":"質問・要望","question":"その他関連して伺いたいことは別の款で伺いますが、来年度の１０月のときに、体制を盤石にしてほしいと求めました。漏れはないか尋ねました。","respondent":"勝亦総務課長","answer":"平和首長会議につきましては、今委員にご紹介いただいたとおり、品川区も加盟しております。ちょっと直接の関わりがなく、平和首長会議のほうとのやり取りの中では、未来アクションフェスについてはお話を伺っていないところです。","id":"exchange-084"},{"speaker":"つる委員","kind":"提案","question":"ですから、品川区の平和施策につなげていただきたい、このように思います。平和に関しては、前回、２年前ですか、予算特別委員会で求めました。","respondent":"河合生活安全担当課長","answer":"やはり区民からの要望や治安情勢から含めて、単年ということではなく、効果を見定めて継続的にできればとは考えております。","id":"exchange-085"},{"speaker":"つる委員","kind":"質問・要望","question":"何に、どこに手を厚くしていけばいいのかということを精査していただきながら、継続性のある事業にしてほしいと求めました。そして犯罪のない、子どもたちが守られる品川区をぜひつくってほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-086"},{"speaker":"やなぎさわ委員","kind":"質問","question":"体制確保や予算面で課題があるということでお話は終わったのですけれども、来年度の予定としてはいかがでしょうか。、答えるよう求めました。","respondent":"加島人権啓発課長","answer":"ある程度伴走して継続的な支援を行っていく必要があるかと考えますが、現状、被害者支援を中心として担ってまいりました区のほうには。そのため、来年度実施は困難と考えております。","id":"exchange-087"},{"speaker":"やなぎさわ委員","kind":"質問","question":"お互い好きな者同士が一緒になっているので、別れるよりも、やはりパートナーに更生してほしいというように願う方が多いと感じております。そういったところが見つかれば、このような加害者関係の更生プログラムを実施していただけるというようなことでよろしいか尋ねました。","respondent":"加島人権啓発課長","answer":"先ほどと少し答えが重なりますけれども、被害者支援を担う部署で加害者支援をも担うことは、被害者の安全確保の面で課題があると考えております。","id":"exchange-088"},{"speaker":"やなぎさわ委員","kind":"質問・要望","question":"数々ありますので、必要であれば私のほうでもそういったデータをお渡ししますし、ぜひそういったところを精査してほしいと求めました。最後に何かあれば、ご答弁お願いします。","respondent":"加島人権啓発課長","answer":"加害者支援の重要性につきましては、確かに認識しております。ただ、委員からご案内がありました東京都の実施体制などにつきまして、こちらは所管のほうで調査研究してまいりたいと思います。","id":"exchange-089"},{"speaker":"やなぎさわ委員","kind":"質問・要望","question":"しながわシティランです。ランニングというか、ジョギングを選んだ理由というものをぜひお聞かせいただきたいのですが、いかがか尋ねました。","respondent":"三井スポーツ推進課長","answer":"いろいろなところからご要望いただきまして、今回開催に向けて検討を進めて、ここまで来ている状況になっています。","id":"exchange-090"},{"speaker":"やなぎさわ委員","kind":"質問","question":"肥満率が３９％というところがありまして、長く行われるイベントになってほしいなと思っているので、応援しています。今のコースの中でできるプラスアルファを入れていくと、特別感が出ると思うのですけれども、いかがか尋ねました。","respondent":"三井スポーツ推進課長","answer":"こちらについても魅力はあると考えていますが、そのような応援方法については、今後実行委員会等を含めて検討してまいりたいと思います。","id":"exchange-091"},{"speaker":"やなぎさわ委員","kind":"意見","question":"それこそ、この前えのした委員が区長にランナーで参加してほしいとおっしゃっていましたけれども、そのようなものもいいと思います。ぜひご検討をお願いしますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-092"},{"speaker":"西村委員","kind":"提案","question":"我が会派からも新しいものをと提案し、終了予定と伺ってまいりましたが、月曜日、ＳＮＳに流れてきて、正直驚きました。今後の予定と併せて説明を求めました。","respondent":"辻広報広聴課長","answer":"一方で、これからの新時代をつくっていく上で、新たな道を探っていこうと考えています。区民とともにワークショップ等を行いまして、マークをつくるですとか、そういったことを進めていくというような計画になっています。","id":"exchange-093"},{"speaker":"西村委員","kind":"質問・要望","question":"この今のタイミングですと、丁寧にご対応と配慮をお願いしたいなと思っていますので、要望させてほしいと求めました。全てを載せるということは限界があると思いますし、大変難しいことと思いますが、いかがか尋ねました。","respondent":"辻広報広聴課長","answer":"今回は３０件以上つきまして、これを惜しむ声ですとか、今までありがとうというような気持ちなのかなと思ったところです。もちろんそれだけではなくて広報紙を使うということで、様々な点を勘案しながら、選んでやることが重要かなと考えています。","id":"exchange-094"},{"speaker":"西村委員","kind":"質問","question":"まず松本議員が気づかれまして、せりざわ議員が即座に問合せをしたら、区役所は事態の認識をして既に動いておられたというように伺っております。こういったＳＮＳ情報収集分析の中での取組の１つの成果かなと思うのですが、ご答弁をお願いいたします。","respondent":"辻広報広聴課長","answer":"その後に議員からお電話いただいたり、区民の方からもお電話をいただきました。プロの方に頼んだほうがいいということで、来年度からはＳＮＳの情報収集分析ということで、業者に委託をすることになったところです。","id":"exchange-095"},{"speaker":"西村委員","kind":"質問・要望","question":"次に都市ブランディングですけれども、どのような品川の未来をつくっていくのか伺ってまいりたいと思います。品川ブランドの可視化に向けて、目的、ゴールは何なのか、品川区はブランディングすることで、何が起こったら成功と考えるのか伺います。","respondent":"辻広報広聴課長","answer":"今年度、既に区民向け、それから職員向けにアンケートを実施したり、あとは区内で活躍する方々に直接ヒアリング等を行っております。まず固定ファンを増やし、そしてそこからどんどん増えていくということが、それがいいかなとは思っています。","id":"exchange-096"},{"speaker":"西村委員","kind":"質問・要望","question":"何かと今話題になる公共トイレの考え方、過渡期だと思いますので、改めて区の姿勢を伺いたいと思います。組織横断的に考えていくと人権啓発課が中心になると思いますが、その辺りはどのようにお考えか、現状の庁内の取組と併せて伺います。","respondent":"加島人権啓発課長","answer":"学校施設担当、新庁舎整備課で、それぞれミーティングを行いました。それぞれの施設の用途、目的に応じて考えていくことが重要だというように、認識を共通にしたところです。","id":"exchange-097"},{"speaker":"西村委員","kind":"質問・要望","question":"ぜひとも人権啓発課がリーダーシップを取っていただきながら進めていただきたいと思うのですが、方向性を伺いたいと思います。男女共用トイレをつくる予定のある施設はあるのか、上位計画はあるのか、伺います。","respondent":"小林施設整備課長","answer":"あるいはおむつ替えスペースを設置したりすることで、国の考え方を準用して整備をする計画として、今進めているところです。区としましては一律に整備をしていくという考え方ではございませんが、その施設の利用に応じて、様々検討を深めていきたいと考えているところです。","id":"exchange-098"},{"speaker":"西村委員","kind":"質問・要望","question":"男性トイレにもおむつ替えスペースがありまして、それは区民の方々からも求められてきたことですので、ぜひ進めてほしいと求めました。設置の趣旨確認や、場所の妥当性をどう考えていくのか、お考えを説明を求めました。","respondent":"小林施設整備課長","answer":"区としても様々なニーズがトイレに求められていることは認識しておりますが、一方でトイレの種類を単に増やしていく考えではないかと考えています。","id":"exchange-099"},{"speaker":"西村委員","kind":"意見","question":"今、一方でジェンダーは人権問題でもありますので、その調整の過程に知恵が必要だと思っています。どうぞとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-100"},{"speaker":"のだて委員","kind":"質問","question":"現在、庁舎跡地等活用検討委員会が行われていますが、検討委員会と計画策定との関わりを伺います。土地評価のところは、しながわ中央公園も含めて行うのかどうか伺います。","respondent":"泉広町事業調整担当課長","answer":"１点目のご質問、庁舎跡地等活用検討委員会と計画策定との関わりですけれども、今現在、検討委員会の中では区民ニーズの把握に努めているところです。","id":"exchange-101"},{"speaker":"のだて委員","kind":"質問・要望","question":"この土地鑑定評価のところでは公園は除くということで、そうすると、しながわ中央公園はこの民間活用の対象にはなってこないのか。民間に貸し出すということにはならないということでいいのか、確認させてほしいと求めました。","respondent":"泉広町事業調整担当課長","answer":"官民連携手法の対象範囲というところのご質問です。現在庁舎跡地等活用検討委員会で区民ニーズの把握をしていますけれども、また、範囲を定めるということで考えてあります。","id":"exchange-102"},{"speaker":"のだて委員","kind":"質問・要望","question":"改めて伺いたいと思います。区民参加の点で、検討委員会の目的を伺います。","respondent":"泉広町事業調整担当課長","answer":"１点目、区民ニーズのかなえられるまちというところの最適なところを目指して、引き続き検討を進めてまいりたいと思います。現在進めております庁舎跡地等活用検討委員会の目的ですけれども、こちらは今検討委員会の中で、今後の計画策定といったところにつきましても。","id":"exchange-103"},{"speaker":"のだて委員","kind":"質問・要望","question":"この会が、区民の声を出させるだけで、市場調査で出されたものを推進していくということになってしまうのではないかと思います。結局のところ、この検討委員会は何をするところなのか、マッチングするということはどのようなことなのか、伺います。","respondent":"泉広町事業調整担当課長","answer":"検討委員会ですけれども、こちらは今も検討委員会の中で様々出たご意見を少しずつ収れんさせながら、そういったところを取りまとめているところです。その取りまとめの過程では、先ほど申し上げた計画策定にしっかり役立てていきたいというところで考えているものです。","id":"exchange-104"},{"speaker":"のだて委員","kind":"提案","question":"居住や商業、業務、高齢者福祉、子育て支援などの施設提案があったとの説明です。具体的な中身は分からないというところで、この具体的な提案内容はどのようなものがあったのか伺いますとの意見を述べました。","respondent":"泉広町事業調整担当課長","answer":"スポーツ、文化、宿泊といった施設の提案がなされたところです。","id":"exchange-105"},{"speaker":"のだて委員","kind":"質問","question":"公開はしないということですか。この中身はいつ公開するのか、ずっと公開しないのか伺いたいと思います。","respondent":"泉広町事業調整担当課長","answer":"民間事業者の提案を公表するかといったところの考えはございませんが、そういったところには留意をしながら、公表については検討してまいりたいと考えています。","id":"exchange-106"},{"speaker":"のだて委員","kind":"提案","question":"こうした下でＰＦＩを導入していくとなれば、企業の利益のために公有地が使われてしまうのではないかと思いますが、いかがでしょうか。民間にこの現庁舎跡地を売り渡すこともあるのか、売却すべきではないと思いますが、いかがか尋ねました。","respondent":"泉広町事業調整担当課長","answer":"ＰＦＩを前提として検討を進めているものではございませんで、広く官民連携手法を検討しているものでございまして、庁舎跡地に活用することで区民ニーズをかなえられるものになるということで考えているものです。","id":"exchange-107"},{"speaker":"のだて委員","kind":"質問・要望","question":"住民要望をかなえるように使ってほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-108"},{"speaker":"石田（し）委員","kind":"質問","question":"それと１７９ページ、デジタル人材育成などについてと、時間があったら２１９ページの選挙費についてお伺いしていきます。４月に今度策定する人材育成・確保基本方針ですか、ここについて１つ、様々な交流を区行政もされてきたと思います。","respondent":"佐藤経理課長、辻広報広聴課長、崎村人事課長","answer":"私のほうから、契約の相手方に情報漏えいがあった場合の区の対応についてお答えいたします。最終的には社会的に信用失墜行為が認められる場合には… １８７ページのＬＩＮＥ公式アカウント運用の契約についてです。ですから、今回の情報漏えいには、直接は関係ないという認識です。例えば１週間ですとか、こちらは令和２年度から、その民間交流というものは止まっているような状況です。","id":"exchange-109"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"どうしても出てきてしまう、それを戻って、また取り入れていく。特にやはり区内企業とやっていただくことはもちろんですけれども、ぜひその辺をやってほしいと求めましたが、最後お考えがあれば説明を求めました。","respondent":"崎村人事課長","answer":"仕事をすることによって、改めて行政職員としてどのようなことが求められているのかということに気づくきっかけにもなるかと思います。","id":"exchange-110"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"にもかかわらず、期日前投票所というものは、さほど変わっていないです。もちろん民間企業の協力を求めていってもらいたいということもありますけれども、そういったときには、その辺に関して何かあればお知らせください。","respondent":"鈴木選挙管理委員会事務局長","answer":"ご存じのように１３地域センター、衆議院選挙の場合に急な選挙があると、どうしても施設の確保が難しいという面があります。その辺も含めて、今後区の施設で拡大できるかどうかは、内部で調整したいと考えております。","id":"exchange-111"},{"speaker":"塚本委員","kind":"質問","question":"１８７ページの区政資料等発行経費、それから１７９ページのしながわＷｉ－Ｆｉスポット事業と、この点について伺っていきたいと思います。ある種の定め等があるのか、そういった点について、まずお伺いしたいと思います。","respondent":"辻広報広聴課長","answer":"その中で、何を誰に伝えたいのかというようなことをまず考えましょうということや、それからレイアウトのコツや見せ方についてそこで示しています。","id":"exchange-112"},{"speaker":"塚本委員","kind":"質問・要望","question":"区民の求める情報、情報というとあれですが、文字の形にはなっていない部分もあると。そういった指導徹底というのですか、印刷物等の在り方というのですか、その点についていかがか尋ねました。","respondent":"辻広報広聴課長","answer":"結果的には、それでは伝わるものも伝わっていないというようなことになっているのかなと思います。全庁的にまた研修を別の形で開くような予定もしておりますので、その中で、見直していきたいなと考えています。","id":"exchange-113"},{"speaker":"塚本委員","kind":"質問・要望","question":"ここの総務費に載っているもの以外にもあるのではないかと思いますけれども、全体としてはどの程度になるのか教えてほしいと求めました。例えばシステムの構築費だとか、移行後に運用していくための、いわゆるランニングコストだとか、そのような内訳についても説明を求めました。","respondent":"横田情報推進課長","answer":"全体で約２５億６,７００万円を計上しております。内訳ですが、イニシャル経費で大体１９億７,２００万円、ランニング経費で５億９,５００万円となっております。","id":"exchange-114"},{"speaker":"塚本委員","kind":"意見","question":"分かりました。区に対するメリット、これは一体どのようなものがあるのか、今の区としての見解をお知らせくださいとの意見を述べました。","respondent":"横田情報推進課長","answer":"２点目ですが、一度契約すれば請け負っているベンダー以外に対応できないといった、価格競争が発生してコスト削減が期待できるということ。","id":"exchange-115"},{"speaker":"塚本委員","kind":"質問","question":"１つの自治体の経費、これが解消されるということがシステム標準化の１つの売りというのですか、私なども認識をしておりました。いわゆる今までのような関係というのですか、また、起こるべきだと思っているのかお知らせください。","respondent":"横田情報推進課長","answer":"これまでシステムのアプリに関しましては、各自治体ごとに違っておりましたので、いわゆる価格交渉というものが今まではできました。アプリの、サービス利用型ということになりますので、システムベンダーとは減額交渉がなかなか難しくなるということが考えられます。","id":"exchange-116"},{"speaker":"塚本委員","kind":"質問・要望","question":"その点を含めて、また区としてコスト削減、こういったことについてどういった点が努力できるのか。品川区として、どういった形でその利用料等を適正化していく手段があるのか、こういったことも含めてお聞かせほしいと求めました。","respondent":"横田情報推進課長","answer":"では、ガバメントクラウドの利用料につきましてはデジタル庁とクラウド事業者の契約になりまして、区は案分された金額を支払うというスキームです。","id":"exchange-117"},{"speaker":"塚本委員","kind":"質問","question":"昨年第４回定例会の一般質問で、接続時間が６０分で切れてしまうということでの使い勝手の悪さや、一部の区有施設ではＷｉ－Ｆｉがないと。こういったことで、ぜひここの改善をというようなことでお願いしたのですが、来年度、ここについて何か対応を予定されているか説明を求めました。","respondent":"横田情報推進課長","answer":"次年度から、１接続当たり６０分の制限をなくしましたＷｉ－Ｆｉにつきまして、室内施設に設置していく予定です。時期については、工事が入りますので、これから交渉していく予定です。","id":"exchange-118"},{"speaker":"塚本委員","kind":"質問・要望","question":"時間が６０分を超えるということは大変に大きな前進で、進めていってほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-119"},{"speaker":"田中委員","kind":"質問・要望","question":"１８６ページの戦略広報費全般に関して、関連しまして２１３ページ、ふるさと納税事業、時間があれば２０９ページ、デフスポーツに関連して伺います。ある意味横並びの情報発信というのでしょうか、今度は情報発信、このような組織改編があったのかなと受け止めております。","respondent":"辻広報広聴課長","answer":"戦略的広報の進め方というようなご質問かと思います。もちろんトップマネジメントの中の１つとしてやるということが１つ、きちんと連携しながら進めていくということが大事かなと考えています。","id":"exchange-120"},{"speaker":"田中委員","kind":"質問・要望","question":"これまで一般質問や、１件も、ほとんど反応がありませんでした。ですから、そのような視点からの取組も私はぜひやってほしいと求めましたが、いかがか尋ねました。","respondent":"辻広報広聴課長","answer":"ふるさと納税で失った税収額というものが、私たちの中では分かっていても、やはり区民の方には届いていないかなという一面はあると思います。そういったところは税務課等と連携しながら、広く伝わるような仕掛けをしていきたいなと思います。","id":"exchange-121"},{"speaker":"田中委員","kind":"意見","question":"しながわ」をやめるのであるけれども、もう時間ないのでやめます。すみませんとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-122"},{"speaker":"せりざわ委員","kind":"質問・要望","question":"私からは１８３ページ、２０５ページ、時間があれば１８５ページのマウントしながわ活用事業についてお伺いしたいと思います。新年賀詞交歓会経費からお伺いしたいと思います。","respondent":"勝亦総務課長","answer":"今年度の課題といたしまして、従来どおりの時間で設定しておりましたが、新しく飲食なしという形で実施させていただきました。その中でお茶は提供させていただきましたが、ゆっくりお話ができる場面、できない場面、それぞれ受け止め方が皆さんあったのかなと考えています。","id":"exchange-123"},{"speaker":"せりざわ委員","kind":"確認","question":"残念ながら今回変わらずに、また、状況の確認があまりできなかったみたいなお話ですが、入り口にいて、私はそんなことあるのかなと思っています。観光大使のお話をちょっと確認したいと思います。","respondent":"篠田文化観光課長","answer":"もともとのサンリオのキャラクターとの違いです。もちろんあちらが考えてつくられているところでありますが、平成２９年から、明確に違いが分かるような形での活動をお願いしております。","id":"exchange-124"},{"speaker":"せりざわ委員","kind":"質問・要望","question":"まず１点は、ほとんどというか多分独占状態でやっていると思いますが、それをぜひ活用していただきたいなと思います。最後、ご見解を説明を求めました。","respondent":"篠田文化観光課長","answer":"シナモンの活用につきましては、様々な制約がある中で、きちんと区の発信として十分活用できるよう取り組んでまいります。","id":"exchange-125"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"だけれども、期間的にはあと４年ぐらいあるのであれば、来年の４月１日、今だったら再来年度と言うのでしょうか。もちろん建物をどういうふうにしていくという計画とともに、最後の３年間ぐらいはそういう使い方を検討してほしいと思っています。","respondent":"三井スポーツ推進課長","answer":"今後、本格活用していく中で、そのままの現状で貸し出せるかどうかというような様々なことを総合的に考えていく必要があると考えております。委員ご提案の内容につきましては、今後、どのような方策があるのか探ってまいりたいと考えています。","id":"exchange-126"},{"speaker":"石田（秀）委員","kind":"提案","question":"職員提案をぜひやってほしいということで９件できました。これをモデル化して、これで９事業やっていけるということは非常にいいことだと思いますので、これをどんどん推し進めていただきたいと思っていますとの意見を述べました。","respondent":"久保田企画部長","answer":"職員提案制度を今年始めて、行政評価もやっているといったところです。今年始めた取組ですので、今後の展開については、より効率的・効果的にできるように検討していきたいと考えております。","id":"exchange-127"},{"speaker":"松永委員","kind":"質問・要望","question":"１７９ページの庁舎管理費について、２０３ページの地域資源活性化事業補助について、２０９ページの品川歴史館のリニューアル経費について伺います。こうしたことも踏まえて、その際に近隣町会も含めた合同のイベントをぜひ検討してほしいと求めましたが、再度のご確認でお願いいたします。","respondent":"篠田文化観光課長","answer":"やはり新たな施設ということで、運営方法が変わってくることもありますので、まずは安定した運営をしていくことが大事だろうというところです。今後、何らかの形でイベントに取り組めるかどうか、検討してまいりたいと考えております。","id":"exchange-128"},{"speaker":"松永委員","kind":"質問","question":"初めに、総合庁舎３階にあります噴水について伺います。いつからそのままになってしまったのか、併せて伺います。","respondent":"佐藤経理課長","answer":"現在、水が出ておりませんが、こちらは２０１１年の東日本大震災の際に噴水のところで水漏れがあったということで、一旦停止いたしました。その後、国全体として節電・節水の必要があったということもありまして、以降使っていないという状況です。","id":"exchange-129"},{"speaker":"松永委員","kind":"質問・要望","question":"これは要望で終わらせていただきます。加入しやすくするため、この事業を定着させるという制度を制定されたと思いますが、ここ３年間の実績についてお知らせください。","respondent":"宮澤地域活動課長","answer":"令和５年１月末で４４件の申請がございました。令和４年は２４件、令和３年は７件です。","id":"exchange-130"},{"speaker":"松永委員","kind":"確認","question":"来年度予算を確認させていただきましたが、１年目から３年目までのところでは、３５町会掛ける１０万円。こちらも、できましたら実績等も含めて、２万円減額された理由をお知らせください。","respondent":"宮澤地域活動課長","answer":"来年度は通常どおりの上限額１０万円になります。１月末現在で１４７件の申請、令和４年度は４７件、令和３年度は１３件です。","id":"exchange-131"},{"speaker":"松永委員","kind":"提案","question":"提案ですが、住民の方に分かりやすくすればいいのではないかと思いますが、いかがでしょうか。なぜ品川区だけこんなに掲載されているのか分かりませんが、そのことも踏まえて、今後どういった対応をされるのか、説明を求めました。","respondent":"宮澤地域活動課長","answer":"そういったところ、ホームページに金額を載せるなど透明性のある形にするというのは良い手法かと思います。そういったところ、町会・自治会、地域センターを含めて支援しておりますので、情報共有できるようなことがあればしていきたいと考えております。","id":"exchange-132"},{"speaker":"松永委員","kind":"質問・要望","question":"そうしたところにもぜひ補助金を出していただきたい。もし活用できるのであれば、その内容を教えていただきたいのですが、改めて伺います。","respondent":"宮澤地域活動課長","answer":"町会・自治会長の皆様との意見交換会を今年度も実施している中で、やはりそういうところが課題ですというご意見を伺っています。その中で、町会もやはりそういう活用ができないかというところで、コンサルを含めて検討しているというところは伺っております。","id":"exchange-133"},{"speaker":"松永委員","kind":"質問・要望","question":"ぜひＪＲに要望していただきたいのですが、例えば羽田空港のような展望デッキというようなところをつくっていただけないかなと思います。最後に伺います。","respondent":"宮澤地域活動課長、篠田文化観光課長","answer":"ＬＩＮＥ等での情報発信のコストの部分です。町会・自治会には毎年、環境整備等助成金という形で補助金をお渡ししているので、その中で活用していただきたいです。 鉄道を使った観光資源の活用というお尋ねです。関係部署と連携しながら、可能性やどういった取組ができるのかということについては、今後研究したいと考えております。","id":"exchange-134"},{"speaker":"西本委員","kind":"提案","question":"しながわ」の評価はどうだったでしょうかということで、９割の方が住み続けたいと言っているので、評価があったというのですが、本当ですか。しながわ」をやられて、今回やめられるわけですから、その評価というのをどういうふうに考えられているかということが１つですとの意見を述べました。","respondent":"辻広報広聴課長","answer":"今まであるものに関しては、ＳＤＧｓの観点からも、それは使っても構わないという認識です。ですから、４月から、今ある区のそういったものも全て新しくするということではございません。","id":"exchange-135"},{"speaker":"西本委員","kind":"質問","question":"進め方もいろいろあると思いますが、これに対して、区の職員の方々は、どういうイメージを持っているのでしょうか。お聞きしたいと思います。","respondent":"辻広報広聴課長","answer":"今現実としてある品川の価値だけでなく、これからのものを、価値を創造していこうと考えております。職員にも既に都市ブランディングに関する研修も行っておりまして、一定の理解を得たと認識しております。","id":"exchange-136"},{"speaker":"西本委員","kind":"質問","question":"都市ブランディングですが、まず、やはりトップが、区長がどういうふうに品川区を捉えているかということに限るのではないですか。できれば区長に答えてもらいたいのですが、区長が考える品川区のブランディングとは何ですかということです。","respondent":"森澤区長","answer":"都市ブランディングを進めていくに当たっては、やはりリーダーとしてのそういった考え方も必要だと思いますので、様々今調査もしております。そういった意見も参考にしながら、区民の皆さんとともに考えていきたいと考えています。","id":"exchange-137"},{"speaker":"西本委員","kind":"提案","question":"では、それをするために品川区は何をするのですかということが大切なのです。そして、職員提案制度についてですが、担当がなぜ秘書担当なのか尋ねました。","respondent":"岡秘書担当課長","answer":"なぜ今年度は秘書担当で職員提案制度をやっているかというご質問だと思います。職員提案制度の目的としまして、区長の前で職員の考えている提案をプレゼンするというところもありまして、秘書担当が担当しております。","id":"exchange-138"},{"speaker":"西本委員","kind":"質問","question":"全部、区長が責任を取ってくれるということですか。いかがか尋ねました。","respondent":"岡秘書担当課長","answer":"所管する課や部では気づかなかったこと、新しい視点といったところで、新たな事業を考えることができると考えております。区としましても必要な事業だと考えておりますので、今後も取り組んでまいりたいと考えています。","id":"exchange-139"},{"speaker":"西本委員","kind":"質問","question":"なぜ上からぼんと落とすのですか。組織というのであれば、いろいろな企画ができるようにしていくというのが組織としてあるべき姿ではないのかなと思いますが、いかがか尋ねました。","respondent":"堀越総務部長","answer":"供給者側からの視点も入れられるのではないかと思っているのが１つと、区長の指示を受けて、またそれを政策に活かしていくと。様々事業展開をしていくという考えで行ってありますので、委員がおっしゃっていることと、考えとしては決して違っていないと考えています。","id":"exchange-140"},{"speaker":"西本委員","kind":"質問・要望","question":"ぜひ見直しを図っていただきたいと強く申し上げたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-141"},{"speaker":"若林委員","kind":"確認","question":"ポイ捨て吸い殻本数をカウントする際に、まさに今数えた落ちている吸い殻の扱いをどうするのかも確認します。これまでの様々な課長等との議論の中で、誰がそういう場所の確認や声がけを行っているのかというご様子をお聞きして、今年度２０２３年度ですかね。","respondent":"勝亦総務課長、河合生活安全担当課長","answer":"品川区内の薬剤師会にご協力いただきまして、避暑シェルターを拡大できないかとご相談いたしまして、連携しながら実施していく予定となっています。具体的な場所等は決まっておりませんが、薬局等で実施する中で… 推進地区５地区の過料徴収という形でやっておりますが、今後の規制の在り方を検討する上で、客観的な根拠として確認するための調査となっております。","id":"exchange-142"},{"speaker":"若林委員","kind":"質問・要望","question":"最後の助成ですが、民間の１か所がもう既に見えているというご答弁だったのでしょうか。確認させてください。","respondent":"河合生活安全担当課長","answer":"喫煙状況の調査をメインに今回は行った上で、規制の在り方、そして喫煙所の整備を検討していきたいと。根拠として整理して、検討していきたいと考えております。","id":"exchange-143"},{"speaker":"若林委員","kind":"意見","question":"具体的に、どこ、何地区とか何駅ということがこの場で言えるのであれば、どうぞおっしゃってくださいとの意見を述べました。","respondent":"河合生活安全担当課長","answer":"五反田地区のゆうぽうとの１階にできる喫煙所ですが、こちらは調整しながら、申請に向けていろいろ指導して、今回受理するところです。","id":"exchange-144"},{"speaker":"若林委員","kind":"意見","question":"なるほど、そういうことですね。港区がなぜあれだけの成果を上げているかということが、また、来年度しっかりと一緒に前に進めていきたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-145"},{"speaker":"澤田委員","kind":"質問","question":"２１５ページ、マイナンバーカード普及促進について質問いたします。内訳に、申請補助事業１,０４７万７,０００円とありますが、こちらの事業内容を説明を求めました。","respondent":"吉野戸籍住民課長","answer":"マイナンバーカード普及促進の申請補助事業ですが、令和６年度は、大きく分けまして２つの事業を行いたいと考えております。令和６年度の出張申請サポートは３０回を予定しております。","id":"exchange-146"},{"speaker":"澤田委員","kind":"質問","question":"以前から行っているマイナンバーカードの出張申請サポートを次年度は３０回行うということですが、今までの実績や成果などを改めて教えてください。お願いします。","respondent":"吉野戸籍住民課長","answer":"次に、出張申請サポートですが、令和５年度はマルチタスク車両を利用して申請補助をしまして、１２回実施しました。武蔵小山商店街などへ出張した申請サポートは計４０回実施しまして、１０１人の方から申請していただきました。","id":"exchange-147"},{"speaker":"澤田委員","kind":"提案","question":"しているところはないかもしれませんが、すまいるスクールでも同じように本人確認として活用できるかと思います。現在、区がお考えになっている新しい利活用方法の現状、今後の考え方などを説明を求めました。","respondent":"横田情報推進課長","answer":"委員ご指摘のとおり７０％を超えてきましたので、積極的にマイナンバーカードの利活用を進めていく予定でございまして、幾つか計画しております。次年度予定しているこれらの施策と近しいスキームもありますので、着手可能なところから今後展開していく予定です。","id":"exchange-148"},{"speaker":"澤田委員","kind":"質問・要望","question":"両親以外の迎えの本人確認として使えるなどという情報を、その世代に向けた、未取得の層に向けた周知をさらに強化してほしいと求めました。利活用の拡充を進めるとともに、周知を強化してほしいと求めましたが、区としてのお考えを説明を求めました。","respondent":"吉野戸籍住民課長","answer":"あらゆる手段を使いまして、周知を進めたいと思います。","id":"exchange-149"},{"speaker":"高橋（し）委員","kind":"質問","question":"１７５ページの計画策定経費の行政評価、２１９ページ、選挙費の若年層への啓発事業についてお尋ねします。これに対する選挙管理委員会の対応はどのような状況か尋ねました。","respondent":"鈴木選挙管理委員会事務局長","answer":"選挙管理委員会としましても、若い方の投票率が低いことは大きな課題であると認識しております。区内の大学の文化祭や明るい選挙推進協議会と協力しまして、様々な若い方の啓発事業に取り組んでおります。","id":"exchange-150"},{"speaker":"高橋（し）委員","kind":"質問","question":"これも先ほどの若者啓発の一つなのでしょうか。その活動の目的や、具体的にどのようなことをなさっているか、その様子などをお尋ねします。","respondent":"鈴木選挙管理委員会事務局長","answer":"その方たちが中心に自主的に取り組んでいただいているもので、区の選挙管理委員会としても支援しているものです。具体的な活動としましては、ご自分たちで啓発の内容や手法の企画を練っていただくという活動をしていただいております。","id":"exchange-151"},{"speaker":"高橋（し）委員","kind":"意見","question":"そうすると、今お話のあった啓発活動でどのような成果があったのか。そこに選挙管理委員会がどのように関わっているのかということをお尋ねしますとの意見を述べました。","respondent":"鈴木選挙管理委員会事務局長","answer":"ご指摘のありました昨年１２月の募集に関しましては、１０名の方に応募いただきまして、Sa-１kowに加わって活動していただいております。令和５年度のSa-１kowの活動としては、地域の祭りに参加するなど、いろいろな機会を捉えて活動いただいているものです。","id":"exchange-152"},{"speaker":"高橋（し）委員","kind":"質問","question":"今すぐに５％、１０％が一気に上がるわけではないですが、地道に活動されることはとても大切だと思います。若者啓発参加者の募集は、引き続いて今後どのような形で進められていくのか尋ねました。","respondent":"鈴木選挙管理委員会事務局長","answer":"今後の活動の予定ですが、年度内におきましては、３月下旬から２回目の参加者募集のポスターを町会の掲示板に貼らせていただいて募集する予定です。","id":"exchange-153"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"これは要望です。令和５年度を振り返って、課題はどのようなところにあるのか尋ねました。","respondent":"吉岡政策推進担当課長","answer":"今回、今後も効果的・効率的に行政評価を行う上では、職員の負担軽減をうまく図りながら実施していくことが必要だと考えております。次年度以降こういった部分もしっかり研究しながら定めていって、効果を測っていきたいと考えております。","id":"exchange-154"},{"speaker":"高橋（し）委員","kind":"質問","question":"行政評価の効率化・重点化が３３％、行政評価の効果に疑問というのが３％と、そのように少し課題が出てきています。４年度の試行および５年度の本格実施を踏まえて、先ほど負担が課題と伺いましたが、もう少し具体的に分かればお願いします。","respondent":"吉岡政策推進担当課長","answer":"品川区のほうでも過去に実施させていただいた行政評価は、やはり職員の負担あるいは職員の評価のマンネリといった部分がございました。今回、全事業の評価を行いましたが、これも全事業が必要かというところも含めまして、引き続き検討を重ねていきたいと考えております。","id":"exchange-155"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"それからすごく小さな字なので、それを複数ページに分割するなどの改善も求められると思います。令和５年度は計画策定経費の小事業として行政評価があるので、この行政評価の行政評価を令和６年度は行うことになるのか尋ねました。","respondent":"吉岡政策推進担当課長","answer":"令和５年度の事務事業を評価するといった形になりますので、当然ながら行政評価も行政評価の対象になります。まさにそのとおりでございまして、どのように示したらいいかというところは、引き続き検討していきたいと思います。","id":"exchange-156"},{"speaker":"松本委員","kind":"質問・要望","question":"私からは１８５ページ、外国人学校児童生徒等保護者補助金、１９１ページ、職員研修費について伺います。これは国籍を一つの要件にしていると理解してよろしいか尋ねました。","respondent":"勝亦総務課長","answer":"外国人学校児童生徒等保護者補助金の交付要綱で定めております対象者は、保護者となっています。おっしゃったように、住民基本台帳には記録されているけれども、日本国籍を有しない者という方を対象としております。","id":"exchange-157"},{"speaker":"松本委員","kind":"質問","question":"東京朝鮮学園、東京韓国学園、東京中華学校に授業料を払う方というふうになっているかと思います。この３つがあえて挙げられている趣旨についてお伺いします。","respondent":"勝亦総務課長","answer":"こちらの制度ですが、たしか昭和５５年に支援していただきたいという請願が出たという記録を拝見しております。そういった中で、議会で全会一致でこちらを採択して、制度として立ち上げたという経緯です。","id":"exchange-158"},{"speaker":"松本委員","kind":"質問","question":"これはやはりこれからも区として予算を立てていく以上は、やはり趣旨・目的というのをより明確にしていく必要があると思います。今、区議会が請願を受けてという話がありましたが、区として、この補助金というのはどういう趣旨がある、目的があるとお考えか、伺います。","respondent":"勝亦総務課長","answer":"要綱の中で学校の指定をしていますけれど、こういった外国人の学校に在籍する児童・生徒をお持ちの保護者の方に対して、授業料の一部を補助させていただきまして、保護者の方の教育費の負担軽減を図ることを目的としております。","id":"exchange-159"},{"speaker":"松本委員","kind":"質問","question":"これは経済的な支援なので、経済的に苦しんでらっしゃるということを区としては考えて、支援されているということでよろしいか尋ねました。","respondent":"勝亦総務課長","answer":"国籍をもって全てという言い方は適切ではないかもしれませんが、これまでの歴史的経過の中で、現状の３つの種類の学校になっていると認識しています。","id":"exchange-160"},{"speaker":"松本委員","kind":"確認","question":"歴史的な経緯というのはいろいろあることと思いますが、確認しておきたいのですが、これは特定の民族学校を支援するという趣旨なのでしょうか。どちらか尋ねました。","respondent":"勝亦総務課長","answer":"こちらの制度の対象につきましては、まず、対象の学校を東京朝鮮学園、東京韓国学園それから東京中華学校としています。一方、対象者につきましては、先ほど申し上げましたとおり日本国籍を有しない者という形で、特定の国籍を求めているものではございません。","id":"exchange-161"},{"speaker":"松本委員","kind":"質問","question":"そうなってくると、例えばこちらの学校に通われようとする保護者であれば、戦時中とか関係なく、それこそ数年前に例えば戦争とは全く関係なく来日された方々であったとしても、これらの学校に通われる方に対しては、経済的な支援が行われているという理解でよろしいか尋ねました。","respondent":"勝亦総務課長","answer":"先ほどの要件に当てはまる方については支援するということになってあります。","id":"exchange-162"},{"speaker":"松本委員","kind":"質問","question":"まだこの制度の理由というところは、考えはいろいろあると思いますが、理由としては出てくるかもしれません。今お伺いすると、この３つの学校設置者について認めていくというのは、お伺いいたします。","respondent":"勝亦総務課長","answer":"一定程度こういった補助金をお渡しする中で、昭和５５年に制度を定めさせていただきまして、それまでの歴史的経緯の中からこのような形でやらせていただきまして、そういった中で一定程度のルールは必要かなというところで現在の形を維持しているものです。","id":"exchange-163"},{"speaker":"松本委員","kind":"質問","question":"この３つの学校に絞っている理由というのが、絞る必要があるということですが、もう一つ、それでは歴史的な経緯というのはどういう意味なのか、お伺いいたします。","respondent":"勝亦総務課長","answer":"昭和５５年に東京朝鮮学園に助成金等の交付をしていただきたいというお話をいただきました。今、委員もおっしゃいましたように戦争の部分もあろうかと思いますけれど、そこの解釈については様々あろうかと考えています。","id":"exchange-164"},{"speaker":"松本委員","kind":"質問・要望","question":"ほかの質問がもうできなくなってしまいましたが、今お伺いしたところで、なかなかこの支援の根拠というのは見いだしにくいのではないかと思います。よく分からない抽象的な差別的な言動にもつながる可能性があるので、これは差別の是正を求める側も考えていかないといけないのではないかと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-165"},{"speaker":"藤原委員","kind":"質問","question":"分かる方もいると思いますが、その辺についてお伺いしたいのは、結局ウェルビーイングというのは、具体的にどういうことを言っているのか。そういう意味において、ウェルビーイングの意味とウェルビーイングの逆はどういうことなのか、教えていただけますか。","respondent":"辻広報広聴課長","answer":"それがウェルビーイングかなと考えています。その逆ですが、いろいろな説があるかと思いますが、選択することができない状態が、逆の意味かなと思っています。","id":"exchange-166"},{"speaker":"藤原委員","kind":"提案","question":"なぜかというと、職員の提案は区長に通るのでしょ。では、これから職員提案制度プラス小さい会派提案制度というのもつくっていただきたいと思うのですが、いかがか尋ねました。","respondent":"佐藤企画課長、岡秘書担当課長","answer":"会派と議員の皆様の要望の政策反映ですが、区といたしましては非常に重要なことと考えております。会派からいただいている要望等も含めて、予算査定をしっかりしておりますので、そのようにご理解いただけるとありがたいです。秘書室で４人という少ない人数でやっていますので、日々コミュニケーションを大事にして、区長や副区長との円滑な職務遂行を行っております。","id":"exchange-167"},{"speaker":"藤原委員","kind":"提案","question":"新規の職員提案が入ってくると思いますが、明るい区長室にしていただきたいという思いで、質問させていただきました。次は、２１９ページの都議会議員選挙、補選について伺いたいと思いますとの意見を述べました。","respondent":"鈴木選挙管理委員会事務局長","answer":"国会議員、都議会議員、区議会議員の違いといいますか、上下というご質問です。それぞれ選挙区なり有権者なりの範囲も違いますし、それぞれに与えられた重い責任を全うしていただいていると考えております。","id":"exchange-168"},{"speaker":"藤原委員","kind":"質問・要望","question":"でも、それだけつながりがあるのだから、選挙管理委員はお給料もある程度出ているのだから、一緒に総務省へ行ってもらえばいいではないですか。私は、そこまでやはりしていただきたいと思っているのですけれども、その辺についてはいかがか尋ねました。","respondent":"鈴木選挙管理委員会事務局長","answer":"その場での現金やクレジットカードでの決済の場合は、事業者が掛け売りの請求ができないので使えないというのが現状です。去年も幾つか出しておりますが、今後もそういう機会を捉えて、しっかりと適正な選挙運動ができるように意見を上げていきたいと考えております。","id":"exchange-169"},{"speaker":"藤原委員","kind":"確認","question":"もう一点、確認だけです。選挙管理委員の報酬を下げますよということは、審議会で話せばできるのですよねということだけ説明を求めました。","respondent":"鈴木選挙管理委員会事務局長、勝亦総務課長","answer":"区の裁量で拒んだり、違う方法を取るということができないという制約はあります。ただし、その辺の整合性をどう考えるかという問題の提起についても、先ほど申し上げた国へ意見を上げる中で上げていきたいと思います。 選挙管理委員の報酬の関係です。選挙管理委員の報酬につきましては、その職責にふさわしい額を区議会の議決により条例で定めております。","id":"exchange-170"},{"speaker":"藤原委員","kind":"質問・要望","question":"同一労働同一賃金ということを言ってきましたが、役職が落ちてしまうのであれば、大体その額になっていくということの確認をさせていただきたい。それと働き方改革で、人材育成担当課長がやられていると思いますが、３６０度人事みたいことをやるではないか尋ねました。","respondent":"崎村人事課長、田口人材育成担当課長","answer":"条例改正を令和４年度に行いましたが、令和６年４月１日に役職定年を迎えるということで、制度が初めて適用されることになります。役職定年で降任した管理職については、現在支給している給料月額の７割が保障されると… 区では、今年度から人材育成の一環としまして、３６０度評価を試行実施しております。そのようなフィードバックをし合うというオープンな文化を庁内に定着させたいと考えて実施しております。","id":"exchange-171"},{"speaker":"藤原委員","kind":"質問・要望","question":"まだ目安箱というのはやっているのですか。その辺についてはっきり説明していただきたいのと、今日は新庁舎担当の課長が来ていますが、全然質問が来ないではないか尋ねました。","respondent":"田口人材育成担当課長、崎村人事課長、山下新庁舎整備課長","answer":"今回実施しているものはあくまでもポジティブなフィードバックに限ったところですので、いいところを伸ばすというところで実施しております。… 昨年の７月から、職員の声を聞きますということで区長室のドアもオープンになって、お声を聞くというスタンスで臨まれているところです。… 今期、委員長にもいろいろご協力いただきながら、年間の予定を超える回数でいろいろご説明を申し上げしています。","id":"exchange-172"},{"speaker":"鈴木委員","kind":"質問・要望","question":"私からは、１９１ページ、会計年度任用職員の待遇改善を求めて質問したいと思います。これはちょっと教えていただきたいのですが、総人件費削減とか定員管理計画をつくるようにと求められているのかなと思いますが、品川区として。","respondent":"崎村人事課長","answer":"１人当たりどのぐらいというのは、今回予算書でもお示しさせていただいていますが、手当の関係で５億円ほどを見込んでおります。毎年度の所要人員計画、所要人員の要求、それに対する定数条例のお示しということで、定数については議会にもお諮りしております。","id":"exchange-173"},{"speaker":"鈴木委員","kind":"質問・要望","question":"１,３８２人なので、その３分の１の方がどこにどういう形で配置されているのかという、ちょっとイメージがつくように教えていただきたいのですが。区として、この会計年度任用職員の待遇面での課題として捉えていることがあれば、どんなことなのかも伺いたいと思います。","respondent":"崎村人事課長","answer":"昨年の給与改定では、その関係で会計年度任用職員についても、昨年の４月に遡って報酬額を増額させていただいたところです。そういったことで、待遇の改善等は一定図られていると考えております。","id":"exchange-174"},{"speaker":"鈴木委員","kind":"質問・要望","question":"なぜ品川区は１年ごとに公募するやり方を取るのかということも伺います。２３区の中でもそういう区はあると伺っています。","respondent":"崎村人事課長","answer":"先ほど申し上げましたように、会計年度ごとに職の必要性を精査した上で実施するということ。国からの通知の中では、基本的には公募で実施するのが望ましいというお話をいただいておりますので、区としては、毎年度公募で実施しています。","id":"exchange-175"},{"speaker":"鈴木委員","kind":"質問・要望","question":"私は、これは改善が必要なのではないかなと思いますが、その点はいかがでしょうか。その点も伺いたいと思います。","respondent":"崎村人事課長","answer":"賃金が変わらないというところに問題意識はあるのかですが、報酬額の設定の考え方については先ほどお話させていただいたところです。福祉部の会計年度任用職員につきましては、８０名ほど配属されております。","id":"exchange-176"},{"speaker":"大倉委員","kind":"質問・要望","question":"確認ですが、改めて伺います。以前の質疑の中で、サイトは今２件かと思いますが、今後サイトの契約を増やしていくのかどうかというところを教えてほしいと求めました。","respondent":"鈴木選挙管理委員会事務局長、三井スポーツ推進課長、宮澤地域活動課長、篠田文化観光課長、提坂税務課長","answer":"小さな投票区では二、三十枚のところ、大きな投票区では１００枚程度出たなどという実績があります。同じ頃に議会でも同様の質問… 消防団にご協力をお願いできないかというところを、消防署に相談してまいりたいということで、お話をさせていただきました。… 町会ホームページの開設支援というのを区が実施しておりまして、それによって２８町会がホームページを開設しております。","id":"exchange-177"},{"speaker":"大倉委員","kind":"質問","question":"投票率の向上というところから、効果もあるのかなと思って伺ったのですが、ＳＮＳなどでも大分取り上げられて載っていたという意識があります。選挙割で地域にもお金が落ちるのかなと思いますので、その点について伺わせてほしいと求めました。","respondent":"田口人材育成担当課長、鈴木選挙管理委員会事務局長、提坂税務課長","answer":"今の研修に関するご質問についてお答えいたします。今現在はコロナが５類になったということで、充実させて、来年度以降も引き続き実施していくところです。それを商業施設で２次活用していただくのは結構ですが、選挙管理委員会から声をかけることは控えるようにという考え方があります。選挙で使う間… 品川縣ビールのセット等を取りそろえておりますが、確かに統一的なビジュアルというところではちょっと欠けている部分があります。","id":"exchange-178"},{"speaker":"あくつ委員","kind":"質問","question":"私からは、１８３ページ、全国自治体との連携事業、１８５ページ市町村交流事業、１９９ページ、地域センター等管理運営費について伺います。この駅のことが公表された後に、総務課もしくは文化観光課において、飯田市との交流の状況について説明を求めました。","respondent":"勝亦総務課長","answer":"区が開催しておりました物産展、それから地域の商店街のお祭り等に出店いただいております。リニアの停車駅になる予定の自治体が、その他一緒に出展して、リニアの開通に向けた共同ＰＲをしたところです。","id":"exchange-179"},{"speaker":"あくつ委員","kind":"質問","question":"リニアという新たな大動脈の誕生を控え、経済や防災について、品川とともにという思いがあることも伺っております。通勤・通学圏とも言える４０分で結ばれる飯田市との間で、例えば防災や文化、品川区のお考えを伺いたいと思います。","respondent":"勝亦総務課長","answer":"今ご案内いただきました災害と地域活性化といった中で、より多くの自治体と手を携えて、相互に活性化していくのは重要なことだと考えています。お互いに協力して、どう相乗効果が出せるかということをともに考えながら、交流・連携等を考えていきたいと思います。","id":"exchange-180"},{"speaker":"あくつ委員","kind":"質問・要望","question":"その対象となっているのかということを伺いたいのと、４０年以上たっていて、センターの在り方。建て替えも含めて、ぜひ検討してほしいと求めましたが、いかがか尋ねました。","respondent":"宮澤地域活動課長","answer":"６０年近くが目安なのかなというところではありますが、中の設備に関するところは、確かに地元の町会の方からもエアコンのお話もいただいております。","id":"exchange-181"},{"speaker":"あくつ委員","kind":"質問","question":"２年間、もう３年目に入りましたが、支援メニューの拡充をお願いしました。そのときにお約束いただきまして、現在、その当時と比べると１人増えて７人の方がいらっしゃるのですかね。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-182"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"初めにＳＤＧｓ推進事業補助金について、４点お尋ねしたいと思います。事業対象、実施時期、通常の助成事業との違い、類似事業の実施自治体があれば、どういった取組をしているのか教えてほしいと求めました。","respondent":"吉岡政策推進担当課長","answer":"５月から６月に実行委員会を設置させていただきまして、８月に最初の助成決定ができればというスケジュールで考えております。補助事業の決定や支援といったところを、民間の事業を実施するスピード感を持って、柔軟な対応ができると考えております。","id":"exchange-183"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"次に、ＳｕｓＨｉ Ｔｅｃｈ Ｔｏｋｙｏ ２０２４とはどういったものでしょうか。これは都が主催する事業と認識しておりますが、品川区の関わり方について教えてほしいと求めました。","respondent":"吉岡政策推進担当課長","answer":"２３区をはじめといたしまして、各自治体にも出展の依頼が来ております。ブース出展におきましては、外に開設されるステージで、区内団体にパフォーマンスを披露いただいたりといったところを検討しております。","id":"exchange-184"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"ゼロカーボンシティしながわ推進経費に１,３００万円の予算がついていますが、これはどのようなことをされるのでしょうか。お尋ねしたいと思います。","respondent":"吉岡政策推進担当課長","answer":"こちらの予算につきましては、コンサルへの委託経費ですが、ゼロカーボンの実現に向けた区の特性の分析や、企業へのヒアリングやアンケート、外部環境の偏向を捉えた、実効性の高い独自の政策検討、また、子ども向けワークショップなどを実施する予定です。","id":"exchange-185"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"昨年１０月に国連を支える世界こども未来会議inＳＨＩＮＡＧＡＷＡがありました。子どもたちから意見・アイデアをもらう未来志向の事業だと思いますが、実施してみての成果と感想をお知らせほしいと求めました。","respondent":"吉岡政策推進担当課長","answer":"区議会の皆様にご理解・ご協力いただきながら実施いたしました、国連を支える世界こども未来会議inＳＨＩＮＡＧＡＷＡの成果・感想です。次年度におきましても、改良を加えながら実施していきたいと考えています。","id":"exchange-186"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"これは最後に要望とさせていただいて、質問を終わりたいと思います。ありがとうございました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-187"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/664001?Template=document&Id=6689#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=3&TermStart=2024-01-01&TermEnd=2024-12-31"}],"sourceMeta":{"pages":0,"characters":132344,"voices":430}},{"id":"r06-20240308-3","meetingId":"r06-c-budget","date":"2024年3月8日","dateIso":"2024-03-08","committee":"予算特別委員会","time":"午前１０時００分～午後 ５時５６分","status":"正式会議録","sourceType":"formal","overview":"予算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を166件整理しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"澤田委員","kind":"質問","question":"保護者のサポートをすることは、不登校や孤立・孤独感の解決、非行を防ぐことへつながるのではないでしょうか。１クール６回となっていますが、もしお聞きになっていることがありましたら説明を求めました。","respondent":"松山障害者支援課長","answer":"苦手なことを減らすように声かけしていたが、私が否定的な注目をしていたと、ご自分の受け止め方が問題であったということに気づけました。それから、施設側の反響ですけれども、もともとペアレントトレーニングは応用行動分析の理論を基に子どもの対応を学び。","id":"exchange-001"},{"speaker":"澤田委員","kind":"質問","question":"様々な皆さん受けてよかったというような印象の回答が多かったと思うので、本当に素晴らしいと思います。ちょっと聞きそびれてしまったのですが、申込みのあった人数なども教えてほしいと求めました。","respondent":"松山障害者支援課長","answer":"申込人数についてですが、今ちょっと手元に詳細な数字がないのですが、定員６人を上回るということで報告を受けており、人気の講座となっております。","id":"exchange-002"},{"speaker":"澤田委員","kind":"質問・要望","question":"例えば１年に１回だけだったと思うのですが、前期・後期と分けて２回に分けたりとか、そういうような方法も検討してほしいと求めました。ペアレントトレーニングを受講する保護者の対象を、小学生だけでなく中学生にまで拡充することへの区の考え方を説明を求めました。","respondent":"松山障害者支援課長","answer":"悩みを多く抱える保護者がいらっしゃるとは聞いております。今実施している事業者、それから講師の方の声を聞きながら、発達障害児の支援の中で充実してまいります。","id":"exchange-003"},{"speaker":"澤田委員","kind":"意見","question":"児童自身が認知行動療法を学ぶことは、本人の抱える問題を自身で解決し、軽減することにつながると思います。こちらも講座を行えるとよいと思うのですが、専門家による講演会などを開催することがまずは大事かと考えますが、区の見解を説明を求めました。","respondent":"松山障害者支援課長","answer":"委員ご提案の講演会についてです。講演会の内容につきましてはまた事業所と相談しながら決定していければと考えています。","id":"exchange-004"},{"speaker":"澤田委員","kind":"質問","question":"きょうだい児が相談しやすい環境、そして相談できる窓口やツールなどが必要であると思いますが、そのような機関は現在ありますでしょうか。それらの必要性について、区としてはどのようにお考えでしょうか、お知らせください。","respondent":"松山障害者支援課長","answer":"現在日常の支援の中できょうだい児がいるご家庭について、例えば福祉サービスを導入するなど、相談員と連携して対応しております。インクルーシブひろばでは、引き続ききょうだい児支援にも配慮したきめ細かな支援というものに努めていきたいと考えています。","id":"exchange-005"},{"speaker":"ゆきた委員","kind":"確認","question":"私からは、２２５ページ高齢者安否確認事業の救急代理通報システム、福祉タクシー・自動車燃料費助成についてお伺いします。例年の申請者数、今後見込んでいる申請者数、また障害者対象要件の拡大の内容について教えてほしいと求めました。","respondent":"東野福祉計画課長、松山障害者支援課長","answer":"令和４年度から比べますと、４０台ほど増えてきているというような状況です。今後につきましては、利用者負担の無償化により拡大を図っていきたい、予算上では約１,５００台の計上をしています。今後の見込みについては、３０人増を見込みまして、令和６年度予算で９９人ということで予算を計上させていただいているところです。","id":"exchange-006"},{"speaker":"ゆきた委員","kind":"確認","question":"現在、高齢者・障害者を含めて登録者数が９００名を超える方が利用して、今後利用者が２倍を超えると見込んでいることを確認させていただきました。今回の無償化対象拡大を機に、より一層認知度を上げるための広報をしていくべきと考えますが、区の見解をお聞きしましたいと思います。","respondent":"東野福祉計画課長、松山障害者支援課長","answer":"救急代理通報システムにつきましては、区のホームページのほか、要介護認定を受けている方につきましては在宅介護支援センターですとか。支え愛・ほっとステーション、在宅介護支援センター… 無償拡大についての広報です。それから相談事業所を含め、全障害福祉サービス事業所へ周知を行いまして、救急代理通報システムの認知度を高めてまいります。","id":"exchange-007"},{"speaker":"ゆきた委員","kind":"質問","question":"このことは、たけうち忍元区議会議員が令和４年の一般質問で質問された内容ですが、希望者が漏れなく利用できるように訴えさせていただいていました。現在までに併用を希望された方がいたのか、もしいればその方への対応をどうされてきたのか、お聞きしたいと思います。","respondent":"東野福祉計画課長","answer":"事業者のほうに確認したところ数件問合せがあって、そちらにつきましては既に新機種への交換を行ったと聞いてあります。詳しい台数までは確認できていませんが数件あり、既に対応済みということで聞いてあります。","id":"exchange-008"},{"speaker":"ゆきた委員","kind":"質問・要望","question":"古いものを使っている場合、新しいものへの対応、取組を確認させていただきました。財産を守ること、両システムの併用を希望する方が漏れなく利用できるように改めて要望いたしますが、最後に区の見解をお聞きしたいと思います。","respondent":"東野福祉計画課長","answer":"委員からのご要望につきましては、事業者を通して、併用できるような形のものをつけていただきたいということで要望していきたいと思います。新機種につきましては現在不具合がないと聞いておりますので、新機種の導入につきましても併せて進めていきたいと考えています。","id":"exchange-009"},{"speaker":"ゆきた委員","kind":"質問","question":"時間がないので、次に２３３ページの福祉タクシー自動車燃料費助成についてお伺いいたします。終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-010"},{"speaker":"山本委員","kind":"確認","question":"２６７ページの子どもの未来応援事業について伺います。令和５年度では、目標５００万円に対して、支援人数２９１名により２,０５９万円余りを集めたと確認しました。","respondent":"飛田子育て応援課長","answer":"今回目標額を大きく超える寄付額となったため、寄付の一部を繰越明許としまして、また来年度にも執行する予定です。来年度には目標額を７００万円としまして、また民間企業からの支援も併せて引き続き取り組んでまいりたいと考えております。","id":"exchange-011"},{"speaker":"山本委員","kind":"質問・要望","question":"ひとり親支援を受けた地域の方からお話を伺ったのですが、武蔵小山パルム商店街にあるお好み焼き屋で、子どもも私も感動したと言っていました。このような外食クーポンの拡充を区が後押しし、支援の輪を広げることはいかがでしょうか、区のお考えを伺います。","respondent":"飛田子育て応援課長","answer":"先ほど言われたとおり、６店舗のところで２３４食が提供されたと企業より報告がありました。さらにこのような支援が広がっていくように取り組んでいきたいと考えております。","id":"exchange-012"},{"speaker":"山本委員","kind":"質問","question":"品川区でもデジタルでの外食クーポンの支援をしてはいかがでしょうか。区のご見解を伺います。","respondent":"飛田子育て応援課長","answer":"今後様々な手法が考えられると思います。このような先駆的な取組や他区の状況、またそのようなところを注視していきたいと考えております。","id":"exchange-013"},{"speaker":"山本委員","kind":"質問・要望","question":"デジタルを活用し、より効果的な子どもの食の支援の検討を要望し、次の質問に移ります。続きまして、２５３ページの子育て支援情報発信アプリについて伺います。","respondent":"藤村子ども育成課長","answer":"ダウンロード数ですけれども、現在リリースから４か月程度経過した状態ですが、２月末時点で２,５００ダウンロードというところになっております。「情報が探しやすくなったので今日このイベントに来た」とか、そういったお喜びの声をいただいているというところがあります。","id":"exchange-014"},{"speaker":"山本委員","kind":"質問","question":"前回のアプリのダウンロード数はどの程度だったのでしょうか。今回の具体的な目標数値はあるのか尋ねました。","respondent":"藤村子ども育成課長","answer":"こちらは昨年の１２月末で閉じたという形になっておるのですが、こちらのダウンロード数が最終で２万３,０００件程度という形になっております。当面の目標としては前回のこの２万３,０００ダウンロードというのを早期に達成するというところは目指していきたいと考えています。","id":"exchange-015"},{"speaker":"山本委員","kind":"意見","question":"小学生や中高生の子どもたちも対象に加えているので、今後はもう少し利用率を高めたいですね。開始したばかりですが、課題があればお教えくださいとの意見を述べました。","respondent":"藤村子ども育成課長","answer":"現在の課題といたしましては、現状では少し子ども向けのコンテンツが不足しているというような感想を持っております。ここだけの情報がここで入手できるですとか、利用者にとってマストの存在になるように、アプリを充実させていきたいとは考えております。","id":"exchange-016"},{"speaker":"山本委員","kind":"質問","question":"例えばしながわチャイルドラインなどの相談できるサイトの連携ができれば、より効果的になると考えます。有効な情報を効果的に提供するためには、関係部署による区役所内での横断的な連携が重要であると考えますが、どのようにされておりますか尋ねました。","respondent":"藤村子ども育成課長","answer":"庁内の連携という部分に関しましては、お知らせということで現在でも発信していただいているところです。ＵＲＬですとか、あとラインにそこからダイレクトでアクセスできるですとか、幅広く利用者目線の機能充実というのを図っていきたいと考えております。","id":"exchange-017"},{"speaker":"山本委員","kind":"質問・要望","question":"いかがでしょうか。要望してくれた人に何らかのインセンティブを付与し、対価を設定するのはいかがか尋ねました。","respondent":"藤村子ども育成課長","answer":"小学生、中・高生の拡大というところですけれども、アプリを入れていただくことはできないかということを協議してまいりたいと考えています。","id":"exchange-018"},{"speaker":"山本委員","kind":"提案","question":"続きまして、２４７ページのデジタル活用による高齢者社会参加促進事業の中で、はじめてのスマホ体験教室・スマホよろず相談について伺います。昨年の決算特別委員会でご質問、拡大や工夫のご提案をさせていただき、昨年の一般質問でもコメントをいたしましたとの意見を述べました。","respondent":"川原高齢者地域支援課長","answer":"令和６年度については、教室の会場を４会場から５会場へ増やし、年間で４０コースの開催を予定しております。そして、新たに講座を１講座追加して、初めて講座に加えて基本アプリ講座を新規の講座として開催の予定です。","id":"exchange-019"},{"speaker":"山本委員","kind":"質問・要望","question":"引き続き稼働率が高いこと、また１会場増やし、また講座の新設を図っていただくなど充実を図っていただくことと理解をいたしました。昨年の決算特別委員会での質問でご説明した内容のとおり、引き続き大幅なペースアップを要望して、質問を終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-020"},{"speaker":"安藤委員","kind":"質問","question":"昨日の新聞等で、生活保護の申請が最多２５万件との報道がありましたが、品川区での申請状況はどうでしょうか。増加しているのか、減ってきたのか伺います。","respondent":"豊嶋生活福祉課長","answer":"そして今年度ですが、１月までの数字で申請数３９７世帯となっております。昨年度から減少傾向にありましたが、今年度の数字の推移を見ていますと、コロナ時期の数字の推移とほぼ同数となっております。","id":"exchange-021"},{"speaker":"安藤委員","kind":"質問・要望","question":"ためらわずに自治体までご相談ください」との厚生労働省の記述を明記していただきたいのですが、いかがでしょうかというのが１つです。ぜひアップしていただけるよう求めますけれども、いかがか尋ねました。","respondent":"豊嶋生活福祉課長","answer":"確かにこの生活保護のしおりは令和３年の１０月に発行しているものですが、リーフレットのほうにはそうした文言は実は入れて配布をしてございました。今後、その辺りの文言は、こうした文言を入れる方向で今後議論を進めてまいりたいと考えています。","id":"exchange-022"},{"speaker":"安藤委員","kind":"質問","question":"先ほど件数をいただいたのですが、今年度扶養照会を行ったのが何件あって、そして援助が得られることになったのは何件だったのか。どの部分を聞き取るのかというのはあるのですが、直近のところで教えてほしいと求めました。","respondent":"豊嶋生活福祉課長","answer":"この３５１世帯のうち、そうしたことを踏まえて、実際に扶養照会をした世帯数は１２２世帯です。金銭的支援が行われた件数が２世帯、それから引取りをしてくださった世帯が２世帯、精神的な援助をしてくださった世帯が５世帯となっております。","id":"exchange-023"},{"speaker":"安藤委員","kind":"質問","question":"例えば１０年程度音信不通であるなど、交流が断絶していると判断される場合は、著しい関係不良とみなしてよいと挙げられています。この事務連絡なのですけれども、実際に窓口でどのように運用されているのでしょうか、伺いたいと思います。","respondent":"豊嶋生活福祉課長","answer":"この令和３年２月２６日の事務連絡の運用についてのご質問です。生活福祉課内の職員に広く周知をして徹底しているものですので、このとおりやるように、今も厳しく指導というか話をしています。","id":"exchange-024"},{"speaker":"安藤委員","kind":"質問・要望","question":"実際やられているということも、鈴木議員のほうからありましたけれども、そうなのです。関係が断絶しているようなところには扶養照会しませんよとしっかり伝えることを徹底していただきたいのですけれども、いかがか尋ねました。","respondent":"豊嶋生活福祉課長","answer":"この事務連絡自体は扶養照会を行わなくていい人を書いてあるものであって、扶養照会自体そのものをしなくていいというものではございません。","id":"exchange-025"},{"speaker":"安藤委員","kind":"質問・要望","question":"貧困の連鎖を断ち切るため、行政等のこの対応を見直すよう国に求めていただきたいのですが、いかがでしょうかというのが１つです。２つ目は、独自の支援制度を早急に具体化していただきたいのですけれども、いかがか尋ねました。","respondent":"豊嶋生活福祉課長","answer":"実際に丁寧にケースワーカー、相談員等々が援助について、給付型の奨学金等々についてもご案内をしております。世帯人数が減ったことによって減額される分については、奨学金で賄うことも可能ですので、その辺りで、今、お話をして対応しています。","id":"exchange-026"},{"speaker":"筒井委員","kind":"確認","question":"私からは、２２５ページ高齢者安否確認事業、２４７ページ認知症高齢者支援事業に関連して質問します。やはりこれは民間企業との連携をさらに強化していくということでよろしいのか尋ねました。","respondent":"東野福祉計画課長","answer":"それから企業と連携したネットワークの取組、そういったものと併せもって地域の見守りについては取り組んでまいりたいと考えています。","id":"exchange-027"},{"speaker":"筒井委員","kind":"意見","question":"救急ペンダント、私もこれは非常に重要で必要だと考えておるのですけれども、今回令和６年度の予算でなぜ無償化にするというご判断をされたのか。利用世帯が８００件ほど、今回無償化することによって利用者増を図るという、そうしたお考えがあってのことなのかどうかとの意見を述べました。","respondent":"東野福祉計画課長","answer":"まだ８７０件前後というところになりますので、これを拡大することによりまして、見守りを強化していきたい。これが区の考え方です。","id":"exchange-028"},{"speaker":"筒井委員","kind":"質問","question":"は６５歳以上のご家族のみの世帯の方とされておりますけれども、６５歳以上の方のみになるというその証明というか、結構それは厳しいのですか。それとも緩やかに捉えているのか尋ねました。","respondent":"東野福祉計画課長","answer":"あくまでも申請時に聞き取りをいたしまして、お困りの状態であるということが確認された場合に適用するというふうにしています。","id":"exchange-029"},{"speaker":"筒井委員","kind":"提案","question":"提案として、この救急代理通報システムの利用申請時に緊急連絡先の記入が必要ということがありますので、これがその役割を果たせるのかどうか。このことも、今私が言った万が一の連絡先としてスムーズに通報する、結果的にそういうことになるということになるのか尋ねました。","respondent":"東野福祉計画課長、川原高齢者地域支援課長","answer":"民生委員のほうにご協力をいただいて、高齢者実態調査というものを３年に一度行っております。ご本人から承諾が得られれば、何かあったとき安否確認の際に通知すると、連絡をするという手段もあります。認知症により外出時に行方不明になるおそれがある４０歳以上の方を対象として、無料でアイテムのグッズ、キーホルダーをお渡ししているような形です。","id":"exchange-030"},{"speaker":"筒井委員","kind":"質問・要望","question":"これは認知症ではなくてもよいというようなことを課長から伺いましたけれども、ぜひもっと区民に対して分かりやすくよろしくお願いします。これは要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-031"},{"speaker":"せらく委員","kind":"確認","question":"お便りについては、外出先ですぐにアプリから確認できて助かります。園の職員の事務作業、こちらの負担感としては、ＩＣＴ活用により変化や課題がありますか尋ねました。","respondent":"立木保育課長","answer":"セキュリティの関係で、直接写真を撮った業者がコドモンのほうに、現行の写真の販売システムをそのまま引き継いでいるようなところです。そういったことで、今後もできるだけ一本化をしていきたいと考えているところです。","id":"exchange-032"},{"speaker":"せらく委員","kind":"質問","question":"具体的な質問なのですけれども、前回のお話の中で、お着替えでは男女を分けるなどの習慣はあるか伺います。普段のお着替えと、水遊び、水着に着替える時で違いがあれば説明を求めました。","respondent":"立木保育課長","answer":"その着替えの際にはパーティションで目隠しをしたりとか、あとほかのお子さんの目に触れない、ほかの人の目に触れないような配慮をしております。","id":"exchange-033"},{"speaker":"せらく委員","kind":"質問","question":"第１子は月４万円、第２子以降は月６万７,０００円を、認可保育園の不承諾通知がなくても助成を受けられるということで間違いないでしょうか。そして、先日償還払いという話も出てきましたが、これまでどおり申請して助成を受け取る形になりますか尋ねました。","respondent":"石井保育支援課長","answer":"どのような施設であったとしても、保護者にとっては通う施設の選択肢が増える、これがすごくメリットであるというふうに考えてあります。こちらの申請方式に関しては、現在のところ償還払い方式を予定しています。","id":"exchange-034"},{"speaker":"せらく委員","kind":"質問","question":"適正な保育所の運営のために、改めて指導検査についてお伺いしたいと思います。認証保育所と認可外保育施設への指導検査の頻度を説明を求めました。","respondent":"立木保育課長","answer":"指導検査の回数、頻度のほうですけれども、認証保育所、認可外保育施設、東京都のほうが児童福祉法でやっている部分と、あと区のほうが現在、子ども・子育て支援法に基づいてやっている部分がありますが、区のほうで年に１回必ず実施をしています。","id":"exchange-035"},{"speaker":"せらく委員","kind":"質問・要望","question":"各園年に２回程度回られているというところでしょうか。その際に、指導検査により指摘された部分についての確認もされていますか尋ねました。","respondent":"立木保育課長","answer":"書類の確認だけで済ましているというような状況で、３年に１回というようなことがあります。検査の合間の巡回指導ですが、その辺の確認もしながら巡回の支援ということで助言指導をしているということで、全園２回ずつやってあります。","id":"exchange-036"},{"speaker":"こしば委員","kind":"質問","question":"２４７ページ、デジタル活用による高齢者社会参加促進事業について伺います。そういう中で、高齢者の方が認知症になるのを防ぐために、行政が高齢者と向き合っていく姿勢、考えについて説明を求めました。","respondent":"川原高齢者地域支援課長","answer":"私ども福祉部においても、高齢者の活動を支援する事業ですとか、見守りの事業なども実施しています。スマホ教室の場所を拡大して実施するというところと、今年度高齢者の方のアンケートを実施して、基本アプリ講座という形で開催をする予定です。","id":"exchange-037"},{"speaker":"こしば委員","kind":"質問","question":"上達の早い人がそうでない方に教えることによって、そこでまた交流が生まれてきた、そういったことなどをお聞きしました。先ほど課長の答弁の中で、ｅスポーツコースを新たに新設されたということでございましたけれども、その経緯について教えてほしいと求めました。","respondent":"川原高齢者地域支援課長","answer":"男性の方のよりよい参加の支援につながるものというところで、新たな展開というところでｅスポーツコースを開催した経緯ということもあります。男女にとらわれずに、高齢者の方の全ての方へのよりよい社会参加につながればよいと考えています。","id":"exchange-038"},{"speaker":"こしば委員","kind":"質問","question":"ぜひ男性・女性の参加率の向上に向けて取り組んでもらいたいと思います。こちらのほうの年間の回数だとか、あと地域、どういった地域で行われていくのか教えてほしいと求めました。","respondent":"川原高齢者地域支援課長","answer":"来年度、年間の実施回数１２回を予定しています。そして月の実施場所は１３地域にまんべんなく利用者の方にご周知をしていきたいと考えていますので、地区内全域で実施をしていきたいと考えています。","id":"exchange-039"},{"speaker":"こしば委員","kind":"質問・要望","question":"そうなりますとどうしても、例えば大井第二地域でやられる場合はつまり年間で１回、２０人の参加となります。その辺り、人数のほうも増やすことも検討してほしいと求めましたけれども、お考えを説明を求めました。","respondent":"川原高齢者地域支援課長","answer":"ご質問いただきました人数の拡充を図ってはいかがかというご質問です。中身のテキストであるとか教室の運営の仕組みを考えていく中で、運営いただく事業者などとも協議をしながら今後検討してまいりたいと考えています。","id":"exchange-040"},{"speaker":"こしば委員","kind":"意見","question":"デジタルに不得手な人、むしろその不得手な人の声をどんどん聞き取っていただいて、そこからまた気づくことがたくさんあると思います。それをまた次年度の事業にも置き換えていただくようお願いを申し上げまして、私のほうは終わらせていただきますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-041"},{"speaker":"横山委員","kind":"質問","question":"私からは、２２７ページ孤独・孤立対策推進事業、２５７ページ品川区子ども計画策定、２６７ページ養育費相談支援事業についてお伺いいたします。１点目に養育費相談支援事業についてお伺いいたします。","respondent":"飛田子育て応援課長","answer":"こちらの団体を利用して支援を受けた経費を補助するということで、想定としましては、１年間の利用で上限を１５万円と考えているところです。","id":"exchange-042"},{"speaker":"横山委員","kind":"質問","question":"ほかの区の動向等も注視していただきながら、必要な方々に最新の情報提供をお願いしたいと思いますが、いかがでしょうか。２点目に、品川区子ども計画策定についてお伺いいたします。","respondent":"飛田子育て応援課長、藤村子ども育成課長","answer":"ひとり親家庭のしおりについてですが、委員おっしゃるとおり、こちらのほうにつきましても積極的に周知を図ってまいりたいと思います。平成３０年度および平成３１年度の子ども子育て支援事業計画につきましては、予算ベースでいくと２か年で１,８８０万円程度というところ。","id":"exchange-043"},{"speaker":"横山委員","kind":"質問","question":"３点目に、地域福祉推進費についてお伺いいたします。２０代、３０代の孤独・孤立感が顕著に表れていますが、性別による結果の分析などありますか尋ねました。","respondent":"東野福祉計画課長","answer":"区が令和４年度に行いましたアンケート調査の項目ですが、性別の問いは設けておりませんでした。女性では３０代、次に２０代が高いという結果が出ているところです。","id":"exchange-044"},{"speaker":"横山委員","kind":"意見","question":"生きやすい地域を広げていくために、さらなる啓発活動や相談体制の構築をお願いしたいと思っています。孤独・孤立の解消に向けて、孤独・孤立対策シンポジウムの開催時などに啓発活動をお願いしたいと考えますが、区のご見解を説明を求めました。","respondent":"東野福祉計画課長","answer":"委員からご指摘のありました点、とても大切な視点だと思ってあります。区で取り組んでいる「おたがいさま運動」の趣旨からも、そういった啓発活動、ご紹介などをしていきたいと考えています。","id":"exchange-045"},{"speaker":"新妻委員","kind":"提案","question":"２２５ページ高齢者安否確認事業、２５３ページ児童センター運営費、関連をして若者の心と体の健康について伺います。人生の総仕上げをどう迎えていくのかについて、終活について提案・要望させていただきましたが、区の認識をお伺いしたいと思いますとの意見を述べました。","respondent":"東野福祉計画課長、菅野高齢者福祉課長","answer":"終末期にどのような治療やケアを行いたいのかとか、そういった希望をまず書き取ることから始めましょうというところでご紹介をしています。そういったところの区民への周知を今後も行っていきたいと考えています。認定率につきましては、令和５年度末で大分認定の数が増えておりますので、１万６,０００人弱ぐらいになるのではないかと推測しているところです。","id":"exchange-046"},{"speaker":"新妻委員","kind":"質問・要望","question":"そして、次に若者支援というところで伺ってまいります。品川区の若者の心と体の健康についてどのように認識をされているか、お伺いをいたします。","respondent":"藤村子ども育成課長","answer":"相談を受けてワンストップで解決するというような状況ではなくて、やはりそこからまたほかの機関につなげるですとか、そういったような形で今のお悩みの相談を受けているような形になっております。","id":"exchange-047"},{"speaker":"新妻委員","kind":"質問・要望","question":"性教育や食育、肥満、やせなど、自身の体に関する様々な健康教育の充実について、より積極的な取組が求められていると報告がされました。そのような若者が、気軽に医師や、またカウンセラーなどの専門家に相談できる場所が必要ではないかと考えますが、区の見解を伺います。","respondent":"藤村子ども育成課長","answer":"区におきましてもどのような形で、思春期特有の様々な悩みですとか、相談に対応できるようなサービスというのを行っていければと考えております。中でも、ＳＮＳ等が活用できて、できるところからやれることをやっていきたいとは考えております。","id":"exchange-048"},{"speaker":"新妻委員","kind":"質問・要望","question":"例えばそういうような団体にもまたアドバイスを求めながら、ぜひ品川区での若者の心と体の相談体制の構築をお願いしたいと思います。要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-049"},{"speaker":"おぎの委員","kind":"質問","question":"本日は、２３９ページ超短時間雇用促進事業と、２４５ページ品川区介護職員居住支援手当についてお伺いします。企業とのマッチングを行うということですが、コーディネーターの配置は何人ぐらいを予定していて、どういった企業を予定しているのか尋ねました。","respondent":"松山障害者支援課長、崎村人事課長","answer":"今年度既に前倒しでモデル実施をいたしまして、１月に超短時間雇用シンポジウムを開催いたしました。来年度はもう本格的に実施するということで、今年度も企業に障害者支援課の職員とともにアプローチをもう開始していますが。品川区では令和４年度から、そういった仕事を集約して仕事を行っていただいている業務支援室というものを設置しております。","id":"exchange-050"},{"speaker":"おぎの委員","kind":"質問・要望","question":"何より現場の介護職の方々の労働環境改善のために検討してみるのも有効だと思われますが、いかがでしょうか。ご見解をお聞きします。","respondent":"菅野高齢者福祉課長","answer":"区におきましては、社会福祉協議会とタイアップさせていただきまして、品川区介護福祉専門学校のほうを平成７年度から運営しております。ここにおいて、今後介護学校でどのように展開しているかというのは進めていきたいと思っているところです。","id":"exchange-051"},{"speaker":"西村委員","kind":"質問・要望","question":"どのようなプロセスをお考えでしょうか。世田谷区は質問を具体化して、「なんでやねんすごろく」を実施していると伺いました。","respondent":"藤村子ども育成課長","answer":"１回目と２回目で経過観察というか同様の方に意見をお伺いできれば一番いいのですけれども、そちらについては今後の検討事項かなとは考えております。やはり子どもに限らず、それに対してご意見をいただいて、それを計画に反映できるタイミングでやっていきたいと考えています。","id":"exchange-052"},{"speaker":"西村委員","kind":"質問","question":"昨年、私が帰省する際に視察に伺った尼崎市の「あまらぶチャレンジ事業」では、世田谷区の青少年交流センターなど複数の中高生が過ごす場所では。品川区でも、子ども若者の「やりたい」を実現するために応援していくような取組はできないでしょうか、伺います。","respondent":"藤村子ども育成課長","answer":"例えば児童センター、事業であればすぐお声かけしてこういった場を設定するということは可能と思いますので、ご提示された事項に応じて対応してまいりたいと思います。","id":"exchange-053"},{"speaker":"西村委員","kind":"提案","question":"実際に伺いましたところ、選ばれると、それを実践するための応援金が上限５万円で交付されると。ワークショップなどで子どもの意見形成支援をしつつ、具現化する取組を提案させてほしいと求めました。","respondent":"藤村子ども育成課長","answer":"こども大綱のほうを踏まえて子ども計画をというようなお話かと思います。数点ほかにも記載されているところなのですけれども、多くの方の意見を聞くことで、子ども計画というのを策定してまいりたいと考えております。","id":"exchange-054"},{"speaker":"西村委員","kind":"質問・要望","question":"次に、私立幼稚園の在り方について、以前にも質問していますが、区の中でも取組が進んでいることがありますので、伺ってまいりたいと思います。区の担当課の職員の皆様から出てくる自由なアイデアが柔軟に実現される環境下で、保護者のニーズをつかみ、求められる具体的な施策は何か。","respondent":"石井保育支援課長","answer":"例えば長期預かりのときに保育園と連携しながら、預かり事業の申込みとかいろいろ手助けできないかということで、現場レベルで非常に努力しています。","id":"exchange-055"},{"speaker":"中塚委員","kind":"質問・要望","question":"２４５ページの介護職員居住支援手当および障害者福祉の職員も一緒に伺いたいと思います。続いて２４３ページの特別養護老人ホーム運営費についても伺いたいと思います。","respondent":"菅野高齢者福祉課長、松山障害者支援課長","answer":"介護職員の居住支援手当についてお答えします。は東京都の特別支援手当の対象者、今後、対象者についてはさらに検討していきたいと考えています。 障害分野における居住支援手当につきましても高齢者と同様、直接処遇に係る障害福祉サービスの従事者ということにしています。介護職員と同様、今後、国や都の動向を見ながら、詳細には詰めていきたいと考えております。","id":"exchange-056"},{"speaker":"中塚委員","kind":"提案","question":"とりあえず介護のほうに伺いますけれども、先ほど伺ったのは、私は事務職までしっかり対象にしていただきたいとご提案をさせていただきました。ぜひ事務職も含めて、この新たな居住支援手当の対象にしてほしいと求めましたが、いかがか尋ねました。","respondent":"菅野高齢者福祉課長","answer":"こちらの居住支援手当はあくまでも介護職員というところがまずは基本だと捉えております。それを支える事務職など、今後事業者や関係者機関と協議をしながら、詳しいところは詰めていきたいと考えています。","id":"exchange-057"},{"speaker":"中塚委員","kind":"質問・要望","question":"事務職については、その協議をするにあたって、区としては事務職を対象にしたいと考えているのかどうかを伺いたいと思います。ぜひ事務職を対象にしてほしいと求めましたが、区としてはどう考えているのか、改めて伺いたいと思います。","respondent":"菅野高齢者福祉課長","answer":"区内事業者において、直接処遇に係る介護サービス従事者に対して区独自の手当を支給することとなっております。ここの、国の調査結果を見ても明らかに賃金格差があるというところに着目した目的の手当ですので、まずはそこを中心に考えていきたいと思います。","id":"exchange-058"},{"speaker":"中塚委員","kind":"質問","question":"ですから、事務職は対象にしないというのが区の考えなのか伺いたいと思います。","respondent":"菅野高齢者福祉課長","answer":"恐らく事務職だけではなくて、介護事業所にはほかのいろいろな職種の方もいらっしゃると思います。そのことも含めて検討しなくてはいけないと思っているところです。","id":"exchange-059"},{"speaker":"中塚委員","kind":"質問・要望","question":"グループホームにしろ、障害者福祉の施設も含めて、そこで働いている方々全員を対象にしていただきたいと強く要望したいと思います。区長の施政方針では、増加するニーズに特別養護老人ホームはあるのかないのか伺いたいと思います。","respondent":"東野福祉計画課長","answer":"これまでも在宅支援を重視しつつ、小規模多機能型居宅介護も含めた様々な整備を進めることで、区民の選択肢を広げてまいりました。限られた資源を活用しながら、整備を進めていきたいということで考えてあります。","id":"exchange-060"},{"speaker":"中塚委員","kind":"質問・要望","question":"私が伺ったのは、総合的に検討するとの答弁がありました。この中に、特別養護老人ホームの増設は入っているのかと伺いました。","respondent":"東野福祉計画課長","answer":"特別養護老人ホームにまだ入居待ちの方もいらっしゃるという事実がありますので、あるというふうに認識しております。それを踏まえた上で、区としてできることをやっていきたいと考えています。","id":"exchange-061"},{"speaker":"中塚委員","kind":"質問","question":"これがなぜなのかと伺いたいと思います。私は３か所目以降のさらなる特別養護老人ホームの考えを持ち、計画を具体化することが必要だと思いますが、いかがか尋ねました。","respondent":"東野福祉計画課長","answer":"区として所有している土地、それから民間が所有している土地、そういったものも含めましてできることをやっていくつもりです。現在のところ計画がない実態はありますが、今後区として総合的に検討してまいります。","id":"exchange-062"},{"speaker":"中塚委員","kind":"質問・要望","question":"できることをやっていく、総合的に検討する、結局３か所目以降の特別養護老人ホームの方向性は何も示されていないのですね。さらなる特別養護老人ホームの増設の考えを持っていただき、具体化していただきたいと要望して終わりたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-063"},{"speaker":"ひがし委員","kind":"質問・要望","question":"医療的ケア児等支援関係機関連絡会について記載がありましたので確認をしたところ、令和３年、令和４年と年に１回実施をしているようです。これとは別にあるコーディネーター連絡会というのはどういったものなのか、改めて確認をさせてください。","respondent":"松山障害者支援課長","answer":"今年度は１回実施を既にしておりまして、２回目が３月の下旬に開催予定です。次年度につきましては連絡会と位置づけまして、研修や事例検討を含め、定期的に実施する予定です。","id":"exchange-064"},{"speaker":"ひがし委員","kind":"質問・要望","question":"情報共有というものは連携強化のためには重要であると考えておりますので、また内容についても充実をさせてほしいと求めました。この目標の３回にも届きますし、区の見解、また課題があれば説明を求めました。","respondent":"松山障害者支援課長","answer":"障害者支援課が、まず退院調整からの支援を始め、横断的につないでいくということになります。現在は現実的に障害者支援課が中心になりましてコーディネートし、あるいは研修、連絡調整も含めて行っていくことを想定しております。","id":"exchange-065"},{"speaker":"ひがし委員","kind":"質問・要望","question":"ぜひ柔軟に考えていただき、困っているご家族の負担がさらに軽減をすることを求めまして、次の質問に移ります。次は避難行動要支援者個別計画作成について伺います。","respondent":"松山障害者支援課長、菅野高齢者福祉課長","answer":"令和３年度から実施しておりまして、令和３年度については、モデル実施として４４人作成済みです。そして今年度につきましては、直近で８０人の方を作成しております。 令和２年度のモデル実施から始めまして、令和６年１月現在で累計約８,０００件の原案を作成いたしました。令和６年度は新たに３,０００件の原案を作成する予定です。","id":"exchange-066"},{"speaker":"ひがし委員","kind":"質問","question":"まだ少し進捗が遅いのではないかというような、障害を持っている方のご家族のほうからの声をいただいていたりします。高齢者支援課のほうについては、８割ほどは原案の作成ができているのかと認識をしておりますが、簡単で大丈夫なので説明を求めました。","respondent":"松山障害者支援課長、菅野高齢者福祉課長","answer":"きちんと１人ずつ個別に対応しているのが現状でして、お待たせしている方には申し訳ないと考えています。着実に計画作成をしてまいります。高齢者の部門につきましては、本来なら避難行動要支援者は要介護度１から５の認定を受けている方なのですが、区では要支援者１。","id":"exchange-067"},{"speaker":"ひがし委員","kind":"質問・要望","question":"高齢者支援課のほうは、そこについてはそれぞれの課でしっかりと進めていただければよいと思います。その点、ぜひ地域と連携してやっていただきたいと私の中では思っているのですけれども、その点について区の考え方を教えてほしいと求めました。","respondent":"菅野高齢者福祉課長","answer":"可能な限り本計画に移行を進めているのですけれども、利用者や関係者との調整に留意し、取り組んでいるところです。ただし、防災課と令和４年度モデル事業を実施させていただきまして、やはり支援者を結びつけるところの難しさを感じているところです。","id":"exchange-068"},{"speaker":"ひがし委員","kind":"確認","question":"この点は質問がかぶらないように質問させていただきたくて、私の中では１点だけ確認をさせていただければと思っています。この事業に子どもの権利が守られているのかというところだけ、１点確認させてほしいと求めました。","respondent":"飛田子育て応援課長","answer":"もちろん養育費というところもあるとは思いますが、我々としましては、一番はやはり子どもにとっての一番の利益ということを考えております。そういうところで成長を見守っていることを実感していくことが、子どもの福祉向上につながっていくのではないかと考えております。","id":"exchange-069"},{"speaker":"ひがし委員","kind":"質問・要望","question":"ぜひ、子どもの気持ちというところを第一に考えた制度になるとよいと思っています。私たちもすごくよいことだと思っているので、その親子にとってよりよいものになるよう求めまして、私からの質問は終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-070"},{"speaker":"つる委員","kind":"質問","question":"２４６ページ高齢者地域支援費、２２７ページ孤独・孤立対策推進事業、２５７ページすまいるスクール運営費について伺っていきたいと思います。児童相談所ですが、昨日の質疑でしながわ見守りホットラインの無料化については見解を伺いました。","respondent":"長谷川児童相談所開設準備課長","answer":"児童虐待の通告先になりますけれども、令和６年１０月１日児童相談所開設後は、品川児童相談所から引き継ぎまして、区児童相談所が受け付けることになります。","id":"exchange-071"},{"speaker":"つる委員","kind":"質問","question":"１０月の開設以降というのは、品川区には東京都の児童相談所、そして品川区立児童相談所がある。これはどちらにつながるのか、そこを説明を求めました。","respondent":"長谷川児童相談所開設準備課長","answer":"今のお話ですけれども、児童相談所開設後は、同様に区児童相談所のほうに通告が走ることになります。その方の一義的には発信地を特定してつながっていきますけれども、その後の振り分けで区児童相談所のほうにつながる仕組みとなっております。","id":"exchange-072"},{"speaker":"つる委員","kind":"提案","question":"まだそこの段階では国や東京都との確認作業というところで明確ではなかったわけでありますけれども、通告先、周知の徹底をお願いしたいと思います。","respondent":"川原高齢者地域支援課長","answer":"２月に実施した平塚橋ゆうゆうプラザにおいては私も視察をさせていただいたところです。引き続き児童センターとの連携も視野に入れて、関係部署との協議は引き続き進めていきたいと考えています。","id":"exchange-073"},{"speaker":"つる委員","kind":"提案","question":"これはちょっと今から提案する、また確認する案件としては、民生費のところの部分で可能な範囲で品川区の現状を伺いたいと思ってありますが。","respondent":"川原高齢者地域支援課長","answer":"委員ご指摘のとおり、都のほうでも人生１００年時代を想定した社会参加のマッチング事業というところも新たに事業の説明があったところです。","id":"exchange-074"},{"speaker":"つる委員","kind":"質問・要望","question":"今度は産業経済費のところでも伺っていきたいと思いますけれども、品川区が一番参考とされるような施策展開をお願いしたいと思います。法律自体は今年の４月から施行ですけれども、孤独・孤立の強化月間が毎年５月に設定をされているわけでありますが、説明を求めました。","respondent":"東野福祉計画課長","answer":"昨年秋ぐらいにトー横キッズ問題などでオーバードーズの報道が取り上げられていたというふうに認識しています。オーバードーズの背景となっている孤独・孤立を防止するため、予防するためという観点で、今、行政のほうは進めているところです。","id":"exchange-075"},{"speaker":"つる委員","kind":"質問","question":"それから近年はそのオーバードーズのことについても若干触れていただいている学校もあるというふうにも伺っておりますので。すまいるスクールですが、五、そういった観点も含めたその視点での朝のすまいる対応についての現状の品川区の認識を説明を求めました。","respondent":"藤村子ども育成課長","answer":"朝のすまいるスクールについてというようなご質問についてお答えいたします。放課後の全児童対策事業として実施しているというところですので、何かできないかというところは課題として考えていきたいと思います。","id":"exchange-076"},{"speaker":"つる委員","kind":"意見","question":"ゆうゆうｅスポーツ交流会についてもご答弁いただければよかったのですけれども、時間がなかったので慌てて答えていただいたかと思いますが、この朝の対応については教育委員会含めて、引き続き様々な観点で品川区として検討ほしいと求めました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-077"},{"speaker":"やなぎさわ委員","kind":"提案","question":"おぎの委員が質問されていた介護専門職の登録紹介という制度の提案、先ほどのお話で、紹介会社を使うと８９万円ぐらい平均でかかってしまうと。これについて区としてどうお考えなのか、率直なご意見をお聞かせいただけますかとの意見を述べました。","respondent":"菅野高齢者福祉課長","answer":"この会社の中でのそういうルールが決まっていて、年収の２割から３割を手数料にというのがちょっと慣例的になっているというふうにも聞いております。","id":"exchange-078"},{"speaker":"やなぎさわ委員","kind":"質問・要望","question":"なので、結構これは大きなことだとぜひ受け止めていただきたい。ぜひその辺は頭の隅に入れておいていただきたいということと、介護人材の登録について、その辺もう少し詳しく説明を求めました。","respondent":"菅野高齢者福祉課長","answer":"そこで人材育成をして、そこで区内の事業者のほうにあっ旋というかマッチングをするということを行っているというのが背景にあります。その中で、登録の方法とか今後どうしていくかなどについては、効果的な方法等も考えながら検証していきたいと考えています。","id":"exchange-079"},{"speaker":"やなぎさわ委員","kind":"質問・要望","question":"３年間働かなくてはいけないということで、ぜひこれは枠を拡大してほしいというのと、進めていただきたいと思うのです。その分賃料を職員に回せるということになりますので、ぜひそういったことを前向きにお願いしたいのですけれども、その見解をお願いします。","respondent":"菅野高齢者福祉課長","answer":"そこについては営業職の配置の支援をするなど、区としてもいろいろ支援して、まずはその辺りのところの強化から始まるのかなと思っているところです。","id":"exchange-080"},{"speaker":"やなぎさわ委員","kind":"質問","question":"次に行きます。いわゆるスマホとかＰＣが使いこなせない人と、そうでない人に差が生じるのを解消するためにということの事業の一環でよろしいか尋ねました。","respondent":"川原高齢者地域支援課長","answer":"今委員がおっしゃっていただいたデジタルディバイドの解消ということに加えまして、高齢者の方の生きがいの創出ですとか、あと人と触れ合うことによる社会参加促進というところも、フレイル予防、認知症予防の点からも兼ねております。","id":"exchange-081"},{"speaker":"やなぎさわ委員","kind":"質問","question":"実はこういったスマホのよろず相談とか体験教室みたいなのを無料でやっている方がいるのはご存じですか。１人教えてしまうと皆がわあっと来てしまったりして仕事が回らなかったりするので断ってしまったりとか。","respondent":"菅野高齢者福祉課長","answer":"高齢者のデジタルディバイドの関係だと思うのですけれども、その中で介護事業所の職員たちが、そのように縁の下の力持ちで支えてくださっているということに感謝したいと思います。","id":"exchange-082"},{"speaker":"やなぎさわ委員","kind":"意見","question":"デイサービスの中で、これは対応しては駄目だよとか、忙しいのだからやめてよとか職員の中でけんかになるのです。そういうことで簡単にできるようなその相談、サービスも多いので、対応していただくように検討してほしいと求めました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-083"},{"speaker":"せりざわ委員","kind":"質問・要望","question":"プレス発表の８７ページ、２６７ページ養育費相談支援事業、時間があれば２５９ページの産後の家事育児支援についてお伺いをしたいと思います。ｅスポーツのお話は今のつる委員からいただきましたので、１点だけお伺いをしたいと思います。","respondent":"藤村子ども育成課長","answer":"しっかりどういった、児童センター全体でどう活用しようかというところを決めた上で、今回のゆうゆうｅスポーツ交流会が開催されたというところです。","id":"exchange-084"},{"speaker":"せりざわ委員","kind":"提案","question":"養育費の支援というのもこれまで何度も、そもそもの区の支援の創設から拡充も含めていろいろ提案をしてきました。は、名前は一緒ですけれども制度が大きく拡充していくわけですから、これの周知をどのようにしていくのか説明を求めました。","respondent":"飛田子育て応援課長","answer":"区としてもそういうことに対しまして、また新たに今回交流支援と、またＡＤＲの支援というところでプラスさせていただきました。そのほかにも戸籍住民課とも連携していきまして、またホームページ上にＱＲコードなどをしまして、周知の工夫をしていきたいと考えています。","id":"exchange-085"},{"speaker":"せりざわ委員","kind":"質問","question":"そもそも母子世帯で３０％以下と言われていて、父子世帯で言えば１０％よりも満たないと言われています。ですから、この遡及も含めてどういった周知をするのか、改めて説明を求めました。","respondent":"飛田子育て応援課長","answer":"そのほかに動画作成も考えておりまして、今回養育費のこの支援のところではいろいろ分かりにくい制度もありますので、それも含めてＰＲ動画のほうも作成していって周知を図りたいと考えております。","id":"exchange-086"},{"speaker":"せりざわ委員","kind":"提案","question":"区がそれに乗り出すということですから、このように支援が拡大しましたというのは、ぜひ大きくＰＲをしてほしいと求めました。時限的に延長になったと理解していますが、とはいえ令和７年ですか、一定程度でまた期限が来てしまうとの意見を述べました。","respondent":"飛田子育て応援課長","answer":"現在国が２分の１、都が４分の１、区が４分の１ということで継続することとなりました。この先、万が一都の補助が終わるということがありましても、区としてはこの政策をしっかり進めていきたいと考えております。","id":"exchange-087"},{"speaker":"せりざわ委員","kind":"質問","question":"ほかの補助制度では恐らくないものですから、これぐらいの支援で、両親で子どもを育てていくのだというのはぜひ進めてほしいと求めました。防災の観点からにはなるのですが、液体ミルクを今どのように活用していくのか、まずそれだけ先にお伺いいたします。","respondent":"藤村子ども育成課長","answer":"液体ミルクの自動販売機の件です。設置のほうを今検討していますが、できるかどうかというところは今後の設置の過程で対応となってまいりますので、今後の検討課題かと考えています。","id":"exchange-088"},{"speaker":"せりざわ委員","kind":"質問・要望","question":"は今回１か所でというふうな予算案かと思いますが、ぜひこれは様々なところにお広げいただきますように、これは要望で終わります。もう一点、産後うつについてお伺いをします。","respondent":"染谷子ども家庭支援センター長","answer":"男性の産後うつに対する予防的なところの対応というお話ですけれども、現在産後ドゥーラのほうで産後の家事・育児支援を実施しておりますが、そういったところで対応させていただけるかと思います。","id":"exchange-089"},{"speaker":"石田（し）委員","kind":"質問","question":"私からは、２５１ページの国民年金事務費についてと、２５０ページからの児童福祉費の中だと思うのですが、少子化対策全般についてお伺いします。","respondent":"菅野高齢者福祉課長","answer":"在宅サービスセンターと、そういった介護事業者の部分について、スマホのちょっとした助言とかしていただいているというところは認知いたしました。今後、どのようなことを提案していただけるのかというところも、区全体の事業も含めて検証していきたいと思います。","id":"exchange-090"},{"speaker":"石田（し）委員","kind":"質問","question":"私の質問に入ります。そして、国や都からのどのような少子化対策支援というのが補助金等で行われているのか説明を求めました。","respondent":"佐藤企画課長、藤村子ども育成課長","answer":"少子化の原因ですが、育児に関わるコストや仕事との両立の負担、また育児への不安、未婚・晩婚化等々と言われていると認識しております。様々そういった子育て支援は継続して行っているところです。 少子化対策に係る特定財源というところですけれども、そちらのほうは、今区のほうで受けている補助金の中では、その少子化対策ということで中心にいただいているというものはないかと認識しております。","id":"exchange-091"},{"speaker":"石田（し）委員","kind":"質問","question":"こういったことについてどのように考えているのか、教えてください。そしてもう一つ、そのまま国民年金のほうに行きますが、国民年金の給付額というのはどのように算定されて給付されているのか説明を求めました。","respondent":"佐藤企画課長、池田国保医療年金課長","answer":"先ほどの委員からご紹介のありました未婚・晩婚の対応については、安全安心なサービスの提供、それらの動向について理解をしているところです。賃金に関しましては国のほうで様々対応しているというのも把握しているところで… 年金につきましては国のほうで毎年、翌年の年金満期額というのが示されまして、４８０月納めた方についてはその満額を支給する形になりますけれども。違いますか。","id":"exchange-092"},{"speaker":"石田（し）委員","kind":"質問","question":"いわゆる年金の額を決定する方法というのは、どのような方法でこの年の金額というのは決まっているのか教えてください。給付額です。","respondent":"池田国保医療年金課長","answer":"給付額とは年金の額ということだと思います。物価連動のスライド制を使ってやっているところです。","id":"exchange-093"},{"speaker":"石田（し）委員","kind":"意見","question":"これは物価の高騰もそうなのですけれども、実は現役世代の給料もこれは算定の一つですね。お答えくださいとの意見を述べました。","respondent":"池田国保医療年金課長","answer":"それと実際に支払っていない月数で決めていくというだけですので、大変申し訳ないのですけれども、細かなところまでは分かりません。","id":"exchange-094"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"ぜひここは森澤区長のリーダーシップの下、もちろん２３区のいろいろな事情もあるし、そこはぜひ頑張ってほしいと求めました。これはよく考えたほうがよいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-095"},{"speaker":"塚本委員","kind":"質問・要望","question":"それから、２５５ページの児童センター学習用Ｗｉ－Ｆｉ設置・運用、時間があれば２４７ページの高齢者社会参加支援について伺いたいと思います。３館について、これはどこなのかというのがもし決まっているのであれば教えていただきたいというのと、説明を求めました。","respondent":"藤村子ども育成課長","answer":"こちら設置予定の館としては、冨士見台児童センター、東大井児童センターの３館を予定しているところです。この３館というのが中・高生の利用が多いティーンズ館になっておるというところと、こちらをセレクトさせていただいたというような形です。","id":"exchange-096"},{"speaker":"塚本委員","kind":"質問","question":"今理由もお聞きしましたけれども、今後残りの館についても拡大という方向であるのかどうか、そこだけご答弁お願いします。","respondent":"藤村子ども育成課長","answer":"ちょっとゲーム機とかそういったものに使われることはないかですとか、運用の方法をしっかり見極めて、今後拡大というところを図っていきたいと考えております。","id":"exchange-097"},{"speaker":"塚本委員","kind":"質問","question":"全会一致でこれは賛成、成立と伺っております。そういった形になっていった理由、その上でこのような結論になったということについての議論の経過というのをお聞きいたします。","respondent":"川崎障害者施策推進課長","answer":"戸越地区児童発達支援センター等整備ということで、大原児童センター内に区内２か所目となる大原児童発達支援センター整備を行うもの。ベルがこの連携の橋渡し役になると考えておりますので、一括で一つの案件として指定管理者の選定を行うものと考えております。","id":"exchange-098"},{"speaker":"塚本委員","kind":"質問","question":"こういった形での児童センターと児童発達支援センターのこういう考え方というか施設のありよう、これは結構全国的に見てもどうなのでしょうか。そういったところについての認識をお伺いしたいのと、これについてはいかがでしょうか、説明を求めました。","respondent":"藤村子ども育成課長","answer":"児童センターに関しましては、児童センター条例の中にこの指定管理を可能とするものを入れ込んでおります。児童発達支援センターの複合施設というのは、今予定しているところはないですけれども、いろいろな方がご利用いただけるような形で。","id":"exchange-099"},{"speaker":"塚本委員","kind":"質問","question":"そういった中で現実問題として、これを一つの指定管理者が受けていくというところについては、厚生委員会でもいろいろ議論があったと伺っております。そういったところについても最後にお伺いしたいと思います。","respondent":"藤村子ども育成課長","answer":"例えば単独でこれに対応できる事業者というのがいなければ、共同事業体というような考え方も区の方針の中で使えないということではございませんので、様々方法を考えつつ公募に臨んでまいりたいと考えております。","id":"exchange-100"},{"speaker":"石田（秀）委員","kind":"質問","question":"私は２２５ページ高齢者のグループホームのことについて、お伺いをいたします。そういう大家がいて、なかなか前へ行かないと思っていて、そこら辺のところをどう考えていらっしゃるか教えていただけますか。","respondent":"東野福祉計画課長","answer":"ほかの地区も１軒から３軒というような状況ですので、品川地区のほうには今後ぜひ建てていきたいというような考えは持っているところです。それから今後の予定についてのすり合わせ、こういうものを高齢者の部門と一丸となって取り組んでまいりたいと考えているところです。","id":"exchange-101"},{"speaker":"石田（秀）委員","kind":"質問","question":"では家賃を少し１０万円でも２０万円でも、それから１人分の人件費が浮くのならぐらいのことがないと、なかなか前に進められないのです。この点のことを、そういうことも考えていかないと、こういうことは前にいかないのではないですかというのを、もう一度そこを聞きたかったわけです。","respondent":"菅野高齢者福祉課長、今井福祉部長","answer":"認知症高齢者グループホーム、区では家賃助成事業というのは実施しております。月額２万４,０００円の助成をすることによって、少しでも安く設定できるようにというところでカバーをしています。今まで区では用地確保などを含めて施設整備の面から充実して取り組んでまいりましたが、あるのは利用者に対する補助というのがあるところです。","id":"exchange-102"},{"speaker":"石田（秀）委員","kind":"意見","question":"それをどういう感覚で捉えていくのだ。だからこれはぜひ、品川第１地区でも品川第２地区でも必ず何軒かできると考えていますので、ぜひとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-103"},{"speaker":"せお委員","kind":"質問・要望","question":"２６７ページ子ども食堂開設・運営支援、２７３ページ就学前教育推進費についてお伺いします。私としても整理したくまず質問させていただきたいのですが、改めて子ども食堂の意義と目的を教えていただけますか尋ねました。","respondent":"飛田子育て応援課長","answer":"その活動が全国に広まりまして、世間に認識されていって、各自治体が後追いで支援していく今の形が出来上がったものです。ですので、我々としましては食の支援を含む子どもの格差を改善するということで、各課と連携して改善に努めていきたいと考えているところです。","id":"exchange-104"},{"speaker":"せお委員","kind":"質問・要望","question":"保健所などとも連携した、これから申請しようとする団体などの思いとかを知るようなことができるような仕組みの構築を要望いたします。そういった助成金とかの認定については、国や都からの要件などがあるのか尋ねました。","respondent":"飛田子育て応援課長","answer":"２０食以上提供する学校や病院などは、少数の特定の者に食品を提供するボランティア給食のため、法による届出の対象外ということは確認しております。都のほうのところですが、特にそういう決まりというのはありません。","id":"exchange-105"},{"speaker":"せお委員","kind":"質問・要望","question":"何か運営側の地域の皆さんが気になったことなどを、次につなげる仕組みというのはあるのでしょうか。そういったことの課題などをどう捉えているか、区の見解を伺います。","respondent":"飛田子育て応援課長","answer":"子ども食堂の成り立ちは先ほど説明させていただきましたけれども、その実現できるお手伝いを柔軟に支援していきたいと区としては考えております。そういうところで意見の交換とかして、理解・ご賛同いただける方にはまた支援をしていきたいと考えております。","id":"exchange-106"},{"speaker":"せお委員","kind":"質問","question":"ありがたいことに障害児の受入れを積極的に進めていただいていたので、受入れ困難になることは少ないですが、私立園ではいかがでしょうか。のびしなプロフェッショナルスクールですが、対象を区立・私立関係なく、そして介助員・支援員の方とかも含めてという形はできるのか尋ねました。","respondent":"石井保育支援課長、立木保育課長","answer":"当初、平成３０年度は２９名だったところ、今、令和５年度段階で９７名、約１００名近い方が加配の対象ということで保育園に通ってあります。そういった方々が私立保育園の中で健やかに過ごしていただけるために… のびしなプロフェッショナルスクールに関しましては、今年度から会計年度任用職員も対象とするようにいたしました。私立の職員の方も受けられる研修というのは用意しています。","id":"exchange-107"},{"speaker":"せお委員","kind":"質問・要望","question":"現場の方からお話を伺うと、それが就学後に必ずつながっているので、ぜひ充実をとお話ししていました。ともにとても大切な取組でより充実していっていただきたいのですが、でも支援が必要な保護者に対してはどのようにアプローチしますか尋ねました。","respondent":"立木保育課長","answer":"１日保育士体験はコロナで休止していたのですが、今年度再開いたしまして、今年度は１,１００人以上の方がもう既に受けていらっしゃっています。そういったところをしっかり子育てのほうにつなげていきたいと考えています。","id":"exchange-108"},{"speaker":"田中委員","kind":"質問・要望","question":"時間がありましたら、２３１ページの東京２０２５デフリンピック周知啓発についてお伺いします。区立の特別養護老人ホームと、いわゆる民間の特別養護老人ホームとの違いについて、簡潔にお聞かせほしいと求めました。","respondent":"菅野高齢者福祉課長","answer":"区立については区が建物とか土地を持っておりますので、その運営について指定管理者として運営してもらうというような仕組みになっております。民設については、それぞれの運営事業者がご自分で土地とかを購入して、そこに建てて運営していると認識しております。","id":"exchange-109"},{"speaker":"田中委員","kind":"質問・要望","question":"その状況を伺うと、目黒のほうはそれを上回る休みが取れるし、あと定年関係です。ぜひ介護現場をもっと見てほしいというのはそういうところが現実にありますので、現在の認識についてお聞かせをほしいと求めました。","respondent":"菅野高齢者福祉課長","answer":"介護報酬の中でサービスの質を工夫しながら、営業というか運営の努力をしていただくというのが基本となっております。そういった部分もしていますので、そして支援しなくてはいけないところは、介護現場のお話を聞いて支援しなくてはいけないと感じているところです。","id":"exchange-110"},{"speaker":"田中委員","kind":"質問・要望","question":"なぜそういう学生さんが敬遠するのかという原因についても、現状を理解いただいた上で対応をとってほしいと求めました。３０秒なので、それも併せてしっかり対応をとっていただくように、区長からも見てほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-111"},{"speaker":"松永委員","kind":"質問","question":"２３１ページの東京２０２５デフリンピック周知啓発について、２４７ページ、２５９ページのヤングケアラー支援事業について伺いたいと思います。初めに、２５９ページのヤングケアラー支援事業について伺いたいと思います。","respondent":"染谷子ども家庭支援センター長","answer":"今回、実施するに当たりまして、無理にご回答いただく必要はありませんというところでアンケート調査をさせていただいた結果。内容において、答えたくないものについては無理に答える必要はありませんという形でのアンケートの取り方をさせていただいているところです。","id":"exchange-112"},{"speaker":"松永委員","kind":"質問・要望","question":"例えば利用時間については何時から何時までとか、１日で何時間とか、そうしたところを教えてほしいと求めました。そしてまた、土日・祝日も可能なのか尋ねました。","respondent":"染谷子ども家庭支援センター長","answer":"中学生で５.２％、そういったところの分析を進める中で、実際にかなりケア負担がかかっているお子さんなどの分析を進めていきたいと考えております。基本の時間帯としては８時半から１８時ぐらいの間でというところで、ただ、そこは柔軟に対応するようにしたいと考えております。","id":"exchange-113"},{"speaker":"松永委員","kind":"質問","question":"先ほどお答えがなかったのですが、１日にどのくらいの時間数と、例えば午前と午後で分けることができるのかどうか。午前中に１時間、午後に２時間とか、３時間ともう存じておるのですが、その辺、分けられるかどうかだけ説明を求めました。","respondent":"染谷子ども家庭支援センター長","answer":"失礼いたしました。規定している中では、１日当たり１回ということになっておりますので、その３時間を分けて利用するということは想定してございません。","id":"exchange-114"},{"speaker":"松永委員","kind":"質問","question":"そうした課題も含めて、区としてどのような相談体制を取られているのでしょうか。そして、親への手伝いを逆に苦として思われていない方については、どのように対応されるのでしょうか、伺います。","respondent":"染谷子ども家庭支援センター長","answer":"そういった意味でもＳＮＳの活用というところで事業を開始したところですが、ＳＮＳ自体を利用できないお子さんも中にはいらっしゃるかと思います。","id":"exchange-115"},{"speaker":"松永委員","kind":"質問","question":"次に、２３１ページの東京２０２５デフリンピック周知啓発について伺います。応援競技として３競技挙げられて、区としてどのような形で周知啓発されていくのでしょうか、お知らせください。","respondent":"松山障害者支援課長","answer":"障害者支援課といたしましては、団体と共に手話体験コーナーとか、あと手話クイズを行ったところです。次年度におきましても、スポーツ推進課と連携しながら積極的にＰＲをしていきたいと考えております。","id":"exchange-116"},{"speaker":"松永委員","kind":"質問・要望","question":"昨年の７月２９日に天王洲公園のサッカー場で、デフサッカーの日本代表候補トレーニングマッチの交流会が開催されました。そうした中で、区としてこのデフリンピックに向けての意気込みを最後に伺いたいと思います。","respondent":"松山障害者支援課長","answer":"デフリンピックの応援競技ですが、そちらはスポーツ推進課が所管しておりますので、私どもは周知啓発ということで、当事者団体と手話の理解・普及啓発とともに進めていきたいと考えています。","id":"exchange-117"},{"speaker":"西本委員","kind":"確認","question":"なぜならば、誰でも通園制度ですから、誰でもいいわけですよ。先ほどそれの確認が取れなかったので、連携の仕方、誰が中心に、どういうふうにこれをまとめていくのかということを、答えるよう求めました。","respondent":"石井保育支援課長、松山障害者支援課長、藤村子ども育成課長","answer":"そこの検討会に出席された委員の中では、やはり生後６か月までは預けないほうがいいというような、様々議論がされていると承知しております。その中で… 個別支援の中ではもう既に保健センター、そのお子さんにとって必要なものを、それぞれ関係者が集まって考えたりしているのは存じております。… 児童センターの職員のご質問にお答えいたします。","id":"exchange-118"},{"speaker":"西本委員","kind":"質問・要望","question":"医療的ケア児支援法を見ると、令和６年度はこれだけやられているのですから、しっかり横串を取るようにしてほしいと求めました。就学前の子どもたち、品川区の子どもたちをどうするのだというところからしっかり考えてほしいと思うのですが、いかがか尋ねました。","respondent":"今井保育教育運営担当課長","answer":"あり方基本方針についてのご質問をいただきました。あり方基本方針の中では、区内の保育施設全般の質の向上に取り組んでまいりたいと、このように考えているところです。","id":"exchange-119"},{"speaker":"若林委員","kind":"提案","question":"もう一つ、私、会派から、助成制度の提案当初から、全国的に効果検証の仕組みが整えられていないことを指摘し続けてまいりました。社会参加や認知症の予防にしっかりと役に立つために、再度のお願いですので、今年度等の取組についてお聞かせほしいと求めました。","respondent":"川原高齢者地域支援課長","answer":"現在区内でご活躍いただいている認知症の地域支援推進員が８名いらっしゃるのですが、医療職、検討会議を実施していきたいと考えています。すぐに効果が実感できないということの意識づけを行うために、来年度も４０回、講話と相談会を実施する予定です。","id":"exchange-120"},{"speaker":"若林委員","kind":"質問","question":"ＭＣＩですか、毎年なのか半年に１回なのか、また考えられていることがあれば教えてください。２,８９７万円という予算が８００名でついておりますけれども、８００名、予算を超えた場合はどういう扱いになるのか説明を求めました。","respondent":"川原高齢者地域支援課長","answer":"どのような実施方法が一番よろしいかというのは、今後検討して、しっかりと前向きに考えていきたいと考えています。そして、２点目、８００人を対象にした予算を超えた場合にはどのような対応をするかというご質問です。","id":"exchange-121"},{"speaker":"えのした委員","kind":"提案","question":"東京２０２５デフリンピック周知啓発、こちらは先ほど松永委員からもご質問がございましたが、違った視点からお伺いいたします。令和５年度予算特別委員会でも要望等、提案をさせていただきましたが、まずはヤングケアラー支援としてコーディネーターが配置されましたとの意見を述べました。","respondent":"染谷子ども家庭支援センター長","answer":"メッセージのやり取りをさせていただいている方が継続的に３０人ぐらいいらっしゃるのですが、そういった結構幅広い構成となっております。はご自身の進路に関するご相談、ご両親が介護をされている方、そういった方からのご相談などを今受け付けさせていただいているところです。","id":"exchange-122"},{"speaker":"えのした委員","kind":"確認","question":"幅広い年代と、相談内容も確認が取れました。こちらはピアサポートだと思いますが、内容や参加者人数、今後の方向性をお知らせください。","respondent":"染谷子ども家庭支援センター長","answer":"大崎ブックカフェを会場として、２月の１２日に１回目の対面での開催をさせていただいておりまして、３月２０日に２回目の開催の予定をしております。今後もより多くの方に参加いただいて、接点を持てるように進めていければと考えております。","id":"exchange-123"},{"speaker":"えのした委員","kind":"質問・要望","question":"本当にコーディネーターの方も一緒ということで、支援のつながり先が重要だと考えますので、引き続き実施の拡充を要望いたします。先ほどもヤングケアラー調査を実施されたということで、調査方法や内容、先ほど答弁がなかった範囲でお知らせいただけますか尋ねました。","respondent":"染谷子ども家庭支援センター長","answer":"実態調査につきましては、先ほど実施方法についてはお話をさせていただいたとおり、オンラインでの実施としています。求められる支援内容が違ってくるというところが今確認できているところですので、支援策に活用できるように生かしていきたいと考えております。","id":"exchange-124"},{"speaker":"えのした委員","kind":"意見","question":"今、一般社団法人彩の国子ども・若者支援ネットワーク理事の土屋匠宇三さんによる「ヤングケアラーの実態とその支援」を広聴してまいりました。子どもたちの負担として先ほど訪問支援をされるというお話でしたが、学習の支援も課題と考えますが、今後の方向性をお知らせくださいとの意見を述べました。","respondent":"染谷子ども家庭支援センター長","answer":"委員がおっしゃられた学習支援ですとか、ご家庭への配食支援、そういったものを来年の予算の中で実施できればと考えているところです。","id":"exchange-125"},{"speaker":"えのした委員","kind":"質問・要望","question":"令和５年の予算特別委員会で要望させていただいた、３月４日にこちらが出ていますが、見出しが「ヤングケアラーが貸与タブレットで相談可能に。ＬＩＮＥの相談者が２５歳以上もいらっしゃるということでしたが、相談者の中にどのくらい１８歳以上のケアラーが存在しているのか尋ねました。","respondent":"染谷子ども家庭支援センター長","answer":"タブレットの関係につきまして、今後も取組を進める中で、積極的にいろいろな取組をＰＲしていければと考えております。１８歳以上のケアラーにつきましては、現在は、実際にコーディネーターが対応させていただいている方につきましては。","id":"exchange-126"},{"speaker":"えのした委員","kind":"質問・要望","question":"ケアラーへの理解の促進、または支援の推進を強く要望します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-127"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"予算編成過程が区のホームページに出ていて、随分前から要望させていただいて、令和２年から公表されて５年になっています。ここは款が違いますので要望にとどめて、要求が２８億５,０００万円余、ところが予算は２０億６,７００万円と。","respondent":"東野福祉計画課長","answer":"公表されております予算編成過程一覧におきまして、委員からお話があったように７億８,０００万円の差が出ているところです。今後も引き続き高齢者施設の整備に向け、用地取得に努めてまいりたいと考えています。","id":"exchange-128"},{"speaker":"高橋（し）委員","kind":"質問","question":"去年、八潮児童センターで、ボランティアへの謝礼として保管してあった２万２,１００円のうち９,９００円が紛失したという事故ありました。最初にお聞きしますが、年度末も近いので、この９,９００円の穴埋めはどのような財政の処理をするのかお伺いします。","respondent":"藤村子ども育成課長","answer":"八潮児童センターの現金紛失の件です。９,９００円が公金紛失だというところは以前、今後どういった形で対応を取っていくかというのは検討してまいりたいと思っているところです。","id":"exchange-129"},{"speaker":"高橋（し）委員","kind":"質問","question":"全体の総務費が３,０９１万円、これはボランティアも入るのでしょうか、１,０００万円であります。単価のお話と、それから、有償ボランティアという方々への児童センターとしての評価はどのようなものか尋ねました。","respondent":"藤村子ども育成課長","answer":"今、すまいるスクールのボランティアが既に１,５００円なのですけれども、そちらに合わせていく形で執行していきたいと考えているところです。","id":"exchange-130"},{"speaker":"高橋（し）委員","kind":"質問","question":"今お話ししたように雇用関係や、それから、さらに保険についてなど、どのような形になっているのでしょうか。結局２５館共通のマニュアルがあって、雇用するというと大げさになるのでしょうか、そちらも伺います。","respondent":"藤村子ども育成課長","answer":"お支払いの段階、事業の実施の段階で、課長が判断する形になっていると解釈しております。保険については、現在手元に資料がございませんのでお答えしかねますが、物によっては館ごとの取り決めという形でやっているところになっております。","id":"exchange-131"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"事務事業評価でもＣということで、これから増やすという方向で評価されていますので、ぜひ今回の事件を機に、ボランティア一体の管理システムについて、本庁のほうで考えていってほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-132"},{"speaker":"松本委員","kind":"質問","question":"２４７ページ、２６１ページ、一時保護所運営費について伺います。今回、所得制限をなくすという方向になったところの趣旨、理由についてお願いいたします。","respondent":"川原高齢者地域支援課長","answer":"高齢者を対象とした補聴器購入助成のまず趣旨についてのご説明です。こちらは、課税要件を撤廃することによって、先ほど申し上げた目的を全ての高齢者の方に享受していただきたいという思いがあります。","id":"exchange-133"},{"speaker":"松本委員","kind":"意見","question":"こちらの制度趣旨、そして今回、予算案では所得制限をこちらもなくすということになっているかと思います。こちらの趣旨と、所得制限をなくす理由もお願いいたしますとの意見を述べました。","respondent":"松山障害者支援課長","answer":"補聴器購入費用を助成するもので、もって難聴のあるお子さんの健全発達を支援するというのが一番の目的です。所得制限の考え方ですけれども、こちらは子育て支援の観点からということで、次年度から難聴児の発達支援事業の所得制限を撤廃するものです。","id":"exchange-134"},{"speaker":"松本委員","kind":"質問","question":"これからは１８歳未満の方たち、６５歳以上の方たちについては所得制限がなく、助成を受けられるということかと思います。一方で、１８歳以上で６４歳までの方たちについては、現状、何か補聴器の助成制度があるのか、お伺いいたします。","respondent":"松山障害者支援課長","answer":"１８歳から６４歳までの手帳のない中等度の方への今のところご支援はございません。","id":"exchange-135"},{"speaker":"松本委員","kind":"質問","question":"そこなのです。そうすると、例えば生活保護を受給されている方であっても、あるいは、学生の方であっても、これはやはり全くないと伺ってよろしいか尋ねました。","respondent":"豊嶋生活福祉課長","answer":"治療材料費ということで支給することが可能です。","id":"exchange-136"},{"speaker":"松本委員","kind":"意見","question":"１８歳から６４歳までの方というのは、たとえ所得がかなり苦しい状況であっても補聴器の助成を受けられないということかと思います。これ、公平性の観点からはどう考えたらいいのかということを思うのですけれども、その点についてご見解があればお願いいたしますとの意見を述べました。","respondent":"松山障害者支援課長","answer":"障害者支援課では、１８歳から６４歳で難聴の方につきましては、手帳の取得により支給することができます。１８歳から６４歳までの手帳のない難聴のある方に対しては、支援につきましては全国的にまだ少なく、研究してまいります。","id":"exchange-137"},{"speaker":"松本委員","kind":"質問・要望","question":"生活保護は先ほど確認できましたけれども、ただ、先ほども効果のところで社会的な生活というお話があったかと思います。これは、やっている区も少ないけれどもあると思うので、こちらについて最後ご見解をほしいと求めました。","respondent":"松山障害者支援課長","answer":"本当に限られた予算の中で公費をどういうふうに分配して、区として公平性・中立性の観点を保つかということは、非常に難しいところです。今後、１８歳から６４歳までの方をどう考えるかということにつきましては、研究課題とします。","id":"exchange-138"},{"speaker":"松本委員","kind":"意見","question":"もう１問ほかのところ考えていましたが、時間がなくなってしまいました。いずれにせよ、自分は支援を受けられないのだということがスティグマになってしまいかねませんので、ここはぜひともどうかとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-139"},{"speaker":"藤原委員","kind":"質問","question":"今日は民生費です。それと、子育て・高齢者のバランス、この辺を含めて教えていただけますか。","respondent":"新井副区長","answer":"子育て支援に関しては、あるいは無償化を進めることによって、不安や不満といった「不」をなくしていくというところを進めてきたところです。そういう意味においては、それぞれ必要なものに対して必要な予算をつけたという形になっていると思っているところです。","id":"exchange-140"},{"speaker":"藤原委員","kind":"確認","question":"まず品川区の人口構成を伺いたいと思うのですが、５歳刻みのグラフを見ると、きれいなピラミッドを描いていて。この辺については、確認ですが、いかがか尋ねました。","respondent":"佐藤企画課長","answer":"数字をお伝えしますと、国の人口構成ですと、年少人口が１１％、生産年齢人口が約６０％、老年人口が約２９％。品川区の場合は、老年人口は逆に１０％低く約２０％で、委員ご紹介のとおり２５歳から大体６４歳ぐらいまでの生産年齢人口が非常に多いです。","id":"exchange-141"},{"speaker":"藤原委員","kind":"質問","question":"それを基本にお伺いします。区長、ぜひそのときの感想を伺いたいのですけれども、よろしいか尋ねました。","respondent":"森澤区長","answer":"表彰状を渡すときに少し涙ながらにお渡しするというような形になりましたが、本当に事業者が日々頑張ってくださっていて、それが利用者の力になっているということを実感した次第です。","id":"exchange-142"},{"speaker":"藤原委員","kind":"質問・要望","question":"どういうことですか、国は。来年は何色かと楽しみにしておりますので、続けていただきたいことを含め、訪問介護について少し答弁していただけますか。","respondent":"菅野高齢者福祉課長","answer":"介護事業経営実態調査の中で訪問介護の収支差率が７.７％の数字ということで、このような報酬改定をしたというふうには聞いております。少しでも働きやすい環境を事業者が整えていただいて、加算を含めて、少しでも賃金が上がればいいかなと思っているところです。","id":"exchange-143"},{"speaker":"藤原委員","kind":"質問・要望","question":"ここに関しては、役所といいますか、行政でバックアップしていっていただきたいのです。その辺について答弁をお願いします。","respondent":"菅野高齢者福祉課長","answer":"そういうことをうたっているのですが、実際に私も書類を見すると、なかなか難しいところがあります。今、それを１回きりではなくて、少しでも多くの事業者が分かりやすく書類等を整えられるように努めていきたいと思います。","id":"exchange-144"},{"speaker":"藤原委員","kind":"質問・要望","question":"たしか決算で伺ったときに、続けていただきたいし、大きくしていただきたいという思いがあるのです。も、あのコーナーは残していっていただきたいと思うのですけれども、その辺についてをお伺いします。","respondent":"川原高齢者地域支援課長、菅野高齢者福祉課長","answer":"高齢者の住宅あっせんの今年度の実績と、また予算の見込みに対するご質問です。住宅の助成というのは実施する必要があるということを見込みまして、来年度に関しては現在の予算額の約３倍を予定して、助成も実施をして。 レイアウト変更もしまして、少し奥まった形でつい立てを作らせていただいて、相談しやすいような雰囲気を工夫させてもらっております。本当に限られた場所での工夫なのですけれども、そのような感想を聞けて、私もうれしく思います。","id":"exchange-145"},{"speaker":"藤原委員","kind":"質問","question":"バランスを取って、子育てで１つだけお伺いしたいと思うのですけれども、２６９ページ、一本橋保育園改築ですけれども、きれいにできましたね。うちから３０秒ぐらいのところなのですが、ピンクの外壁というのか尋ねました。","respondent":"今井保育教育運営担当課長","answer":"令和４年度、５年度ということで２か年かけまして改築工事を実施し、新園舎を整備したところです。令和６年度４月当初からは民営化ということで、高い質の保育が提供されるよう、引継ぎの保育を実施しています。","id":"exchange-146"},{"speaker":"藤原委員","kind":"質問","question":"２８２ページの生活保護費を最後、伺いたいのですけれども、生活福祉という意味で、いつも対面で大変ですよね。毎回激しいところでやられていると思うのですけれども、その辺について、もう本当の気持ちを今日お伺いさせていただけますか。","respondent":"豊嶋生活福祉課長","answer":"大変なミッションを任せていただいてありがたいと考えていますが、なかなかやはり……。でも頑張ります。","id":"exchange-147"},{"speaker":"藤原委員","kind":"質問","question":"やはり人間ですから、「少しきついのだけど」と言えるような役所のシステムにしていかないといけないと、私は思っています。どうもすみません。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-148"},{"speaker":"鈴木委員","kind":"質問・要望","question":"この改定に対してということで要望書を出しているのですけれども、これに対しては、まず初めにお願いしておきたいと思います。予算でも６４９万円ですから、ぜひこれも所得制限撤廃をしていただきたいと思うのですが、いかがか尋ねました。","respondent":"菅野高齢者福祉課長","answer":"お尋ねの入院時の紙おむつ代の助成についてです。さらに紙おむつ代の負担が加わることから、低所得者の方の経済的負担軽減対策として実施しているというところが理由となっております。","id":"exchange-149"},{"speaker":"鈴木委員","kind":"質問・要望","question":"大体ひとり暮らしですと１５５万円、６万円の方はもう課税になってしまうわけですから、ぜひとも所得制限の撤廃を強く要望しておきたいと思います。そういうところも含めて、現場の実態をぜひ聞いていただけないかなと思うのですが、いかがか尋ねました。","respondent":"菅野高齢者福祉課長","answer":"少しでもどんな支援ができるかというところで今回考えさせていただいたのが、居住支援手当とか、今までもほかの支援等もしています。そういった都のやっている事業の動向も見ながら、区としてできることをまた研究していきたいと思います。","id":"exchange-150"},{"speaker":"鈴木委員","kind":"質問・要望","question":"それで、障害者福祉も、グループホームでも４００社に公募をかけても１社しか応募がないと、そんな状況ではないですか。改めてこれは検討してほしいと求めましたが、いかがか尋ねました。","respondent":"菅野高齢者福祉課長","answer":"品川区における地域包括支援センターは、在宅介護支援センターにより構成して、きめ細やかな支援体制を継続して行っております。第９期介護保険事業計画においても、この在宅介護支援システムを採用した仕組みづくりは、継続して行ってまいりたいと思っているところです。","id":"exchange-151"},{"speaker":"大倉委員","kind":"質問","question":"２４５ページ、福祉人材確保・定着事業と品川介護福祉専門学校、あと、２７３ページの保幼小ジョイント事業、保幼小の連携というところで伺います。実際そこへの解消の視点ではどういうふうに行われてきたのか、どうなっているのか、またほかに異なる視点があったら教えてほしいと求めました。","respondent":"立木保育課長、菅野高齢者福祉課長","answer":"保幼小のジョイント事業、今、名称がそうなっておりますが、開始当初は保幼小交流事業ということで、平成１９年からスタートしております。やはり小一プロブレムと言われている、非常に有効なものだと考えておりますので… このことから、区では介護職員確保支援のため、紹介料補助として１人当たり５０万円を上限に助成するものとなっております。予算の内訳としましては、５０万円掛けるまずは１０人分というところで、計５００万円の予算を計上しています。","id":"exchange-152"},{"speaker":"大倉委員","kind":"質問・要望","question":"コロナのところは３年間休止をされていたということで、少し伺おうかなと思っていたのですが、その３年間の部分について少し教えてください。さらにこういった支援をしながら人材確保に努めていってほしいと求めましたが、改めてこれからの定員の確保に向けた取組を説明を求めました。","respondent":"立木保育課長、菅野高齢者福祉課長","answer":"小学校・義務教育学校の前期課程全校で一応実施という形を取っていただいておりますで、区立幼稚園９園、全部です。実際に交流ができないとしても連携自体は取っている中で、そういった部分では… 地域で活躍する福祉人材の養成に努めてまいりました。少しでも多くの生徒が取り込めるように、インスタグラムなども活用しながら、様々な方法で努めていきたいと思います。","id":"exchange-153"},{"speaker":"大倉委員","kind":"確認","question":"保育園側としてどういうふうにしていきたいというのは、子どもたちの成長を促していきたいということでいいかどうか、確認をさせてください。先ほど伺うのを忘れたのですが、しっかりと継続をしているかどうか、しなかった場合はどうなるのかというところを教えてほしいと求めました。","respondent":"立木保育課長、菅野高齢者福祉課長","answer":"今後も小学校・義務教育学校と連携をしっかり取りながら、事業としては進めてまいりたいと思います。年度当初の校長連絡会等でも保育課からお邪魔しまして、今後もしっかり連携を取りながら… こちらの補助金の事業の継続性等についてですけれども、皆様から集めた保険料とか、国でも問題視しているところがあります。今後の様子等を見ながら、また法人や事業者と意見交換をしながら、継続性については考えていきたいと思います。","id":"exchange-154"},{"speaker":"大倉委員","kind":"確認","question":"しっかりと連携を取りながら、受け入れてもらいながら進めていきたいということが確認できましたので、ありがとうあります。福祉人材確保のところでは、継続性をしっかり確認をしながら進めていってほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-155"},{"speaker":"あくつ委員","kind":"質問・要望","question":"昨年の決算特別委員会で多胎児の子どもの命、ご家庭を守る観点から、保育園入園選考時の調整指数について加点を求めました。一番気になるところですが、申請をされた多胎児の皆さんが無事に入園できたのかどうか、お知らせください。","respondent":"立木保育課長","answer":"その内訳、例えば双子の方、三つ子の方、兄弟児の方というのは統計的に今取っておりませんので、お答えすることができません。二次に関しましては、２４人の申請中１０人が内定で１４人が不承諾という形になってあります。","id":"exchange-156"},{"speaker":"あくつ委員","kind":"質問・要望","question":"もう１点要望しておったのですが、これは８０ページ近くになって、知りたい情報が検索できないと。これもたしかすぐにやっていただいたと思うのですけれども、これはいつから文字検索ができるようになったのか説明を求めました。","respondent":"立木保育課長","answer":"こちらもご要望をいただいた中で、実際、画像から、一から文字起こしをいたしまして改めて作り直したことで少し時間がかかってしまいまして、ご案内を掲載してから、１月にはもう検索できるような形にしています。","id":"exchange-157"},{"speaker":"あくつ委員","kind":"質問・要望","question":"先週は、９０代の女性で大家から立ち退きを言われているという結構むちゃな話も、ご相談に伺いました。入居促進事業の窓口である高齢者地域支援課ではどのように認識をされているか、伺います。","respondent":"川原高齢者地域支援課長","answer":"こういった住宅課と連携した助成事業が拡大するに伴って、それに伴って、かなりやはり限られているような状況というのは認識しています。私どもの課では現在、高齢者のみへの助成という形にはなりますが、関係課と協力して理解の促進というところを深めていきたいと考えています。","id":"exchange-158"},{"speaker":"あくつ委員","kind":"質問・要望","question":"不動産事業者にも伺ったのですが、レインズというパソコンをたたきますよね、みんな不動産屋に行くと。これはどうですかと聞こうと思ったのですが、これは一応総括でもうちの会派でやりますので、今日はこれでおしまいにいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-159"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"２０２５のデフリンピックの周知啓発というのは会派としても要望をさせていただいている中で、本区では競技はございませんけれども。先日、２月に八潮の明晴学園であった手話＆デフリンピックフェスタ、私もお伺いをしてきました。","respondent":"松山障害者支援課長","answer":"デフリンピックの周知啓発に関する、前年度から４万円ほど減になっているものでしょうか。これは啓発グッズの内容の違いによるものです。","id":"exchange-160"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"すみません。その内容というのは、どういうものからどういうふうに変わったか、種類というのですか、教えてほしいと求めました。","respondent":"松山障害者支援課長","answer":"今年度はボールペンを作ったのですけれども、それで、いろいろデフリンピックのイベントで配らせていただいたのですけれども、来年度は少しまだ精査はしているのですけれども、ほとんど、４万円程度なので、同じぐらいのものを考えているところです。","id":"exchange-161"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"同程度のものということで認識をしておきますので、よろしくお願いします。来年度は５３万円余なのですけれども、この理由もどうなのか、教えてほしいと求めました。","respondent":"松山障害者支援課長","answer":"内容ですけれども、今年度も実施していました区職員向けとか区民向け、子ども向け、事業者向けの手話講座があります。そのために、こちらは６０万円余の減という形になっております。","id":"exchange-162"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"この認知度向上を含めて、款は違うのですけれども、来年度１１月ですか、今年の１１月ですよね。周知啓発の１年前記念イベントがあると思うのですけれども、現時点でどういうふうにやっていこうかという何かあれば、教えてほしいと求めました。","respondent":"松山障害者支援課長","answer":"ちょうど１１月に開催されるので、９月ぐらいに、例年ですと福祉まつりを行っております。実行委員会に働きかけを区から行いまして、多くの区民に知っていただくことになろうかと考えております。","id":"exchange-163"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"それと、２３７ページ、心身障害者福祉会館運営費についてお尋ねをします。いろいろな利用者がいるので相当数だと思いますけれども、区はこれをどのように把握して対応しているのか、教えてほしいと求めました。","respondent":"松山障害者支援課長","answer":"心身障害者福祉会館指定管理者に寄せられた声の把握と対応についてです。定期的に毎月１回、心身障害者福祉会館の指定管理者と、障害者支援課と打合せを行っております。","id":"exchange-164"},{"speaker":"高橋（伸）委員","kind":"質問","question":"そこで、作業療法士が講師となってサポーター養成講座があって、２４人が受講されたということであります。これに関してまた３月４日ですか、私のこの認識でよろしいのかどうか、失語症があるというのも含めてお聞きしたいと思います。","respondent":"松山障害者支援課長","answer":"高次脳機能障害のうちの障害で現れる症状の一つとして、失語症は委員のご認識どおり、あります。","id":"exchange-165"},{"speaker":"高橋（伸）委員","kind":"確認","question":"それと、ホームページも確認したのですけれども、ぜひこれも周知徹底をよろしくお願いいたします。ありがとうございました。","respondent":"松山障害者支援課長","answer":"失語症に対する講習会についても、ホームページで掲載をしています。","id":"exchange-166"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/664001?Template=document&Id=6691#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=3&TermStart=2024-01-01&TermEnd=2024-12-31"}],"sourceMeta":{"pages":0,"characters":131239,"voices":388}},{"id":"r06-20240311-3","meetingId":"r06-c-budget","date":"2024年3月11日","dateIso":"2024-03-11","committee":"予算特別委員会","time":"午前１０時００分～午後 ５時５０分","status":"正式会議録","sourceType":"formal","overview":"予算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を165件整理しています。","topics":[{"id":"topic-01","title":"予算特別委員会","agenda":"予算特別委員会","exchanges":[{"speaker":"こしば委員","kind":"質問・要望","question":"私からは、３２１ページ、商店街活性化事業についてお伺いいたします。自民党も要望してきました、またプレミアム率３０％の区内共通商品券の発行など、多くの施策を品川区は展開されてきました。","respondent":"小林商業・ものづくり課長","answer":"品川区の動向ですけれども、令和５年度の現時点におきまして、９７というのが品川区の商店街の数になっております。課題ということで、後継者、そういったものの活動というのが難しくなってきているということが要因にあるのではないかと考えているところです。","id":"exchange-001"},{"speaker":"こしば委員","kind":"提案","question":"これまで、私も何度か商店街の振興支援について質問や提案をさせていただいたことがありました。そこで、商店街が解散した場合の影響、また、その課題について教えてほしいと求めました。","respondent":"小林商業・ものづくり課長","answer":"商店街の管理している街路灯についても、やはり一定の処分といいますか、一定の対応をする必要が出てきます。商店街はやはり地域のコミュニティで、街路灯についてもふだんから支援していますし、ふだんの活動についても支援を進めているところです。","id":"exchange-002"},{"speaker":"こしば委員","kind":"質問","question":"この商店街の街路灯、装飾灯ともいいますが、そこの補助金についてお伺いしたいと思います。この額が１本当たりの算定額となるのか、２倍にした額に２０％を上乗せした額なのか、その辺りを教えてほしいと求めました。","respondent":"小林商業・ものづくり課長","answer":"ご指摘がございました装飾灯につきましては、もともと１本５,６００円というのが基準になってあります。そこから２０％アップということで、区の予算の方針でいけば、合わせて前年度と変わらない水準でご支援をしていくというような予算計上にしています。","id":"exchange-003"},{"speaker":"こしば委員","kind":"提案","question":"続きまして、商店街を支える人の取組についてお伺いします。これまで一般質問などでサポーター制度の拡充を提案してきましたので、来年新たに創設されます業務サポーター制度というものを高く評価いたしますとの意見を述べました。","respondent":"小林商業・ものづくり課長","answer":"地域の課題、いろいろ情報提供あるいは課題をお聞きする、その相談に対応するということの取組です。会員の方には、そのような支えを区としてしていくことによって、活力の維持や活動の継続というものを支援していく取組です。","id":"exchange-004"},{"speaker":"こしば委員","kind":"質問","question":"地域を巻き込むサポーター制度の運用をぜひお願いしたいと思います。そうすることによって、商店街の地域性に寄り添った支援のますますのさらなる拡充をお願いしまして、私からの質問は終わらせていただきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-005"},{"speaker":"ゆきた委員","kind":"提案","question":"先日の一般質問にて、オンライン化で被災者の生活再建支援を充実させていくことを求めたところ、システムの導入や。そこで、火災ごみの減額免除の公的支援を受けるための申請についてはオンライン化を提案しますが、区のご所見を伺いたいと思いますとの意見を述べました。","respondent":"品川品川区清掃事務所長","answer":"現在、火災の費用につきましては、罹災証明をお持ちいただいて、９割減免するという形を取っております。昨今、いろいろな申請システムの電子化等の流れもありますので、こちらについては電子で申請ができるような形で検討していきたいと考えています。","id":"exchange-006"},{"speaker":"ゆきた委員","kind":"質問・要望","question":"こちらは要望で終わりたいと思います。改めて区ではどういった対策をしてこられたのか、また来年度の予算でどういった対策を取られていくのか、お聞きしたいと思います。","respondent":"舩木生活衛生課長","answer":"あるいは、ご自身での対応が難しい場合は、害獣対策に関する専門事業者の集まりである東京都ペストコントロール協会を紹介しております。現在行っている支援に加えまして、駆除方法のアドバイスに対応するほか、効果的な支援を行ってまいります。","id":"exchange-007"},{"speaker":"ゆきた委員","kind":"確認","question":"年間を通して２０１件以上の状況、ネズミ専門業者の個別での派遣調査も新しく行うことを確認いたしました。次年度は新しい取組を始められますが、改めて、その後の施策の方向性・展開についてお聞きできればと思います。","respondent":"舩木生活衛生課長","answer":"ネズミが大量に繁殖したり、あるいは建物に侵入できないようにするなど、区民の暮らしを守るための環境的防除対策が効果的であると考えております。","id":"exchange-008"},{"speaker":"ゆきた委員","kind":"質問","question":"被害の調査、発生の状況調査など、より一層進めてほしいと求めました。ネズミの被害と苦情の声が寄せられていますが、こちらの対策について、最後にお聞きできればと思います。","respondent":"舩木生活衛生課長","answer":"住宅所管課において、解体工事計画の事前周知に関する指導要綱に基づく個別説明の中で指導を行っていると聞いております。ネズミをはじめとする害獣の生息が確認できた場合の駆除の方法などについては、必要に応じて保健所も協力しながら対応してまいります。","id":"exchange-009"},{"speaker":"山本委員","kind":"提案","question":"昨年の決算特別委員会や一般質問でもご提案させていただきました。昨年の一般質問では「しながわペイ」と呼び、それが重要なポイントであることを説明し、導入の提案を致しましたとの意見を述べました。","respondent":"横田情報推進課長","answer":"仮称「Tokyo Tokyo Point」ですが、現在、都が事業スキームを検討中でございまして、具体的な話は下りてきてございません。","id":"exchange-010"},{"speaker":"山本委員","kind":"提案","question":"様々な実績データの還元がしっかり受けられるような共通プラットフォームとなるよう、区から都への要望をお願いいたします。いろいろとご要望いたしましたが、区のご見解を伺いますとの意見を述べました。","respondent":"横田情報推進課長","answer":"区といたしましては、これまでも都のスケールメリットを活かしたデジタル地域通貨の実現について要望してきたところです。区が実施予定のデジタル商品券の状況や他区の動向などを踏まえまして、デジタル地域通貨について検討を進めてまいります。","id":"exchange-011"},{"speaker":"山本委員","kind":"質問","question":"続いて、健康ポイント事業について伺います。昨年の決算特別委員会でも質問し、一般質問でも触れた事業で、その要因とアンケートの状況についてお教えください。","respondent":"若生健康課長","answer":"これまで数年間、前のアプリで継続して参加していただいていたので、前年度については約６,３００人の登録があったところではあります。それから、今年度のアンケート結果については現在集計中ですので、また機会がありましたらお答えしたいと思います。","id":"exchange-012"},{"speaker":"山本委員","kind":"質問・要望","question":"頑張ったりした人が報われるような仕組みにしてほしいという声や、期待する景品は１位が商品券で半数以上だったと記憶しています。とうきょう健康ステーションのウェブサイトから、がん検診の受診率について確認いたしました。","respondent":"若生健康課長","answer":"がん検診につきましては、国の対策型検診として指定されている５つのがんについて、区としても受診率向上に取り組んでいるところです。受診率があまり伸びていない、ほかのがんの対策については今後、検討していきたいと考えています。","id":"exchange-013"},{"speaker":"山本委員","kind":"質問","question":"効果が高まるのではないかと思っています。続きは総括質疑ですることといたしまして、本日の私の質問は終わらせていただきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-014"},{"speaker":"安藤委員","kind":"質問","question":"伺いますけれども、４月からの組織改正で部署の名前を変える理由というのを伺います。伺います。","respondent":"小林商業・ものづくり課長","answer":"課名をどうして変更するかですが、これは１つ、産業構造がやはり品川区の中で少しずつ変わってきているということを捉えたものです。こういった変化も捉えまして、創業・スタートアップ支援担当課長の設置も含めて、地域産業振興課ということで課名変更を行うものです。","id":"exchange-015"},{"speaker":"安藤委員","kind":"質問・要望","question":"産業のまちネットワーク推進協議会は平成９年度からということで、それぞれの産業政策等に関しての交流等を通じ、各自治体の課題解決を促すと。これらのものづくり産業の支援事業には、ぜひ引き続き力を入れていただきたいのですが、いかがか尋ねました。","respondent":"小林商業・ものづくり課長","answer":"従来の区分に加えまして、デジタルといいますか、新しい情報通信業と組み合わさるような形での製造業の在り方というのもあり得ると考えています。それ以外に今後新たな取組を含めて、製造業、ものづくりを引き続き支援してまいりたいと考えております。","id":"exchange-016"},{"speaker":"安藤委員","kind":"質問・要望","question":"いかに被災者の心の救いになるか、もちろん衛生上もそうですけれども求められているかというのを、そのときにすごく実感したのです。伺いますけれども、災害時における入浴の重要性や、銭湯に期待する役割などについて、保健衛生部門としてのお考えを伺いたいと思います。","respondent":"若生健康課長","answer":"公衆浴場自体には行っておりますし、そういうところで、公衆衛生の観点から支援は進めているところです。災害時についても、そういったところで何ができるかというところは、災害部門とも連携して考えていかなければいけないと考えています。","id":"exchange-017"},{"speaker":"安藤委員","kind":"質問","question":"政策的経費として耐震化促進事業３７０万円が計上されておりまして、公衆浴場の耐震化を促進し、利用者の安心安全を確保するとありました。応急的修繕１００万円が２件、計画的修繕１７０万円が１件とありましたが、それぞれ、どのような修繕や工事に対する予算なのか伺います。","respondent":"若生健康課長","answer":"公衆浴場の耐震化促進の支援です。これはもう躯体などの補強等をしたり、天井を張り替えたりというような、大規模なところをという内容になってあります。","id":"exchange-018"},{"speaker":"安藤委員","kind":"質問・要望","question":"代表質問でも取り上げたのですけれども、現状はどうなのかということなのですが、銭湯は対象外なのです。衛生上も重要な銭湯も入れるべきだと思うのですけれども、ぜひ働きかけていただきたいのですけれども、いかがか尋ねました。","respondent":"若生健康課長","answer":"上下水道の耐震化につきましては、私どもの所管でなかなか把握し切れていないところですが、銭湯、公衆浴場の公衆衛生の観点からです。区の所管とも連携してやる必要もあるかと認識していますし、今後、意見交換等もしていきたいと思います。","id":"exchange-019"},{"speaker":"筒井委員","kind":"提案","question":"都民ファーストの会が最重点政策として提案・要望させていただいて、東京都の令和６年度予算に入れさせていただいたものですけれども。まだ詳細不明なところが多いかと思いますが、区の見解として、いかがお考えか尋ねました。","respondent":"横田情報推進課長","answer":"先ほどの山本委員への答弁と同じ回答になってしまうのですが、現在、都が事業スキームを検討中ということでございまして。引き続き、区が実施予定のデジタル商品券をどうしていくか、検討を進めてまいりたいと考えております。","id":"exchange-020"},{"speaker":"筒井委員","kind":"質問・要望","question":"行政評価シートの３４１ページを見ますと、品川健康センターですけれども、区民の健康の保持・増進を図るというのが目的になっております。あくまで品川区民の健康の保持・増進を図るという目的達成のためですから、当然、品川区民と区外の方の区別というのはついているのか尋ねました。","respondent":"若生健康課長","answer":"区民と区外、区外の方も参加できるようになっておりますので、これを合わせた形になってあります。内訳については、これは区で今把握していないのですが、およそ９割が区民というところで、アンケート結果から把握しています。","id":"exchange-021"},{"speaker":"筒井委員","kind":"確認","question":"９割、昨年の決算特別委員会でも質問させていただきましたけれども、新規では登録団体で確認して区別をつけられる。やはり段階的に、区民料金と区民外の料金というのを区別していったほうがいいと思いますけれども、いかがお考えか尋ねました。","respondent":"若生健康課長","answer":"で、やはり区民の方のご利用というのをより進めていくといいますか、区民サービスを充実させていくというところは必要だと認識しています。今後これは改定も視野に入れまして、現在、内部で検討は進めているところです。","id":"exchange-022"},{"speaker":"筒井委員","kind":"質問・要望","question":"しながわ健康プランについて伺います。この座り過ぎについて、今度のしながわ健康プラン２１ではどのように反映されていくのか、お考えを説明を求めました。","respondent":"若生健康課長","answer":"厚生労働省についても、座りっ放しのところも含めた身体活動・運動ガイドを現在策定中ということを認識しております。これは健康づくりでも、そういったところも意識しながら、健康プラン２１についての策定を進めてまいりたいと考えております。","id":"exchange-023"},{"speaker":"筒井委員","kind":"質問・要望","question":"やはり区役所として範を示していただきたく、先行して、ぜひリードしていっていただきたいと考えております。やはり会議の仕方の工夫というのをしていかなくてはいけないと思いますけれども、品川区役所として具体的な取組・行動のお考えはあるのか尋ねました。","respondent":"堀越総務部長","answer":"職員の健康管理につきましては、いろいろな労働安全の法令にのっとった対応をするのと、それから、より働きやすく仕事をして能率を上げるという面の検討が必要だと思いますので、様々な角度から検討して、取り入れるものについては取り入れていきたいと考えています。","id":"exchange-024"},{"speaker":"筒井委員","kind":"意見","question":"やはり、お酒というのは、たばこの規制より大きなハレーションもあるかと思います。厚生委員会でも、改めてどのようにしながわ健康プラン２１に反映されるのか、お知らせくださいとの意見を述べました。","respondent":"若生健康課長","answer":"健康日本２１の指標等で、アルコール量の指標について、令和１４年度までに１０％にすることというのを目指しているというようなこともあります。","id":"exchange-025"},{"speaker":"筒井委員","kind":"質問・要望","question":"様々、そのとき適切に品川区の健康プランにも反映していっていただいて、かつ具体的な取組・行動に移していってほしいと求めました。ぜひ。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-026"},{"speaker":"せらく委員","kind":"質問・要望","question":"学習会への参加は１回当たり大体何組ほどでしょうか。年齢層や、複数回参加したことがある方、学習会の雰囲気を説明を求めました。","respondent":"矢木大井保健センター所長","answer":"小学校１年生から３年生が３名、中学生が３名、高校生が４名といった人数構成になってあります。地域の普及啓発と家族の対応能力の向上ということで、講師から、こういうふうに対応すればいいのだというようなアドバイスがございまして。","id":"exchange-027"},{"speaker":"せらく委員","kind":"質問","question":"詳しく学習会の雰囲気を教えてくださいまして、ありがとうあります。この学習会を知るきっかけとしては、保健センターとしてどういった案内をされているのか、説明を求めました。","respondent":"矢木大井保健センター所長","answer":"は毎年度のアンケートを年度末に実施するのですが、また参加者の方も踏まえながら、講師と相談して内容については決定しています。講師につきましては、ひきこもり等、家族相談を行っている、精神保健福祉士・社会福祉士をお持ちの先生に継続してお願いしています。","id":"exchange-028"},{"speaker":"せらく委員","kind":"質問","question":"私がお話を伺った中でも、引き続き参加されているという方がいらっしゃって、交流を経て前向きな変化があったのだと思います。８０５０という問題もありますが、親や兄弟から家族支援として相談された際には、行政機関とはどのようにつなげていらっしゃいますか尋ねました。","respondent":"矢木大井保健センター所長","answer":"１つの事例ですが、そういったお子様のご相談におばあ様がいらしたというような事例においては、やはり学校や医療機関といった関係機関と連携してつなげてまいってあります。","id":"exchange-029"},{"speaker":"せらく委員","kind":"質問","question":"個別計画については、精神障害者保健福祉手帳をお持ちの方が対象と伺いまして、ひきこもりの方全てが対象ではないという理解をしています。こちら、ご所見を伺いたいと思います。","respondent":"矢木大井保健センター所長","answer":"発災時の個別避難計画といったものを作成するのをテーマの内容にしてはどうかというご質問でございまして、こちらは、今年度末で間もなくアンケート結果がまとまりますので、それらを含めまして来年度に反映できるかどうか、また所内で相談・検討してまいりたいと思います。","id":"exchange-030"},{"speaker":"せらく委員","kind":"質問・要望","question":"震災については、アンケートといったところも、能登半島地震が起きたというところも踏まえましてテーマに入れてほしいと求めました。社会課題として、ひきこもり本人と家族が孤立しないような支援、震災に向けた対策、引き続き。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-031"},{"speaker":"横山委員","kind":"質問","question":"虐待予防の観点からの母子保健の役割と重要性を区はどのようにお考えでしょうか。母子保健における指導と支援の違いについてもお伺いいたします。","respondent":"榎本荏原保健センター所長、石橋品川保健センター所長","answer":"私からは、母子保健の援助対象についてと、母子保健における指導と支援の違いについてお答えいたします。それから支援についてですが、気持ちに寄り添った対応を大切にして支援していくことと考えております。 保健師の役割ですが、保健センターの保健師は最も身近な存在として、不安などを抱えている養育者のご相談に対応しております。そして、その相談に応じて区の関係各課と連携しております。","id":"exchange-032"},{"speaker":"横山委員","kind":"提案","question":"「思い描いていたよい母親になることができない私のままでやっていくしかないと認めて、提案されている援助を拒むのをやめる。大井・品川・荏原保健センターで内容に違いはあるのか尋ねました。","respondent":"石橋品川保健センター所長","answer":"所管ではないのであまりしっかり把握はしていないので申し訳ありませんが、区の個別支援や講演会などを実施しているものと認識しております。家族への支援を実施しておりまして、参加者の方からは、少し気持ちが楽になったといったお声を頂いているところになります。","id":"exchange-033"},{"speaker":"横山委員","kind":"質問","question":"創業・スタートアップ等支援経費についてお伺いいたします。区内においてスタートアップの力が高まることで、地域社会にどのような影響を及ぼすと区はお考えか尋ねました。","respondent":"石橋品川保健センター所長、小林商業・ものづくり課長","answer":"年間の回数１０回というお話をさせていただきましたが、こちらは各保健センターにて１０回前後、実施している形になります。こちらの連絡会議に、特別区保健衛生主管課長会の代表の課長が出席しておりまして… 武蔵小山創業支援センターにおきましては、女性の起業家の支援というのを一層進める中で。五反田産業文化施設は５月１日にオープン予定です。","id":"exchange-034"},{"speaker":"横山委員","kind":"提案","question":"さらに、地域保健の力で関係機関につなぐことに加えて機能を高めていくネットワークの構築も併せてお願いいたします。スピード感を持って提案内容を検証したり、事業の妥当性を判断する道の重要性が指摘されていますので、どうぞとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-035"},{"speaker":"西村委員","kind":"質問・要望","question":"明石市のおむつ宅配がいいと私が思ったのは、コープ・生協に勤める先輩ママが、最近どうかと訪問してくれると伺ったからです。今届いている要望と併せて説明を求めました。","respondent":"石橋品川保健センター所長","answer":"０歳児の養育者の方は、支援員の話し方、感じ方は異なる部分があると思います。引き続き、見守り支援員は配慮に欠けないような言葉遣い、声かけを心がけるように、受託者を通じて指導してまいります。","id":"exchange-036"},{"speaker":"西村委員","kind":"提案","question":"一目瞭然なフローチャートがあると、双方にとってよいのではないかと思いましたので、ご提案します。既に声を聞きながら軌道修正をしていると伺っておりますとの意見を述べました。","respondent":"石橋品川保健センター所長","answer":"その辺りにつきましてはしっかりと、訪問支援員が訪問時に丁寧に利用者の方にはご説明をしていくとともに、今後の展開については検討してまいります。今後とも利用者の声に耳を傾けて、利用しやすいように、できる限りの改善・軌道修正を図ってまいりたいと考えております。","id":"exchange-037"},{"speaker":"西村委員","kind":"質問・要望","question":"大手航空会社や他区も追随しておりまして、あと品川区の会社に行けば安心だという品川ブランドにしてほしいと区内企業様よりご要望いただきました。人材の交流を目的とした協定や友好都市の締結など、人材の流出を防ぐ手だてをお願いしたいと思いますが、いかがか尋ねました。","respondent":"小林商業・ものづくり課長","answer":"就職の支援というだけではなくて、今後あり得る展開としましては、ビジネス交流なども考えられると考えております。そういう中で現地側とも信頼関係を築いて、その中でより成果が見えるような取組を進めていきたいと考えております。","id":"exchange-038"},{"speaker":"西村委員","kind":"意見","question":"出てくることも踏まえて、人材流出しない、さらなる取組をお願いしたいと思います。五反田バレーとの取組も現在、検討中かと思いますが、今後の展開について説明を求めました。","respondent":"小林商業・ものづくり課長","answer":"モンゴル高専との取組ということでいきますと、今までの中心は、やはり製造業、ものづくりの現場において人手不足をどう解消していくか。モンゴル高専にはそのような対応をする学科がございまして、そこの学生たち、そういったところも今後進めてまいりたいと考えております。","id":"exchange-039"},{"speaker":"西村委員","kind":"質問・要望","question":"この点も引き続き、ぜひとも力を入れてほしいと求めました。現状を捉えて、今後どのような施策を考えていくのか、説明を求めました。","respondent":"小林商業・ものづくり課長","answer":"今後、人が採れないという場合には、ロボット化や自動化といった、ＤＸを活用したような意味での人材対応というものも出てくるものです。こういうものは総合的に進めながら、人材の部分にも対応しながら、区内中小企業の下支えというものをやってまいりたいと考えております。","id":"exchange-040"},{"speaker":"西村委員","kind":"質問・要望","question":"会派としても要望してきました男性接種助成を開始するに当たりまして、なぜ男性に接種が必要かを正しく理解してもらう施策が必要だと考えます。お伺いいたします。","respondent":"坂野保健予防課長","answer":"一応、今の予定なのですけれども、令和６年７月１日の広報に記事を掲載しようかというのを考えているところです。大体、医療機関ベースで１０か所ぐらい、女性のほうが多い今の状況です。","id":"exchange-041"},{"speaker":"西村委員","kind":"質問・要望","question":"５年生の段階から、科学的根拠に基づいた情報も届けてほしいと要望させていただきました。キャッチアップに関しましては、先日の委員会の中でも、７月をめどにお知らせの送付ができるということで伺っておりました。","respondent":"坂野保健予防課長","answer":"若いときからの情報提供ということで、滋賀県の例をご案内いただいたところです。私からは言いにくい部分があるのですが、いろいろな方法はパラレルに使っていって、立体的な情報提供ということを考えていきたいと思います。","id":"exchange-042"},{"speaker":"西村委員","kind":"質問","question":"立体的な周知をお願いしたいというのが今回の質問の全般でお伝えしたいことでありまして、いろいろな方法が考えられると思いますので、正しい知識が区民の皆様に届きますようにお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-043"},{"speaker":"新妻委員","kind":"質問・要望","question":"昨年の第３回定例会一般質問で、また更年期症状について掲載していただきたいと、施策展開を要望いたしました。策定委員会の中で議論をしていくというご答弁でありましたので、改定のスケジュールをお伺いいたします。","respondent":"若生健康課長","answer":"１回目が夏頃以降、開催していく予定でございまして、それを受けて年度末には策定していくといった予定です。","id":"exchange-044"},{"speaker":"新妻委員","kind":"質問・要望","question":"２０２４年度から始まります健康日本２１（第三次）の中で、新たに骨粗鬆症検診の受診率向上を追加したことから、国も検診の必要性を示しております。医師会との協議がまとまり次第、補正予算を組んででも早期の実施をしてほしいと求めましたが、見解を伺います。","respondent":"若生健康課長","answer":"例えば検査の方法や実施場所、様々、意見のすり合わせや調整等に少々時間がかかっているというところはあります。一緒に進めていく必要があるというところで、早期の実現に向けて、引き続き具体的な協議を進めてまいりたいと考えています。","id":"exchange-045"},{"speaker":"新妻委員","kind":"質問・要望","question":"私もこのことを要望させていただきましたので、とても、これはいいことだとお話を頂いております。令和５年度中に説明会を行い、４月からすぐに新制度が開始されるということでありますので、また参加者からのお声をお聞かせほしいと求めました。","respondent":"舩木生活衛生課長","answer":"９日の土曜日の日に、その後、講演会も実施したところです。予算案は詳しくはご説明できませんでしたけれども、区が予定している大きな方向性といったところを説明いたしまして、あと詳細については。","id":"exchange-046"},{"speaker":"新妻委員","kind":"質問","question":"適正に地域猫がいると認識しておりますので、ボランティアの方の協力がなければ野良猫等が増えていくという現状にもなっていくかと考えています。グループですか、町会・自治会の皆様に関してはどのようにこのことをご説明いただくのか、お知らせください。","respondent":"舩木生活衛生課長","answer":"今予定しておりますのは、町会・自治会にもそういった旨を説明して、共有した上でということを１つの要件にしたいと予定しております。大体６月前後、ぜひそういった目でご支援・ご協力を頂きたいという旨を、説明というか周知してまいりたいと考えております。","id":"exchange-047","title":"町会・自治会支援"},{"speaker":"新妻委員","kind":"質問・要望","question":"なかなかやはり周知が届かないという現状もありますので、この機会を逃すことなく、さらなる周知を求めたいと思います。品川区は２０２１年に、もう一歩の周知をお願いしたいと思いますが、見解を伺います。","respondent":"坂野保健予防課長","answer":"今の予定では終わってしまう予定なので、国や東京都がいろいろなものを考えていますので、その辺も応用していきたいと思います。","id":"exchange-048"},{"speaker":"おぎの委員","kind":"質問","question":"３１５ページ、３１９ページ、時間があるところまでお聞きします。は食育推進事業ですが、来年の歳出予算見積書を見ますと、品川栄養士会への委託事業の見直しとありますが、どのような点が変更となるのか尋ねました。","respondent":"若生健康課長","answer":"栄養士会から提案がありまして、様々検討して、そういったことで考えてあります。こちらの回数を若干変更するというようなところが内容になってあります。","id":"exchange-049"},{"speaker":"おぎの委員","kind":"質問・要望","question":"受診されなかった方へのフォローはどうされているのでしょうか。８０２０・９０１６顕彰が４００人となっていますが、こちらは他の区に比べて割合としては多いのか尋ねました。","respondent":"石橋品川保健センター所長、若生健康課長","answer":"私からは、４か月健診の受診率またはフォローについてご回答いたします。未来所の、健診を受けていない方に関しましては、保健師が電話でご連絡を取って、状況の確認等を行っている形になります。 こちらは、ここ数年１０％前後ということで推移しています。８０２０の達成者顕彰につきまして、毎年、こちらに区長にも参加いただきまして顕彰式を行っているところです。","id":"exchange-050"},{"speaker":"おぎの委員","kind":"質問・要望","question":"追加補正で約３９７億７,０００万円と、約１１０倍補正されたと、驚きをもってマスコミでも取り上げられています。そのうちの認定件数、否定件数、保留件数と支払金額についてお聞きします。","respondent":"濱中新型コロナウイルス予防接種担当課長","answer":"認定に伴う支給額につきましては、約３８６万円となっております。今後、健康被害救済に関しまして丁寧にご相談に対応するとともに、迅速かつ適切に手続を進めてまいります。","id":"exchange-051"},{"speaker":"おぎの委員","kind":"意見","question":"死亡一時金が４,５３０万円ですので、この時点で、品川区民の死亡認定は出ていないということがうかがえます。令和６年４月以降の新型コロナワクチン予防接種の対象者の変更点について説明を求めました。","respondent":"濱中新型コロナウイルス予防接種担当課長","answer":"制度が大きく変更しまして、秋から冬にかけて年１回、接種を実施する予定です。使用ワクチンは、最新の流行株に対応したワクチンを接種します。","id":"exchange-052"},{"speaker":"ひがし委員","kind":"質問・要望","question":"先月の一般質問において、また予約をネットでもできるようにしてほしいと、利用者目線での改善について要望しておりました。一般質問の回答でも、利用者アンケートでの複数回利用の要望、また多くの方から利用の要望を頂き。","respondent":"石橋品川保健センター所長","answer":"私からは、産後ケアの拡充についてと、工夫した点についてご回答いたします。電子申請での予約という形を４月から取れるように、今、進捗を進めているところになります。","id":"exchange-053"},{"speaker":"ひがし委員","kind":"質問・要望","question":"ぜひ日帰り型、また訪問型にも拡充してほしいと思うのですけれども、課題がどのようなところにあるのかというのを聞かせてほしいと求めました。区民の妊産婦の方々にお話を伺っても、ネットでの予約は実現してほしい、子育てのお知らせがまとめて見られるとうれしいなどの声もありました。","respondent":"石橋品川保健センター所長","answer":"要件緩和をすることで人数が増えていくと想定されますので、その人数に鑑みて、場所や実施場所を課題として検討してまいりたいと考えております。","id":"exchange-054"},{"speaker":"ひがし委員","kind":"質問・要望","question":"確認してみると、産後ケアというところの事業を導入していただければいいかと要望して、次に行きます。先ほど山本委員から、この結果を区としてどういうふうに分析しているのですかというような質問がありましたが、個別で受診券を送付していて。","respondent":"若生健康課長","answer":"令和３年度から未受診者への再勧奨という形でおはがきをお送りしたりということをやっていまして、確実に受診につなげてまいりたいと考えております。","id":"exchange-055"},{"speaker":"ひがし委員","kind":"意見","question":"１点、男性の前立腺がんというのは、すごく多いのです。時間がないのでお尋ねしませんけれども、罹患率が高い、その点については検討してほしいと求めました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-056"},{"speaker":"のだて委員","kind":"質問・要望","question":"運送業者への物価高騰対策支援金の継続を求め、３０５ページ、省エネルギー対策事業にも関わって質問します。この間の実績と実施期間、いつまでかというのを、それぞれの事業について伺います。","respondent":"小林商業・ものづくり課長、若生健康課長","answer":"１００件分追加するという形で、今年の１月３１日までの間にちょうど予算枠といいますか、使い切るような形で終了したところです。… 公衆浴場の物価対策支援金のところですが、こちらについても第４回定例会の補正予算で計上しまして、それで申請を受け付けてきたところです。… こちらは、申請期間としまして、まだ現在も受け付けているところですけれども、１月２５日から受付を開始しています。","id":"exchange-057"},{"speaker":"のだて委員","kind":"質問","question":"それで、運送事業者はまだ受付中ということで、それはいつまでなのかというのを伺いたいと思います。銭湯のほうは１年間、３月までということですけれども、まず運送業者のものを伺いたいと思います。","respondent":"小林商業・ものづくり課長","answer":"運送事業者等燃料費高騰対策支援金につきましては、先ほど申し上げたように１月２５日からスタートしまして、今、受付の終了期限としましては令和６年３月１５日までということで対策を進めているところです。","id":"exchange-058"},{"speaker":"のだて委員","kind":"質問・要望","question":"なぜ当初予算で組まなかったのでしょうか。伺いたいと思います。","respondent":"小林商業・ものづくり課長、若生健康課長","answer":"商業・ものづくり課で実施しております省エネ対策の更新助成金、運送事業者等の燃料費高騰対策支援金ですけれども、燃料費高騰が。こうした動向を見て、今後の支援… 燃料費の高騰等の状況については、他の補助等も踏まえつつ、状況を見ながら検討していきたいと考えております。","id":"exchange-059"},{"speaker":"のだて委員","kind":"質問・要望","question":"銭湯は東京都で補正を組んだりというお話がありましたけれども、既にそういうもので予想されているものがあるということなのか、伺いたいと思います。やっていただきたいと思うのですけれども、既に物価高騰が収まっているという考えなのか、伺いたいと思います。","respondent":"若生健康課長、小林商業・ものづくり課長","answer":"７月ですか、それを受けて区でも検討してというところで、第４回定例会の補正というところでやっております。令和６年度については少しまた状況を見てというところになるかと思いますので… 物価高騰はやはり続いていると考えております。直近の状況で見ますと、こういうところを見ながら、区内企業にとって今どういう状況が大変なのかということを引き続き考えていくという状況です。","id":"exchange-060"},{"speaker":"のだて委員","kind":"質問・要望","question":"これまで行ってきたところをぜひ実施していっていただきたいと要望しておきたいと思います。この事業の概要と、本年度の実績を伺います。","respondent":"小林商業・ものづくり課長","answer":"１点目の省エネ対策に効果があるかというところで、そこに対して省エネ効果が見られたものに対して支援を行っているというものです。企業と東京都が、奨学金を負った方が入社した場合にその負担を軽減する仕組みに、企業負担の部分の２分の１を区が支援するという状況です。","id":"exchange-061"},{"speaker":"のだて委員","kind":"質問・要望","question":"環境対策としても、温暖化対策としても、ぜひ実施していってほしいと求めました。これはむしろ平時から利用できる仕組みにしていくべきだと思いますし、奨学金返還金支援制度も引き続き。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-062"},{"speaker":"中塚委員","kind":"質問・要望","question":"対象が６５歳からということですが、ぜひ若い世代も対象にしてほしいと求めましたが、いかがでしょうか。若い世代がどういう状況に置かれているのか、対象年齢の議論の出発点にしてほしいと求めましたが、いかがか尋ねました。","respondent":"坂野保健予防課長","answer":"今度、新型コロナウイルスのワクチンも来年度、Ｂ類になるわけなのですが、結局これらに関して、既に今年度は２,５００円の自己負担でやっています。","id":"exchange-063"},{"speaker":"中塚委員","kind":"質問・要望","question":"２,０００万円ためろと言われ、老後の不安を調べるとＮＩＳＡやｉＤｅＣｏが言われるが、そんな余裕はとてもないという状況をよく伺います。まずは実態調査も行って、支援策や対象年齢も検討してほしいと求めましたが、いかがか尋ねました。","respondent":"坂野保健予防課長、阿部品川区保健所長","answer":"予防接種のことだけ私からお答えします。そこで、Ｂ類の人に支援しようというスキームでやっております関係上、この年齢を変えるというところにはならないのかと思います。 予防接種以外のところで保健所の所管する内容について、概要を私からお答えいたします。その中で、必要な施策については年齢を問わず対応していくことが必要と考えますけれども、予防接種や健康診断等につきましては。","id":"exchange-064"},{"speaker":"中塚委員","kind":"質問・要望","question":"例えば品川区が被災地となった場合、営業許可はどうなるのか、伺いたいと思います。例えば受け入れるための、品川区でもホームページで必要な情報を発表してほしいと求めましたが、いかがか尋ねました。","respondent":"舩木生活衛生課長","answer":"こういったことに対して、無償で災害支援を行う場合は、このことに関しての食品営業許可は必要ないものと考えられます。この辺りも、やはり移動販売の特性を活かして、この辺りはまさに防災計画のあたりでしっかり今後整備されていくものだと認識しています。","id":"exchange-065"},{"speaker":"中塚委員","kind":"質問・要望","question":"いつ起きてもおかしくないと言われている中で、ぜひキッチンカーがその力を発揮できるように、環境整備をお願いしたいと思います。様々な食の提供というのは支援の柱になってくるかと思いますので、防災課などとの連携を強くしてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-066"},{"speaker":"せりざわ委員","kind":"質問・要望","question":"私からは、あと３０９ページの資源持ち去り防止対策費、２９１ページのしながわ健康プラン２１等策定についてということでお伺いしたいと思います。「去年も使ったな」とか、ぜひ名前も新しい名前でＰＲしていただきたいと思うのですが、ご見解を説明を求めました。","respondent":"小林商業・ものづくり課長","answer":"例年、３月末に、品川区の令和６年度の予算施策を説明する助成金の制度説明会というのをまとめてやっているものがあります。分かりやすいというようなことも心がけながら、この補助金なり助成金を広く使っていただけるようにということで取り組んでまいりたいと思います。","id":"exchange-067"},{"speaker":"せりざわ委員","kind":"提案","question":"これは要望で、進めていきます。ある調査だと約２０％から３０％ぐらいが、いろいろな自治体で資源ごみを、持ち去りをされていると伺っていますとの意見を述べました。","respondent":"品川品川区清掃事務所長","answer":"パトロールをしているのですが、やはり持ち去りも現状は続いているということで、そこを継続しているというような段階です。それから過料ですが、現在５件、過料を取っているという実績はあります。","id":"exchange-068"},{"speaker":"せりざわ委員","kind":"質問・要望","question":"資源ごみという名前で、ごみと言われてしまいますが、リサイクルを求めて、区民も区に対してお渡ししている。取締りの方法も、今いろいろ見回りをしていただいていると伺っております。","respondent":"品川品川区清掃事務所長","answer":"防犯カメラ等をいろいろ活用しながらという方法は非常にいい方法だと思いますので、こういったところも十分に考慮しながら、今後の対策については検討していきたいと考えています。","id":"exchange-069"},{"speaker":"せりざわ委員","kind":"質問","question":"若干、話がずれるのかもしれないのですが、健康プランにも書いてあると思います、心の健康の側面からお伺いしたいと思います。１人で、ウェルビーイングというのでしょうか、まず評価を説明を求めました。","respondent":"若生健康課長","answer":"筋トレと心の健康に関してです。それが科学的にも効果があるというところで進めているところですけれども、健康プランの改定で、しっかり検討していきたいと考えております。","id":"exchange-070"},{"speaker":"せりざわ委員","kind":"意見","question":"そういう意味で、大井のエリアに健康センターというのがないと思っていて、健康センターのこれからの拡充というのはどうお考えなのか。１つ、在り方としてあるのかと思うのですが、その感覚もご見解を説明を求めました。","respondent":"若生健康課長","answer":"健康センターの拡充については、今後、様々考えてまいりたいと考えております。それから、民間のフィットネスジムへの補助といったものも、民間との連携についても今後考えてまいりたいと思います。","id":"exchange-071"},{"speaker":"つる委員","kind":"質問・要望","question":"それぞれ産後ケアの拡充を求めさせていただいたものが、来年度もしっかりと強力に進めていただきたいと、まず思います。先ほど答弁で確認させていただきましたが、経産婦もぜひ対象にしてくれと求めさせていただいていて、本当に感謝しているところであります。","respondent":"石橋品川保健センター所長","answer":"次年度以降、しっかり対応してまいります。次年度以降、そういったメニューの中でまたいろいろ要望がありましたら、検討を考えていきたい、課題として考えていきたいと考えています。","id":"exchange-072"},{"speaker":"つる委員","kind":"質問・要望","question":"この辺の療養支援等については、引き続きの拡充をお願いしたいと、求めたいと思います。動きが１つあるわけでありますが、品川区の取組と、この辺りの考え方について説明を求めました。","respondent":"小林商業・ものづくり課長","answer":"生きがいや、あるいは社会貢献といった気持ちを持って働けるようにということで、いろいろ支援をしています。今、引き続き就労の場というのができるだけ広がる、あるいは希望に沿ったお仕事の場が提供できるような支援をしてまいりたいと考えております。","id":"exchange-073"},{"speaker":"つる委員","kind":"質問・要望","question":"「ｍｏｔｔＥＣＯ」の取組もぜひ活かしたらどうですかというところで、２３区で見ると昨年、品川区はドギーバッグということでやっていただきます。単価が２０５円で１,４４０個と、それから郵送料で１,０３０円５０個と分かれているのですが、この違いなどを説明を求めました。","respondent":"河内環境課長","answer":"やはり自分のメニューの中の、例えば小盛り対応など、細々したところをご対応いただくことになりますので。２００円の単価につきましては、いろいろまた現場の声も踏まえて選定を進めていき、使いやすい制度にして仕上げていきたいと考えているところです。","id":"exchange-074"},{"speaker":"つる委員","kind":"質問・要望","question":"注文をタブレットでやるものですから、どうするのだということで、まさに「ｍｏｔｔＥＣＯ」だったのです。イベント自体は２年目ですか、やっていただいて、ファッションショーもついにやっていただきました。","respondent":"小林商業・ものづくり課長","answer":"昨年１０月に、エシカルファッションショーを初めて取り入れる形で、エシカル消費イベントというのを実施いたしました。いろいろ我々、新たな連携先なども含めて、またこの事業を一生懸命やってまいりたいと考えております。","id":"exchange-075"},{"speaker":"つる委員","kind":"質問","question":"あちこち行くと１日で回り切れなかったのではないかというところもありますので、連携してどうやってやっていくのかも含めて、環境啓発・推進事業として説明を求めました。","respondent":"河内環境課長","answer":"私どもの取組で、エシカルファッションとサステナブルファッション。社会意義を伴うのがエシカルファッションと認識しておりますが、日付もきちんと工夫しながら、しっかり進めてまいりたいと考えているところです。","id":"exchange-076"},{"speaker":"つる委員","kind":"質問・要望","question":"時間がないので、商業・ものづくり課の課長から答弁がなかったですけれども、しっかりと勉強して、いい味わいを来年度も出していただきたい。私もファッションショーの一員として出られたらいいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-077"},{"speaker":"やなぎさわ委員","kind":"質問","question":"１１月から、おむつの定期便が始まりました。プロポーザル方式で５社応募があって、配達員の方の採用基準を伺いたいと思いますけれども、お願いします。","respondent":"石橋品川保健センター所長","answer":"見守り支援員の採用基準というところになります。それで、実際の採用は受託者のほうで実施しておりますので、その辺りについては受託者にお願いしている形になります。","id":"exchange-078"},{"speaker":"やなぎさわ委員","kind":"質問","question":"有資格者というのは、保育士や保健師、助産師あたりになってくるのだと思うのですけれども、現在の支援員の方の資格者の内訳を教えていただけますか。","respondent":"石橋品川保健センター所長","answer":"今、見守り支援員は９名おりまして、うち有資格者は１名となっております。残りの８名は子育て経験者というところで採用させていただいていると伺っております。","id":"exchange-079"},{"speaker":"やなぎさわ委員","kind":"質問","question":"９名ということで、これから恐らく１２名ぐらいまで実際増えてくるのかと思うのですけれども、さらに資格者を増やすのは大変なのかと思います。ＴＮＣプロジェクトの方の懐に入っているとすると、ぜひその辺は今後見直しをしていっていきたいと思いますけれども、その点はいかがか尋ねました。","respondent":"石橋品川保健センター所長","answer":"見守り支援訪問は、始まる前にまず２回の研修を実施して、今も月１回、支援員は定期的に研修をしっかりしているところになります。今後、今ＴＮＣプロジェクト、受託者は信用してやっているところにはなりますが、金額についてもしっかりと検討していきたいと考えております。","id":"exchange-080"},{"speaker":"やなぎさわ委員","kind":"質問","question":"お願いします。今、支援員が９名いるということなのですけれども、その方たちが直接雇用なのか業務委託なのかといった内訳はお分かりか尋ねました。","respondent":"石橋品川保健センター所長","answer":"こちらは正式な手続を経て、再委託という形で見守り支援員の雇用をしていると伺っております。","id":"exchange-081"},{"speaker":"やなぎさわ委員","kind":"質問・要望","question":"そうなってくると、もしかしたらＴＮＣプロジェクトが採用に関して、どういう人物なのかといったことに関われていない可能性があると思うのです。なので、その辺をしっかり管理・監督といいますか、していただきたいのですけれども、いかがか尋ねました。","respondent":"石橋品川保健センター所長","answer":"契約が決まった、受託者が決まった時点でも、人に関してはしっかりと対応していただくように受託者にはお願いして実施しております。そちらともしっかり連携を取って図ってやっておるというのを、こちらは今後ともしっかりやっていきたいと考えております。","id":"exchange-082"},{"speaker":"やなぎさわ委員","kind":"質問","question":"よろしくお願いします。時間がなくなったので次なのですけれども、自殺対策なのですけれども、国と区の、１０万人当たりの自殺率の数字を教えていただけますか尋ねました。","respondent":"坂野保健予防課長","answer":"すみません。調べて後で申し上げます。","id":"exchange-083"},{"speaker":"やなぎさわ委員","kind":"質問","question":"恐らく品川区は平均的に全国よりも低いと思うのです。これは計画の中にある自殺率の数値というのを、必ずその計画に入れなくてはいけないものなのか、教えていただけますか。","respondent":"坂野保健予防課長","answer":"令和４年の実績で、人口１０万人ベースで、全国が１７.４％で、品川区は１２.５％。普通、私が見た範囲では、どこの自治体のものにも入っていたというところです。","id":"exchange-084"},{"speaker":"やなぎさわ委員","kind":"意見","question":"実際にもう起きてしまっていたら、その方は亡くなっているから、どうしようもない。改善ができないし、つまり基本的にゼロを目指すべきで、基本的にはゼロを目指すという気持ちでやっていただければいいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-085"},{"speaker":"木村委員","kind":"質問","question":"少し足のぐあいが悪いものですから、座ったままで質問をします。質問ですけれども、改めて、このモンゴル高専との科学技術交流事業の目的は何か尋ねました。","respondent":"小林商業・ものづくり課長","answer":"卒業後の進路としまして日本で働きたいと考える学生が多く、品川区では海外からの人材の確保、人材交流を行うこととなりました。引き続き、こういう事業に品川区として力を入れていきたいと考えています。","id":"exchange-086"},{"speaker":"木村委員","kind":"質問","question":"２０２４年２月、令和５年の１年間に生まれた子どもの数は、過去最少で７５万人になったとの厚生労働省の発表がありました。そこでお聞きしますけれども、この事業が開始されてから、これまで何人が日本での就職を果たしたのか尋ねました。","respondent":"小林商業・ものづくり課長","answer":"途中、その間は止まっていた部分もありますけれども、これまでに計２０名の卒業生が区内中小企業６社に就職しております。その知識、能力を活かせる分野として、いずれも区内中小企業の製造業やものづくり企業に就職を果たしています。","id":"exchange-087"},{"speaker":"木村委員","kind":"質問","question":"言葉の問題もあろうかと思いますが、どのような業種の企業に就職しているのでしょうか。説明を求めました。","respondent":"小林商業・ものづくり課長","answer":"一番ネックになってくるのが、日本語をきちんと話せるかどうかが、きちんと将来的に続くのかどうかということに影響してくると思います。企業の取組としてやはり長く続いていただいて、活躍していただくということも含めて、品川区の事業としてこの事業を進めているところです。","id":"exchange-088"},{"speaker":"木村委員","kind":"質問","question":"日本の若者でさえそうですから、進められないということでありますから、不安な点もあろうかとも思います。お聞きしますけれども、就職のミスマッチなどをなくし、スムーズに日本の生活や会社に入っていけるような配慮や工夫はされているのか尋ねました。","respondent":"小林商業・ものづくり課長","answer":"こうした形で、モンゴル高専側あるいはモンゴル国側に伝えることによって、この信頼関係を長く続けていきたいと考えています。","id":"exchange-089"},{"speaker":"藤原委員","kind":"確認","question":"関連します。双方の意思を確認しながら、モンゴルの若者たちが長く元気で働いてくれることが重要だと思いますが、いかがか尋ねました。","respondent":"小林商業・ものづくり課長","answer":"日本できっちり働いていただいて活躍していただくことが、モンゴル高専の後輩の若者たちからすると、「先輩がきちんとああいうところで活躍している。","id":"exchange-090"},{"speaker":"藤原委員","kind":"質問・要望","question":"この事業はプラスになっていることは確かで、品川区にとってもメリットの大きい事業だと考えますが、いかがお考えになるでしょうか。この事業を大切に品川区で育てていただきたいと考えていますので、その辺についてもお伺いします。","respondent":"小林商業・ものづくり課長","answer":"つまり、今後、区内の中小企業の中で、ひとつ将来的に安心して働いていただける人材だということの認識もできているのだと思います。我々職員や、また、こちらとしてもこういう人材が欲しいのだということがきちんと伝わるような信頼関係をつくっていきたいと考えています。","id":"exchange-091"},{"speaker":"藤原委員","kind":"意見","question":"グローバルという意味でもモンゴルは大切だと私は思うのですが、やはり、毎回区民委員会でもお話ししていますが、まず日本の方たちをどういうふうに守っていくかが私は大事だと思っているのですけれども、最後にその辺も含めて答弁していただけますかとの意見を述べました。","respondent":"小林商業・ものづくり課長","answer":"若者たちも結構、助成制度など、区も支援して企業と折半するような負担の割合での取組なども進めているところです。ですので、国内の若者たちがしっかり働いていきたい、区内で働いていきたいという応援をしていきたいと考えています。","id":"exchange-092"},{"speaker":"澤田委員","kind":"質問","question":"３０１ページ、健康診査、３０７ページ、もったいないプロジェクトについて質問いたします。ここ数年の受診者の人数は、増加傾向または減少傾向にあるのか、そのように至った理由についてご見解を説明を求めました。","respondent":"若生健康課長","answer":"令和３年度から未受診者方に個別に、受診期限の３か月程度前に通知を差し上げて、再勧奨という形で行っている。広報紙や、それから図書館や商業施設などでも、女性のがんについて啓発を強化して行っているところです。","id":"exchange-093"},{"speaker":"澤田委員","kind":"提案","question":"そのような未接種の方たちは、西村委員も先ほど様々提案していたように、ＨＰＶ検査の導入が効果的だと考えます。区としてはＨＰＶ検査の導入についてどのようなお考えでいるのか、また方向性などを説明を求めました。","respondent":"若生健康課長","answer":"国から２月に通知がありまして、がん検診の在り方検討会の議論を踏まえて、子宮がん検診にＨＰＶ検査単独法ということで追加されたところです。","id":"exchange-094"},{"speaker":"澤田委員","kind":"質問","question":"区として店舗を増やすため、推進店を増やすために取り組もうとしていることがあれば、教えていただけたらと思います。情報の発信についてもどうお考えか説明を求めました。","respondent":"河内環境課長","answer":"取組にご参加くださる皆様、利用者に、知りやすいように工夫を進めてまいりたいと考えています。エコルとごしですが、こういった定常的な取組もしっかりと発信し、皆様にご理解いただけますよう進めてまいりたいと考えているところです。","id":"exchange-095"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"３２１ページ、３１５ページ辺りで、五反田バレー等について質問します。","respondent":"濱中新型コロナウイルス予防接種担当課長","answer":"新型コロナワクチンの定期接種化に伴う救済制度の変更についてです。年金の額や死亡一時金、遺族一時金などといった制度も変更がありますので、こちらも丁寧に区民の皆様に周知していきたいと考えています。","id":"exchange-096"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"３１９ページから３２１ページを様々見ていくと、地域電子マネーなどなど、中小企業や商店街の皆さんに様々な支援をしている。ぜひ進めていっていただきたいと思うのですが、その辺をどのようにお考えか、お知らせください。","respondent":"舩木生活衛生課長、小林商業・ものづくり課長","answer":"こちらは昨年の５月に５類相当に変更する前に、令和５年３月のときに、３年以上にもわたったコロナの対応をしっかりと検証して。間もなく最終的に区民の方に公表する予定にしておりますので、どうぞよろしくお願いいたします。 商店街や、あるいは物づくりの分野も、こういったところの連携ができてくるのかとは思っております。令和６年度におきまして、こういった中で、いろいろ新たな相乗効果を生み出すような取組を進めていきたいと考えております。","id":"exchange-097"},{"speaker":"塚本委員","kind":"質問・要望","question":"１億１,３９７万７,０００円ということで、かなり実施に向けて要望させていただいてきましたし、今年度から始まりました。シングリックスが５,４１０件、これが２回かかるということが、予算を多く確保した理由についてお伺いいたします。","respondent":"坂野保健予防課長","answer":"１回当たりの値段が大体、実は今年度の８月から事業がスタートしたのですが、半分より少し多いぐらいだろうというのが実は予想だったのです。それで、令和６年度の予算としては、シングリックス、不活化ワクチンのほうに多めに数を割り当てたという経緯です。","id":"exchange-098"},{"speaker":"塚本委員","kind":"質問","question":"そのときにシングリックスというもののワクチンとしての優位性ですか、この２つのワクチンのどちらがよいかみたいなお話というのは、どのように評価されておりますか尋ねました。","respondent":"坂野保健予防課長","answer":"まだ出てきていない感じですけれども、それを出すには相当、逆にこれは時間がかかる。一年、二年では、いわゆるワクチン効率を計算するような値はなかなか出てこないと考えております。","id":"exchange-099"},{"speaker":"塚本委員","kind":"質問","question":"一応、ホームページなどでは医者によく相談してどちらを打つかというのを決めてほしいと、シングリックスのほうがいいのではないですかというお話が。こういったことについて、もう間もなく新札に変わっていくわけですけれども、区に区内中小企業者から相談というのは来ているのか尋ねました。","respondent":"小林商業・ものづくり課長","answer":"ただいま、新札発行に関する相談といいますか、経営相談があるかというお話です。三件程度ですけれども、やはり何か使える制度はないのですか、設備投資を支援するようなものはありますかというようなお問合せはございました。","id":"exchange-100"},{"speaker":"塚本委員","kind":"質問","question":"そういった中で、実際に使える支援策、簡単に言えば、買ったときに幾らか補助できるのですかと。実際に区として、また都や国なども含めた形で、あるのかないのかということについてお知らせください。","respondent":"小林商業・ものづくり課長","answer":"例えば物価高騰の総合支援資金ということでいきますと、３年間無利子で信用保証料全額を支援するという制度で、資金調達。国の支援制度ということでいきますと、こういう支援制度があり得ますということはきちんとご説明できるようにしていきたいと考えています。","id":"exchange-101","title":"町会・自治会支援"},{"speaker":"塚本委員","kind":"意見","question":"ぜひお願いしたいと思いますけれども、区としての情報発信、周知をよろしくお願いしたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-102"},{"speaker":"田中委員","kind":"質問","question":"私は、３２３ページの商店街活性化推進事業についてお伺いいたします。改めて、この共通商品券、プレミアム付商品券の商店街活性化に向けた目的・意義についてお伺いします。","respondent":"小林商業・ものづくり課長","answer":"今回、令和６年の春に行います商品券発行事業というのは、またポイントも春に行う場合はプレミアム率を２０％という形にする事業です。","id":"exchange-103"},{"speaker":"田中委員","kind":"質問・要望","question":"この春は２０％のプレミアムをつけ、いわゆる補正予算で令和６年度分の春分は決定し、実行されようとしております。昨年は５月１９日からということで、僅か１０日ほど前倒しで、補正予算を組んでまで早めにやろうとした狙いについてお聞かせほしいと求めました。","respondent":"小林商業・ものづくり課長","answer":"政府の経済認識というところでいきましても、やはり今、足踏み状態という部分になってきているのだろうと。少しでも早く、そういうものとの連動性なども考えまして、タイミング的に少しでも早くということで実施するものです。","id":"exchange-104"},{"speaker":"田中委員","kind":"質問","question":"要は２億円が上乗せされた、私もまだ１期生だったと思いますが、それを前向きに活かしていくべきではないかと。合計１２億円ですが、要は２億円が広まるというだけではなくて、商業・ものづくり課としてのご指導をいかがお考えか尋ねました。","respondent":"小林商業・ものづくり課長","answer":"先ほど申し上げましたように、この事業は２００３年から始まって、発行支援という形で品川区商店街連合会の支援事業としてやってあります。台所用品など、そういうものに使っていただいているという意味で、より区民に愛着を生んでいる事業なのではないかと思っているところです。","id":"exchange-105"},{"speaker":"田中委員","kind":"質問","question":"ぜひお伺いしたいのですが、目標は申込み件数が１つ目標数値となっておりますが、評価項目は申込み件数だけとなっております。もう一段高い目標を掲げて、商店街のいわゆる活性化にという視点での評価にもつなげていくべきだと思いますが、いかがか尋ねました。","respondent":"小林商業・ものづくり課長","answer":"ただいま、行政評価シートの関係でもお尋ねいただきました。一番、こういうものの認知が区民に深まり、よりこういうものを使って近所の商店街でお買物をしていただくということも一緒に進めていきたいです。","id":"exchange-106"},{"speaker":"田中委員","kind":"質問・要望","question":"商品券そのものの売上げ増進も１つの目標と掲げられていますが、そして商店街の支援がまずは第一にあるべきだという考えに基づくと、より有効活用していく上でのお気持ちを改めてお聞かせいただきたい。","respondent":"小林商業・ものづくり課長","answer":"区民の皆さんの身の回りのところでというところで、いろいろ、この点も含めて、今後どういう対象範囲がいいのかというのは考えていきたいと考えています。","id":"exchange-107"},{"speaker":"えのした委員","kind":"質問","question":"私からは、３０５ページ、自殺対策事業についてお伺いします。その後の区の取組や対策をお知らせください。","respondent":"坂野保健予防課長","answer":"９月と３月が予防月間というふうに、組み合わせるというか、啓発を実施しています。カードについては、品川区は非常に駅がたくさんございまして、各駅にカードを置かせていただいているという形を取らせていただいています。","id":"exchange-108"},{"speaker":"えのした委員","kind":"質問","question":"孤独・孤立対策推進についてお伺いしましたが、約５０％の方が孤独を感じると回答しており、自殺者が増加。女性に対する支援の強化、地域自殺対策の取組が重要だと考えますが、区の現状と自殺対策計画をお知らせください。","respondent":"坂野保健予防課長","answer":"その際の対応方法など、１回の研修で、こういった研修を繰り返し実施しています。令和６年度に中間の見直しというのが予定されておりますが、その中でも、子ども・若者への視点は重点施策の一つとして挙げられているところです。","id":"exchange-109"},{"speaker":"えのした委員","kind":"質問","question":"子ども・若者の取組を、さらに拡充して進めてほしいと求めました。今、すぐに厚生労働省のページなどにつながるようになっていますので、こちらも具体的に詳しくお知らせいただけますか尋ねました。","respondent":"坂野保健予防課長","answer":"今委員がおっしゃられたように、相談先を案内するような検索アルゴリズムで、相談先に誘導していく。その相談先につながった後は、人手でやっているという感じです。","id":"exchange-110"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"ぜひその辺も考えていただきたいのと、お礼を言ってほしいのは、ペットボトル。もっと言ってほしいと思うのだけれども、ぜひそこはもう少しやってほしいと思っているので、それについてのお答えをそれぞれ頂きたいと思います。","respondent":"品川品川区清掃事務所長","answer":"やはり、でも検討していかなくてはいけないというところは確かにありますので、進めていきたいと考えています。説明会等もありますので、そういうところでは区民の皆様方にぜひお礼をして、やっていきたいと考えています。","id":"exchange-111"},{"speaker":"石田（秀）委員","kind":"意見","question":"合計で８８.２％で、それから中間層の方々の収入をもっとしっかり拡充していくべきだろうと思っていて、これは１つだけどうしても聞きたかった。","respondent":"小林商業・ものづくり課長","answer":"副業など、新しい働き方が出てまいっておりますので、いろいろな制度を見ながら人材の問題も考えていきたいと思います。","id":"exchange-112"},{"speaker":"松永委員","kind":"質問","question":"２９９ページの、３０７ページのカラス及び外来種対策事業について、同じく３０７ページのマイボトル用給水機設置助成について伺います。初めに２９９ページの、そ族昆虫防除対策費について伺います。","respondent":"舩木生活衛生課長","answer":"令和３年度５４７件、令和４年度６９６件と、かなり多くの相談を受けております。この辺りは特に次年度も、今年度と変わりなくスズメバチもほかの蜂も同様に、区で相談に応じて駆除の対策等を取っていく予定です。","id":"exchange-113"},{"speaker":"松永委員","kind":"質問・要望","question":"早急に対応していただきたいのですが、この時期、特に４月から１１月、梅雨明けが特にそうした被害が大きいということを思います。様々グッズなどはあるのですけれども、そうした予防対策についての補助というのはあるのかどうか、確認だけさせてください。","respondent":"舩木生活衛生課長","answer":"今のところ、住まいのところに発生する巣に関しての助成の制度は持ち合わせておりません。","id":"exchange-114"},{"speaker":"松永委員","kind":"質問・要望","question":"様々あるのですけれども、その中で調査場所について、どのくらいやられているのか確認させてください。調査された場所について、どういったところをやられているのか、改めて伺います。","respondent":"舩木生活衛生課長","answer":"１か所当たり年に４回、薬剤を投入して、蚊の対策を行っております。要望があれば窓口で薬剤もお渡しすることが可能ですので、こういった場合は管理者などに、自身で雨水ますに投入するようにお願いしています。","id":"exchange-115"},{"speaker":"松永委員","kind":"質問・要望","question":"ユスリカの病気ですか、アレルギー性鼻炎などといったところでも、結構被害に遭われている方もいらっしゃるそうです。もちろん近隣住民の方に対しても、そうした周知をしていただきたいのですが、品川区の対応・対策をお知らせください。","respondent":"舩木生活衛生課長","answer":"こういった水生幼虫には、区の場合はそこをもって、蚊と同様に対策を取っているものと認識しております。どういった対応かは存じ上げませんが、保健所としてはユスリカ対策も含めた対応を取っているということで答弁します。","id":"exchange-116"},{"speaker":"松永委員","kind":"確認","question":"これは現在もその１店舗のみなのでしょうか。予算書の中にはそうしたところが見当たらないのですが、どうなっているのか尋ねました。","respondent":"品川品川区清掃事務所長","answer":"以前はリサイクルショップ等で売っていたのですけれども、今回、廃止になってしまっておりますので、現在は西友だけで売ってあります。カラスにつきましてはカラス用ネットを今、区としては配布して対策を取っているというところを、一般的な対応としてやっているところです。","id":"exchange-117"},{"speaker":"松永委員","kind":"質問・要望","question":"次に、ハトについて、野鳥について伺います。ほかにも何か方法はあるのかどうかということなのですが、路上喫煙まではいかないとは思うのですけれども、その見解についてお知らせください。","respondent":"河内環境課長","answer":"大田区などが設置している状況でありますが、注意し、粘り強く対応というのが基本になってくるかと思います。まき散らすということはないのですが、そのような良識の中でも甘えることなく、しっかり粘り強く対応することが基本かと考えています。","id":"exchange-118"},{"speaker":"松永委員","kind":"質問","question":"ハトの駆除１万１,０００円からなど、なぜネットではできていて品川区ができないのかというと、恐らく法律があるからだと思います。駆除してほしいという方に対して、そういったところの補助というのはできるものなのかどうか、伺いたいと思います。","respondent":"河内環境課長","answer":"むしろ、野生の保護に向かって保護していくべき動物という法律の位置づけになってあります。そういった特定の狩猟許可を得た業者など、精査に精査を重ねまして、有効な対策になりますように重ねて取り組んでいるところです。","id":"exchange-119"},{"speaker":"松永委員","kind":"質問・要望","question":"要望です。ありがとうございました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-120"},{"speaker":"西本委員","kind":"質問","question":"そして３０３ページのＨＰＶワクチン予防接種、３０３ページの感染症予防費についてお伺いします。それをまず説明を求めました。","respondent":"石橋品川保健センター所長","answer":"すくすく赤ちゃん訪問の目的につきましては、児童福祉法に位置づけられ、今は国のガイドラインに基づいて実施しております。こちらは区独自事業として実施しておりまして、行政とのつながりを感じていただき、安心して子育てをしていただく。","id":"exchange-121"},{"speaker":"西本委員","kind":"質問","question":"今、目的をお聞きしましたけれども、かぶっているのです。民間に頼むかどうかは分かりませんけれども、さらに、いかがか尋ねました。","respondent":"石橋品川保健センター所長","answer":"今、申請ベースというお話がありましたが、こちらは申請されていないご家庭に関しては勧奨ということを定期的に実施しているところになりますので。国のガイドラインに基づいて実施しておりまして、時間としては１時間程度、育児指導を行っているところになります。","id":"exchange-122"},{"speaker":"西本委員","kind":"質問・要望","question":"迅速性が求められるということだと思います。今回、男性なのですけれども、なぜ男性にこのワクチンを接種することになったのか尋ねました。","respondent":"坂野保健予防課長","answer":"こういった形で検疫所との連携で、非常に慣れておられるので、そういったところと連携したスキームが必要なのではないかと思います。ＨＰＶの男性接種の補助を４月からスタートするわけですが、長期的に見て、恐らく子宮頸がんの抑制につながるのではないかという仮説があります。","id":"exchange-123"},{"speaker":"西本委員","kind":"質問","question":"これは、品川区で何かあったときにどうやって責任を取るつもりですか。そこを、答えるよう求めました。","respondent":"坂野保健予防課長","answer":"今のスキームだと、女性は法定というか定期接種なので、そちらのスキーム。男性は任意接種ですので、ＰＭＤＡ、医薬品医療機器総合機構の補償スキームというものが使われることになろうかと考えています。","id":"exchange-124"},{"speaker":"若林委員","kind":"質問・要望","question":"２３区全体の問題でもあり、さらには特別区長会での検討・結論が求められる問題でもありますので、よろしくお願いいたします。混載が可能となった規制緩和についての認識と評価をお聞きいたします。","respondent":"品川品川区清掃事務所長","answer":"それから、これは２３区全体で要綱変更をしないと、やはり２３区全体としての対応が必要であること。それから、ほかの廃棄物についても同じような意見が出るのではないかというところも懸念されるところで、現在は検討しているという状況です。","id":"exchange-125"},{"speaker":"若林委員","kind":"質問・要望","question":"ビルピット汚泥については産業廃棄物との混載を認める旨の改正をしてほしいと、特別区長会において混載実現に向けた検討を求めるものとなっています。そこで最後に、特別区長会において早期の議論が期待されておりますけれども、議論されるに当たり、認識をお聞きしたいと思います。","respondent":"品川品川区清掃事務所長","answer":"現在のところ、今、委員がお話になったとおり、区長会まで話が出て、議論をしているというところになります。今後多分、再検討するなどという話も考えられると思いますので、またその状況に応じて対応を考えていきたいと考えています。","id":"exchange-126"},{"speaker":"せお委員","kind":"確認","question":"私からは、２９７ページ、不妊治療等支援事業、同じページで猫の適正飼養および活動支援事業を伺います。こちらは確認ですが、もし男性も女性も治療があった場合でも、それぞれ助成していただけるとの認識でよろしいか尋ねました。","respondent":"若生健康課長","answer":"どういった支援をしていくかということをいろいろ検討していったところ、支援が入っていないところに支援していきたいということで。不妊当事者であるピアカウンセラーが中心になって相談をお受けする予定で、経済的な部分も含めてというような相談内容があるかと想定しています。","id":"exchange-127"},{"speaker":"せお委員","kind":"提案","question":"国も保険適用の実施２年で見直しなどの検討を行うと伺っておりますので、国の動向も見ながら、引き続き調査研究をよろしくお願いいたします。ここからは思いだけ、あるクリニックの院長にお話を伺ったときに、４３歳以上の患者はそちらのクリニックでは４分の１いらっしゃるとの意見を述べました。","respondent":"舩木生活衛生課長","answer":"安心して活動ができるなど、こういった活動の公共性を区が後押しすることで、活動性の信頼性を高めていきたいと考えております。今の委員の、主体的な団体の卵ではないですけれども、そういうところも育っていくといいかという意識で区も進めてまいりたいと思います。","id":"exchange-128"},{"speaker":"高橋（し）委員","kind":"質問","question":"１歳６か月児が９７.１％、３歳児が９６.２％、未健診家庭への対応はどのようにしているのか伺います。これを比較すると、利用料金収入が５,３００万円多いのですが、どうして委託料、つまり指定管理のお金が必要になるのか、この関係をお伺いします。","respondent":"小林商業・ものづくり課長、石橋品川保健センター所長、若生健康課長","answer":"あるいは今後の設備投資に対する支援といったところも含めまして、こういった部分は引き続き問題のないように手当てをしていきたいと考えています。… 私からは、乳幼児健診を未受診の家庭のフォローについてご説明いたします。委員のおっしゃるとおり、健診を未受診の家庭のフォローが保健センターではとて… 令和６年度に１億３,０００万円余、収入が見込まれる額、見込みの額を引いた値を指定管理料として定めているところです。","id":"exchange-129"},{"speaker":"高橋（し）委員","kind":"確認","question":"融資のところで、返済状況が滞っているところへの支援というところがあったので、それを確認したいです。","respondent":"小林商業・ものづくり課長","answer":"融資残高でいきますと６００億円ぐらい、実は融資金額について区が支援しているという状況です。問題が起きないように、現在ある制度を使いながら、区内企業の資金繰り支援をやっていきたいと考えています。","id":"exchange-130"},{"speaker":"高橋（し）委員","kind":"質問","question":"今お話があったように、これから返済の状況が迫ってきて、またといいますか、苦しまれる事業者の方がいるので、その支援をよろしくお願いします。この方は全部そういうのをしていないとか、この方はやっているとか、そういうことはチェックされたりしているのか尋ねました。","respondent":"石橋品川保健センター所長","answer":"１つのカルテというものに記入していますので、各事業の情報共有をしながら、しっかり保健師がそれぞれ対応している形になります。","id":"exchange-131"},{"speaker":"高橋（し）委員","kind":"質問","question":"本当に、健診等をやっていない方が０人というか、本当に１００％になるように、大変だと思いますけれども、よろしくお願いします。利用料の一部が入ってくると思うのですが、その表示が予算書にないのですけれども、どこを見れば出ているのか尋ねました。","respondent":"若生健康課長","answer":"こちらについては、歳入の項目になりまして……。その差額の２０％を区に納めていただくというようなことで、協定として取り決めるということにしておりまして、その歳入の分が計上されるものです。","id":"exchange-132"},{"speaker":"高橋（し）委員","kind":"質問","question":"ですから、予算書にも出てこないし、決算書にも出てこない。その点については健康課ではないと思うのですけれども、予算書についてはどうか尋ねました。","respondent":"遠藤財政課長","answer":"全て雑入のところに入っていまして、来年度、６００万円ほど計上しています。ほかの金額が大きいので、代表的なものを書いていますので、今後は検討していきたいと思います。","id":"exchange-133"},{"speaker":"松本委員","kind":"質問","question":"私からは、３１５ページ、創業・スタートアップ等支援経費について伺います。お願いします。","respondent":"小林商業・ものづくり課長","answer":"いろいろ我々でも、２３区、他区の状況というのは調べておりますけれども、恐らく品川区が１位か、それに近いトップクラスだと考えています。新たにＳＨＩＰがオープンしているということもございまして、そういう中で、品川区の中でこういう取組が充実したと認識しています。","id":"exchange-134"},{"speaker":"松本委員","kind":"質問","question":"いい取組で、ほかの自治体から視察もよく来ているようにも伺っていますので、いいことだと思います。そこで、複数の施設があるので、それぞれの施設の直近の入居率をお願いいたします。","respondent":"小林商業・ものづくり課長","answer":"天王洲が、今１０部屋あるうちの７部屋ということで７０％。広町一丁目工場アパートも同様の、７０％、８０％といった稼働率です。","id":"exchange-135"},{"speaker":"松本委員","kind":"確認","question":"私のほうでも募集状況などを確認すると、若干、今のお話でも出ましたけれども、広町のほうが７割だったりすることがあるのかということで、ここがなかなか埋まらないことも過去見ているのですけれども、これはなかなか埋まらない状況が発生するのは、どういう理由がありますか尋ねました。","respondent":"小林商業・ものづくり課長","answer":"２部屋、仮に例えば２部屋とも入った場合ということでいきますと、８割から９割という形になります。そこは入居される企業の意向やニーズということもありますけれども、そういったところが１つ、違いにあるのかと考えています。","id":"exchange-136"},{"speaker":"松本委員","kind":"質問","question":"少し私が思ったのが、工場と書いてあるのですけれども、アパートというとどうしても普通の共同住宅をイメージするのかと思っています。結構もう長く別の使われ方がしているということについて、これは今後どういう見通しをお持ちなのか伺います。","respondent":"小林商業・ものづくり課長","answer":"ちょうどＳＨＩＰが平成２７年にできるときに、オアシスルームでの活用が始まって現在に至っているというところがあります。中小企業といったところの支援もということで、中小企業施策のニーズや変化も見ながら、今後の在り方も考えてまいりたいと考えています。","id":"exchange-137"},{"speaker":"松本委員","kind":"質問","question":"次に、品川ビジネスクラブ助成金に関連して、区も共催されていますビジネス創造コンテストについて伺います。高校生ぐらいだったら、もうプレゼンテーションの機会があってもいいのかと思うのですけれども、この点はどうお考えか尋ねました。","respondent":"小林商業・ものづくり課長","answer":"こうなるようにということで、そういう思いも込めたようなものを書面にしていただいて、我々が審査しているようなものです。ファイナリストとしてやっていただいている例もあるのですけれども、そういう中で、さらに力を伸ばすような応援をしていきたいと考えています。","id":"exchange-138"},{"speaker":"松本委員","kind":"質問","question":"どうしても狭い門を、全国の成人の方たちと戦い抜いてという枠で、結構狭い門かと思います。起業の事業計画などというのをつくるようなことも、試みられてもいいのではないかと思いますが、いかがか尋ねました。","respondent":"小林商業・ものづくり課長","answer":"我々としましては、創業支援施設は個々に運営しているというよりは連携して、いろいろイベントなども、取組を通じて協力して、新たな才能を伸ばしていくようなことも応援していければと考えています。","id":"exchange-139"},{"speaker":"松本委員","kind":"質問・要望","question":"もう一問あったのですけれども、時間がなくなりましたので、ぜひ引き続き頑張ってほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-140"},{"speaker":"須貝委員","kind":"質問","question":"私は、３２３ページ、共通商品券普及促進事業についてお聞きしたいと思います。この事業について、区民に対する販売周知方法について説明を求めました。","respondent":"小林商業・ものづくり課長","answer":"プレミアム付区内共通商品券の周知です。あるいは区内の郵便局や、あるいは商店街連合会もありますけれども、店舗などでもＰＲをさせていただいているところです。","id":"exchange-141"},{"speaker":"須貝委員","kind":"意見","question":"商品券販売について、お知らせに気がつかない方がたくさんいらっしゃると思います。ここで、区の予算を使うならば、この販売に対する周知方法は、私は非常に不平等だと思うのですが、その辺についてご見解を説明を求めました。","respondent":"小林商業・ものづくり課長","answer":"先ほど、広報しながわも含めというところでお知らせいたしましたけれども、そういった紙を使った媒体での周知という以外に、ホームページや、あるいはＳＮＳという形も使って、なるべく世代もいろいろ異なるというところもありますので、幅広い方法で周知しているという状況です。","id":"exchange-142"},{"speaker":"須貝委員","kind":"質問","question":"区の予算、税金を使うわけですから、区民全世帯に対して平等に、こういう案内を送るべき、周知するべきだと私は思いますが、お答えください。これもついでに説明を求めました。","respondent":"小林商業・ものづくり課長","answer":"令和５年度でいきますと、４万冊、４万冊ということで、春・秋です。例年の販売状況によって変わりますけれども、実際、その中で９割近く、９５％など、それぐらいの割合で販売ができているというような状況です。","id":"exchange-143"},{"speaker":"須貝委員","kind":"質問","question":"これは予算を投入しているのですから、商業・ものづくり課ですが、必要ではないですか。これは私はやはりきちんと直して公表すべきだと思うのですが、ご見解を説明を求めました。","respondent":"小林商業・ものづくり課長","answer":"令和４年度の例えば決算ベースの数字になってしまうのですけれども、春でいくと例えば４万冊、秋でいくと６万１,１７９冊という形で、商店街連合会で後々まとめて、販売状況に応じて、どれぐらいの割合で売れたかという数字は、それぞれの年度において把握しています。","id":"exchange-144"},{"speaker":"須貝委員","kind":"質問","question":"全く中身がないのですから。やはりその辺は私はきちんとやってほしいのですが、もう一度だけご見解を説明を求めました。","respondent":"小林商業・ものづくり課長","answer":"我々も区の決算という形で申し上げているところですけれども、先ほど申し上げたような令和４年度の決算のベース。ただ、我々のほうで把握しているのが冊数ベース、どれぐらいの販売率なのかというところでの把握です。","id":"exchange-145"},{"speaker":"須貝委員","kind":"質問","question":"ぜひ、やはり長年やっているのですから、「品川区商店街連合会さん、その実態を教えてください」と。ご見解を説明を求めました。","respondent":"小林商業・ものづくり課長","answer":"この事業の目的というところで、いわゆる区内消費の喚起というものと、商店街振興、実際の売上げがどう上がるかです。そういう意味では、両方の目的から見たときに、区内区民に対してプラスの効果が出るような事業になっていると考えているところです。","id":"exchange-146"},{"speaker":"須貝委員","kind":"質問","question":"そうしたら、区長だって、いや、区民の税金ですから、区民にやはり還元したい、区民に使ってほしいというのは、誰でもトップに立つ人は当たり前です。ではどういうことですかということは、洋服・スーツ店、ショッピングセンターにも使える。","respondent":"小林商業・ものづくり課長","answer":"現在、プレミアム付区内共通商品券につきましては、商店街連合会加盟のということで約２,０００店舗ということで対象にしています。事業実施ということで、切れ目なく連続実施ということで、キャッシュレス決済といったものも事業を実施していますけれども。","id":"exchange-147"},{"speaker":"須貝委員","kind":"質問・要望","question":"やはりそのような、消費者にも選べる仕組みというのがあっていいのではないですか。やはり、そういうことが消費者の心理ではないか尋ねました。","respondent":"小林商業・ものづくり課長","answer":"ただいまいろいろご指摘いただきまして、今後、我々の産業振興の中も、幅広く支援していく部分と、また見直す部分と、いろいろあるかと思います。そういう部分を含めて研究してまいりたいと考えています。","id":"exchange-148"},{"speaker":"鈴木委員","kind":"質問・要望","question":"これに対して、区としてどう捉えて、どのような対応をしていくのか、伺いたいと思います。早期治療につなげていくということが、とても大事なことではないかと思うのですけれども、区としての見解を伺います。","respondent":"若生健康課長","answer":"やはりそういった医療費の高騰というところもあるかと認識しています。具体的には、科学的根拠に基づくがん検診の実施や区民への周知、それから国の指針に基づくがん検診の実施や精度管理の向上。","id":"exchange-149"},{"speaker":"鈴木委員","kind":"質問・要望","question":"それが第１位に挙げられて、ぜひ品川区としても踏み出してほしいと求めましたけれども、いかがでしょうか。２３区を調査したときに、既にこのときで９区が、それも説明を求めました。","respondent":"若生健康課長","answer":"年度ごとに目標を設置して毎年毎年クリアしていくというようなことはやってございませんが、集計して、毎年努めているところです。生活保護の方につきましては、ご希望に応じて既に無料券を配付しておりまして、低所得者層に対する対策というのは区としては推進しています。","id":"exchange-150"},{"speaker":"鈴木委員","kind":"質問・要望","question":"これが何で今出てきたのかということで伺いたいのですけれども、これは、できたのが平成２５年のときですよね。これも含めて検討されてこういう結果になったのか、どこで誰がこういう結果を出したのかも伺いたいと思います。","respondent":"若生健康課長","answer":"前立腺がんにつきましては、国の推奨するがん検診からは外れております。がん部会からも、これは死亡率減少効果の有無を判断する根拠は現在では不十分だということで、指導を受けているところです。","id":"exchange-151"},{"speaker":"大倉委員","kind":"提案","question":"選挙管理委員会でも、選挙割というのもやってはどうですかというところではあるのですが、これはぜひ商店街の視点から教えてほしいと求めました。１０代、２０代の、こういった選挙割についての考えについて伺いますとの意見を述べました。","respondent":"河内環境課長、小林商業・ものづくり課長","answer":"説明におきましては、お店の方の説明はもちろんなのですが、徹底を図ってまいりたいです。もちろん、区のホームページなどでも、こちらのご案内をする予定です。 投票率アップというのは大変重要な取組だと考えています。その中で、そういう工夫の中で投票率アップに向けて取組を進めていただく、それぞれの自主判断の中で進めていただくということで考えております。","id":"exchange-152"},{"speaker":"大倉委員","kind":"質問・要望","question":"２種類でなどというお話もありましたが、１個だけ、伺いたいと思います。これも質問で、どういったものになるのか教えていただきたいのと、考えを説明を求めました。","respondent":"河内環境課長","answer":"無料で登録できますので、ここに関しましてはしっかりとアプリを登録しながら進めてまいりたいと考えています。エコルとごしなどでも、しっかりと発信していって、利用率が上がるように工夫を重ねてまいりたいと考えています。","id":"exchange-153"},{"speaker":"大倉委員","kind":"意見","question":"よろしくお願いします。給水スポットが増えていくというのもありますし、そうした取組などもいいのかと思うのですが、区の考えをお聞かせほしいと求めました。","respondent":"河内環境課長","answer":"ただ、まだ出始めで、ロケットで言うと第１段階ぐらいです。そういった形の連携もしっかり進めてまいりたいという視野で、今後、設計してまいりたいと考えているところです。","id":"exchange-154"},{"speaker":"あくつ委員","kind":"質問・要望","question":"マイボトル使用の推進の周知については、シンボリックなコラボ動画などを作ってみたらどうですか、広報したらどうですかというご意見もまとめまして。先ほど民間アプリについてはご説明が２つありましたので、ステッカーのロゴデザインのところも伺いたいのですが、意外に難しいと思います。","respondent":"河内環境課長","answer":"第１弾ではないのですが、有名な方も含めまして、指定管理者といろいろ話合いをしながら進めてまいりたいと考えているところです。６月から早くもスタートを切りたいということでございまして、専門業者の知見を活かしながら進めてまいりたいと考えているところです。","id":"exchange-155"},{"speaker":"あくつ委員","kind":"提案","question":"併せて、品川区は２月に内閣府のＳＤＧｓ未来都市および自治体ＳＤＧｓモデル事業に申請されたと伺っています。具体的にどういう内容で、予算の積算根拠についても説明を求めました。","respondent":"河内環境課長","answer":"東京につきましては、８０年度あたりからペットボトルを売り始めた世代がそのまま大人になり、非常に多くのペットボトルが使われている状況がある。","id":"exchange-156"},{"speaker":"あくつ委員","kind":"質問・要望","question":"申請を２月の末にされたと伺っておりますが、こうしたＣＯ２削減のために、ぜひ発信していただきたいというのが１つです。他自治体の先行事例も参考にしていただきながら、これもぜひ行ってほしいと求めましたが、いかがか尋ねました。","respondent":"河内環境課長","answer":"現状の考え方なのですが、まず多くの区でやられていることはもちろん認識しておりますが、環境が厳しいところがあることも認識しております。そういったところに対しまして、積極的な検討を今後加える必要があるかというところで認識しています。","id":"exchange-157"},{"speaker":"あくつ委員","kind":"質問・要望","question":"最後に、宿場まつりの支援について伺いたいと思います。これは品川区の商業・ものづくり課として、しっかり支援していただきたいという要望がありますけれども、この点についてご答弁を頂きたいと思います。","respondent":"小林商業・ものづくり課長","answer":"例えば補助金の申請というのが当然出てくるわけですけれども、その業務でも１つ、重たい作業になってまいります。そういうものの負荷を軽減しつつ、従来のイベントをにぎやかに大きくやっていただきたいという支援の目的です。","id":"exchange-158"},{"speaker":"あくつ委員","kind":"質問・要望","question":"多いときには１５万人の集客があるということですから、しっかりと支えていただきたいことをお願いいたしまして、私からの質問を終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-159"},{"speaker":"高橋（伸）委員","kind":"質問","question":"３０５ページ、二酸化炭素排出量算定クラウドサービス利用助成、３１５ページ、創業・スタートアップ等支援経費についてお伺いいたします。ＣＯ２排出量算定クラウドサービスの利用助成に対しての狙い、あと対象、効果をお尋ねしたいと思います。","respondent":"河内環境課長","answer":"エコアクション２１の事務局、銀行など、いろいろな情報が様々入ってまいりました。今まで省エネ診断なども含めてやっていたところではあるのですが、さらに商取引の中で優位に立てますということで、このサービスを始めたです。","id":"exchange-160"},{"speaker":"高橋（伸）委員","kind":"確認","question":"今のご説明で、区内の中小企業において、ＣＯ２算定新規事業の利用ニーズがあることは、具体的にアンケートやヒアリングで確認をしたのかどうかというのをお聞きしたいと思います。","respondent":"河内環境課長","answer":"直接事業者に聞いたわけではございませんが、先ほど出てまいりましたエコアクション２１の事務局あるいは銀行などに。こうした動向を考えますと、こういった手助けが要る事業者を支援することによりまして、こういったサービスに至ったです。","id":"exchange-161"},{"speaker":"高橋（伸）委員","kind":"確認","question":"今、これは確認していませんというご説明だったのですけれども、これは、確認していないということは、なぜこのサービスが必要と判断して事業化しようとしているのかというのをお聞きしたいと思います。","respondent":"河内環境課長","answer":"先ほどご説明した流れの中で、今まではマネジメントシステム等で省エネ診断というのを受けていたわけです。こうしたことから、こういうサービスが必要だと判断したところです。","id":"exchange-162"},{"speaker":"高橋（伸）委員","kind":"意見","question":"これは、助成制度の利用者に対して、都が実施する省エネルギー診断の活用を進めるとプレスにも書いてありますけれども、これは義務ではなくて、あくまで勧めるというスタンスだと思うのですけども、その理由はどういう理由なのかをお尋ねしたいと思いますとの意見を述べました。","respondent":"河内環境課長","answer":"一方で、脱炭素社会の実現に向けましては、設備がそのままであったり、例えば低炭素電力の導入などによりＣＯ２自体を減らすことができます。企業はより選択肢が増え、行うことが容易になってくるということから、こういったサービスを進めたです。","id":"exchange-163"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"３点目が、それぞれの創業支援センターがありますけれども、その果たすべき役割をどう捉えているのかということをお尋ねします。強みというのはどういうことなのか、教えてほしいと求めました。","respondent":"小林商業・ものづくり課長","answer":"武蔵小山、西大井でいきますとアントレプレナーということで小中学生を対象としての事業支援ということもやっていきたいと考えております。オリジナリティがあると考えておりますけれども、西大井の中で、それぞれ個性を持った創業支援というのをやっていきたいと考えています。","id":"exchange-164"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"将来ある、未来ある子どもたちのためにぜひやってほしいと求めましたので、どうぞよろしくお願いします。要望で終わらせていただきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-165"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/664001?Template=document&Id=6693#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=3&TermStart=2024-01-01&TermEnd=2024-12-31"}],"sourceMeta":{"pages":0,"characters":132442,"voices":377}}]);
